(window.TNQ=window.TNQ||[]).push({"terms":{"진정소급입법":{"d":"이미 완성된 사실이나 법률관계에 새 법을 거슬러 적용하는 입법이에요. 원칙적으로 금지돼요.","r":["부진정소급입법"]},"부진정소급입법":{"d":"과거에 시작되어 아직 진행 중인 사실에 새 법을 적용하는 입법이에요. 원칙적으로 허용돼요.","r":["진정소급입법"]},"명확성원칙":{"d":"법규정의 내용이 누구나 예측할 수 있을 만큼 분명해야 한다는 원칙이에요.","r":[]},"복수정당제":{"d":"여러 정당이 자유롭게 존재하고 경쟁할 수 있게 보장하는 제도예요.","r":[]},"제도적 보장":{"d":"헌법이 특정 제도 자체를 보호하되 그 핵심만 보장하고 개인에게 주관적 권리를 주지는 않는 방식이에요.","r":[]},"위임조례":{"d":"기관위임사무에 대해 개별 법령의 위임을 받아 지방의회가 제정하는 조례예요.","r":[]},"과잉금지원칙":{"d":"기본권을 제한하는 법률이 목적의 정당성, 방법의 적절성, 피해의 최소성, 법익의 균형성을 갖춰야 한다는 원칙이에요.","r":["피해의 최소성"]},"피해의 최소성":{"d":"같은 목적을 이룰 수 있는 방법 중 기본권을 가장 덜 침해하는 수단을 골라야 한다는 요건이에요.","r":["과잉금지원칙"]},"일반적 행동자유권":{"d":"행복추구권에서 나오는 권리로, 하고 싶은 일을 하고 하기 싫은 일을 하지 않을 자유예요.","r":[]},"헌법불합치":{"d":"법률이 헌법에 어긋나지만 바로 효력을 없애지 않고 개선입법 때까지 존속시키는 결정이에요.","r":[]},"사전검열":{"d":"표현물이 발표되기 전에 행정권이 허가를 목적으로 내용을 심사해 금지하는 제도예요. 헌법이 절대 금지해요.","r":[]},"임의수사":{"d":"강제력을 쓰지 않고 상대방의 동의나 협조를 전제로 하는 수사예요.","r":[]},"영장주의":{"d":"체포·구속·압수·수색 같은 강제처분은 법관이 발부한 영장으로 해야 한다는 원칙이에요.","r":[]},"보안처분":{"d":"형벌과 달리 범죄 위험성이 있는 사람에게 재범 방지와 사회 보호를 위해 하는 처분이에요.","r":[]},"양심실현의 자유":{"d":"마음속 양심을 밖으로 표현하거나 그에 따라 행동하거나 행동하지 않을 자유예요.","r":[]},"직업수행의 자유":{"d":"선택한 직업을 어떤 방식으로 영위할지 정하는 자유로, 직업선택보다 폭넓게 제한될 수 있어요.","r":["직업선택의 자유"]},"직업선택의 자유":{"d":"어떤 직업을 가질지 또는 그만둘지 스스로 정하는 자유예요.","r":["직업수행의 자유"]},"상대적 평등":{"d":"모든 차별을 금하는 것이 아니라 합리적 이유 없는 차별만 금지하는 평등이에요.","r":[]},"공무담임권":{"d":"공직에 취임할 기회를 자의적으로 배제당하지 않을 권리예요.","r":[]},"재판청구권":{"d":"독립된 법원에서 법관에게 헌법과 법률에 따라 공정한 재판을 받을 권리예요.","r":[]},"형사보상":{"d":"구금되었다가 무죄 판결 등을 받은 사람에게 국가가 그 손실을 보상하는 제도예요.","r":[]},"근로3권":{"d":"근로자가 단결하고, 단체교섭을 하고, 단체행동을 할 수 있는 세 가지 권리예요.","r":[]},"불체포특권":{"d":"국회의원이 현행범이 아니면 회기 중 국회 동의 없이 체포·구금되지 않는 특권이에요.","r":[]},"체포동의안":{"d":"회기 중인 국회의원을 체포하거나 구금하려 할 때 국회의 동의를 구하는 안건이에요.","r":["불체포특권"]},"회기계속의 원칙":{"d":"회기 중 의결되지 못한 의안이 회기가 끝나도 폐기되지 않고 다음 회기에 이어지는 원칙이에요.","r":[]},"추가경정예산안":{"d":"예산이 성립한 뒤 사정이 바뀌어 예산을 바꾸려고 정부가 다시 제출하는 예산안이에요.","r":[]},"국가긴급권":{"d":"전쟁이나 재난 같은 비상사태에 대통령이 헌법 질서를 지키려고 발동하는 비상 권한이에요.","r":[]},"위헌법률심판":{"d":"법원이 재판 중 법률이 위헌인지 의심되면 헌법재판소에 심판을 제청하는 제도예요.","r":[]},"진정입법부작위":{"d":"헌법상 입법의무가 있는데도 입법자가 아무 입법도 하지 않은 상태예요.","r":[]},"의제상인":{"d":"상행위를 하지 않아도 상법이 상인으로 간주하는 사람으로, 설비상인과 민사회사가 있어요.","r":[]},"지배인":{"d":"영업주를 대리해 영업에 관한 재판상·재판 외의 모든 행위를 할 수 있는 상업사용인이에요.","r":[]},"유질약정":{"d":"변제기 전에 채무불이행 시 질물의 소유권을 채권자가 취득하기로 하는 약정이에요.","r":[]},"명의대여자":{"d":"자기 이름이나 상호로 타인에게 영업을 허락한 사람이에요. 거래 상대방에게 책임을 질 수 있어요.","r":[]},"영업양도":{"d":"조직화된 영업재산을 동일성을 유지하며 한꺼번에 넘기는 계약이에요.","r":[]},"형해화":{"d":"법인격이 껍데기뿐이어서 회사가 배후자의 개인기업과 다름없게 된 상태예요.","r":[]},"가장납입":{"d":"실제로 자금을 들이지 않고 납입한 것처럼 외형만 꾸미는 납입이에요.","r":[]},"변태설립사항":{"d":"회사 설립 때 자본충실을 해칠 우려가 있어 정관에 적어야 하는 특별한 사항이에요.","r":["현물출자","재산인수"]},"현물출자":{"d":"금전이 아닌 재산으로 하는 출자예요. 변태설립사항이라 검사인의 조사를 받아요.","r":["변태설립사항","검사인"]},"재산인수":{"d":"발기인이 회사 성립을 조건으로 특정 재산을 양수하기로 약정하는 일이에요.","r":["변태설립사항"]},"검사인":{"d":"법원이 선임해 현물출자나 재산인수의 적정성을 조사하는 사람이에요.","r":["현물출자"]},"명의개서":{"d":"주식을 취득한 사람의 이름을 주주명부에 적어 바꾸는 절차예요.","r":["주권"]},"주권":{"d":"주식을 표시하는 유가증권이에요. 교부해야 양도의 효력이 생겨요.","r":["명의개서"]},"자기주식":{"d":"회사가 자기 회사의 주식을 취득해 가지고 있는 주식이에요.","r":[]},"주식매수선택권":{"d":"회사 임직원이 미리 정해진 가격으로 신주를 인수하거나 자기주식을 살 수 있는 권리예요.","r":[]},"종류주식":{"d":"이익배당이나 의결권 같은 권리 내용이 다르게 정해진 주식이에요.","r":[]},"주식매수청구권":{"d":"합병 같은 중요한 결의에 반대한 주주가 회사에 자기 주식을 사 달라고 청구하는 권리예요.","r":["형성권"]},"형성권":{"d":"권리자의 일방적 의사표시만으로 법률관계를 바꾸는 권리예요.","r":["주식매수청구권"]},"대표소송":{"d":"주주가 회사를 대신해 이사의 책임을 묻는 소송이에요. 이득은 회사에 돌아가요.","r":["다중대표소송"]},"다중대표소송":{"d":"모회사 주주가 자회사 이사의 책임을 묻기 위해 제기하는 소송이에요.","r":["대표소송"]},"자기거래":{"d":"이사나 주요주주가 자기 또는 제3자를 위해 회사와 하는 거래로, 이사회 승인이 필요해요.","r":[]},"업무집행지시자":{"d":"이사가 아니면서 이사에게 업무집행을 지시하는 사람으로, 이사와 같은 책임을 져요.","r":[]},"감사위원회":{"d":"이사회 안에 두는 위원회로, 이사의 직무집행을 감사하며 감사를 대신해요.","r":[]},"집중투표":{"d":"이사를 여러 명 뽑을 때 주주가 가진 의결권을 한 사람에게 몰아서 줄 수 있는 선출 방식이에요.","r":[]},"신주인수권":{"d":"회사가 새로 주식을 발행할 때 우선적으로 배정받을 수 있는 권리예요.","r":[]},"전환사채":{"d":"일정 기간 뒤 소지인의 청구로 주식으로 바꿀 수 있는 권리가 붙은 사채예요.","r":["신주인수권"]},"차등감자":{"d":"주주마다 다른 비율로 주식을 줄이는 자본금 감소로, 주주평등원칙에 어긋나 문제가 돼요.","r":[]},"간이합병":{"d":"소멸회사의 총주주가 동의하거나 존속회사가 90% 이상을 가질 때 총회를 이사회 승인으로 대신하는 합병이에요.","r":[]},"청산인":{"d":"해산한 회사의 청산사무를 집행하고 회사를 대표하는 사람이에요.","r":[]},"유한책임회사":{"d":"사원 모두가 출자액 한도에서만 책임지면서도 내부는 조합처럼 운영할 수 있는 회사예요.","r":[]},"인적항변":{"d":"어음채무자가 특정 소지인에 대한 개인적 사정을 이유로 지급을 거절하는 항변이에요.","r":[]},"백지어음":{"d":"어음 요건 일부를 비워 두고 나중에 채우라고 맡긴 채 발행한 어음이에요.","r":[]},"선의취득":{"d":"무권리자에게서 양도받았어도 선의·무중과실로 증권을 취득하면 권리를 얻는 제도예요.","r":[]},"이득상환청구권":{"d":"어음상 권리가 시효 등으로 소멸했을 때 발행인이 얻은 이익의 한도에서 상환을 청구하는 권리예요.","r":[]},"어음보증":{"d":"어음채무를 담보하기 위해 어음 위에 하는 보증이에요. 최고·검색의 항변권이 없어요.","r":[]},"고지의무":{"d":"보험계약자가 계약 때 중요한 사항을 보험자에게 사실대로 알려야 하는 의무예요.","r":[]},"중복보험":{"d":"같은 피보험이익과 사고에 관해 여러 보험자와 체결한 손해보험으로, 합친 금액이 보험가액을 넘는 경우예요.","r":[]},"선박우선특권":{"d":"선박과 관련해 생긴 일정한 채권을 가진 사람이 선박을 경매해 다른 채권자보다 먼저 변제받는 권리예요.","r":[]}},"notes":{"15세 미만자, 심신상실자, 심신박약자의 사망보험은 무효이지만(심신박약자가 의사능력이 있으면 예외) 이들의 상해보험은 유효하고, 단체가 규약에 따라 체결하는 단체보험에는 서면동의가 필요 없음(제732조·제735조의3)":"15세 미만자, 심신상실자, 심신박약자의 사망보험은 무효이지만 이들의 상해보험은 유효해요.","1990년 개정 민법 부칙이 계모자 사이의 법정혈족관계를 소멸시킨 것은 합헌":"계모자 사이의 법정혈족관계를 없앤 1990년 개정 민법 부칙은 합헌으로 판단됐습니다.","1인 주주인 대표이사가 회사의 유일한 영업재산을 처분해도 유효하지만 회사와 주주는 별개의 인격이어서 1인 주주가 회사 자금을 임의로 쓰면 횡령죄가 성립":"1인 주주도 회사와는 별개의 인격이라 회사 자금을 임의로 쓰면 횡령죄가 성립해요.","1인 회사에서는 실제 총회를 열지 않았어도 1인 주주의 의결로 의사록이 작성되었으면 결의가 있었던 것으로 보고, 다른 사람 명의를 빌렸어도 실질적으로 한 사람이 모든 주식을 가지면 같음":"1인 회사는 총회를 열지 않았어도 1인 주주가 의결해 의사록을 작성했다면 결의가 있었던 것으로 인정합니다.","1주 1의결권 원칙은 강행규정, 정관이나 총회 결의로 변경 불가(제369조 제1항)":"1주 1의결권 원칙은 강행규정이라 정관이나 총회 결의로 바꿀 수 없어요.","2023년 개정 전기통신사업법은 명칭을 통신이용자정보로 변경":"2023년 개정 전기통신사업법은 통신자료라는 명칭을 통신이용자정보로 바꿨어요.","2024년 개정(2025.1.31. 시행)으로 지점 소재지 등기는 없어짐":"2024년 개정으로 2025.1.31.부터 합병등기도 지점 소재지 등기는 없어졌어요.","2024년 개정(2025.1.31. 시행)으로 지점 소재지 등기 폐지":"2024년 개정으로 2025.1.31.부터 지점 소재지 등기가 폐지됐어요.","2025.7.22. 공포·시행 개정 상법은 이사가 회사 및 주주를 위해 직무를 충실히 수행하도록 정함":"개정 상법은 이사가 회사뿐 아니라 주주를 위해서도 직무를 충실히 해야 한다고 정했고, 2025.7.22. 공포·시행되었습니다.","2025년 개정으로 상장회사 사외이사는 독립이사로 변경":"2025년 개정으로 상장회사의 사외이사가 독립이사로 바뀌었어요.","2026.9.10. 시행, 정관으로 집중투표를 배제할 수 없음(제542조의8·제542조의7·제542조의12)":"2026.9.10. 시행이며, 이때부터 정관으로 집중투표를 배제할 수 없어요.","2026년 3월 12일 개정 헌법재판소법은 확정된 법원의 재판이 헌재 결정에 반하거나, 적법한 절차를 거치지 않았거나, 헌법과 법률을 위반한 것이 명백하여 기본권을 침해한 경우 재판에 대한 헌법소원을 허용(제68조 제3항)":"개정된 헌법재판소법은 확정된 법원 재판이 헌재 결정에 반하거나 명백히 위법해 기본권을 침해한 경우 재판소원을 허용해요.","2026년 3월 개정 법원조직법에 따라 2028년 3월부터 해마다 4명씩 늘어 26명(법원조직법 제4조 제2항)":"2026년 3월 개정 법원조직법으로 2028년 3월부터 해마다 4명씩 늘어 최종적으로 26명이 됩니다.","3·1정신은 해석의 기준이나 개별 기본권이 곧바로 나오지는 않음":"3·1정신은 헌법을 해석하는 기준일 뿐, 이것만으로 개별 기본권이 생기지는 않아요.","3년이 지나면 청산이 종결된 것으로 봄(제520조의2)":"해산 간주 후 3년이 지나도록 계속하지 않으면 청산이 종결된 것으로 처리합니다.","3명 이상 이사로 구성, 사외이사가 3분의 2 이상":"감사위원회는 3명 이상의 이사로 구성하고 사외이사가 3분의 2 이상이어야 해요.","각 회사의 주주·이사·감사·감사위원회 위원·청산인만 교환일부터 6개월 안에 소로 주장 가능":"교환무효의 소를 제기할 수 있는 사람은 각 회사의 주주·이사·감사·감사위원회 위원·청산인이며 기간은 교환일부터 6개월입니다.","각 회사의 주주·이사·감사·청산인·파산관재인·합병 미승인 채권자만 주장 가능":"합병무효는 각 회사의 주주·이사·감사·청산인·파산관재인과 합병을 승인하지 않은 채권자만 주장할 수 있어요.","간통죄와 혼인빙자간음죄는 성적 자기결정권 침해로 위헌":"성적 자기결정권을 지나치게 제한해 간통죄와 혼인빙자간음죄 조항이 위헌 판단을 받았습니다.","감사는 선임결의와 승낙으로 지위 취득":"감사는 선임결의와 본인의 승낙으로 지위를 얻어요.","감사 선임 시 의결권 없는 주식을 제외한 발행주식총수의 3% 초과분은 의결권 없음":"감사를 선임할 때는 의결권 없는 주식을 뺀 발행주식총수의 3%를 넘는 주식은 의결권이 없어요.","감사원은 대통령 소속이지만 직무상 독립이고 국무총리의 통할을 받지 않으며 원장을 포함한 5인 이상 11인 이하의 감사위원으로 구성":"감사원은 대통령 소속이어도 직무에서는 독립되어 총리의 통할을 받지 않고, 5인 이상 11인 이하의 위원이 있습니다.","감자 결의에 하자가 있어도 감자의 효력이 생긴 뒤에는 감자무효의 소로만 다툴 수 있고, 이 소는 주주·이사·감사·청산인·파산관재인·감자를 승인하지 않은 채권자가 변경등기일부터 6개월 안에 제기(제445조)":"감자의 효력이 생긴 뒤에는 변경등기일부터 6개월 안에 감자무효의 소로만 다툴 수 있어요.","강제추행·카메라등이용촬영 유죄 확정자를 신상정보 등록대상으로 한 조항은 합헌":"강제추행·카메라등이용촬영으로 유죄가 확정된 사람을 신상정보 등록 대상으로 삼은 조항은 합헌이에요.","강화, 중대한 재정적 부담, 입법사항에 관한 조약":"강화, 중대한 재정적 부담, 입법사항에 관한 조약도 국회 동의 대상이에요.","같은 사유로 형사소송이 진행 중이면 심판절차를 정지할 수 있고(헌법재판소법 제51조), 결정 선고 전에 파면되면 청구를 기각하며(제53조 제2항), 임기만료로 퇴직하면 심판의 이익이 없어 각하":"결정 선고 전에 파면되면 청구를 기각하고, 임기만료로 퇴직하면 심판의 이익이 없어 각하해요.","개별 법률에 근거가 있으면 부담금관리 기본법 별표에 빠져 있다는 이유만으로 부과가 금지되지는 않음":"개별 법률이 근거가 되면 부담금관리 기본법 별표에 없어도 부과할 수 있습니다.","개별사건법률도 합리적 이유로 정당화되면 합헌일 수 있음":"특정 사건만 겨냥한 개별사건법률도 합리적 이유로 정당화되면 합헌일 수 있어요.","개업준비행위는 상대방이 영업의사를 알 수 있으면 최초의 보조적 상행위":"영업을 준비하는 행위는 상대방이 영업 의사를 알 수 있다면 첫 번째 보조적 상행위로 봅니다.","개인인 근로자만 주체, 노동조합은 주체가 아님":"근로의 권리를 가지는 쪽은 근로자 개인이고 노동조합은 그 주체가 아닙니다.","거래 내용과 절차가 공정해야 함":"자기거래는 내용과 절차가 모두 공정할 때에만 허용됩니다.","거래상 일반적이어서 예상할 수 있는 사항이나 법령을 되풀이한 사항은 설명할 필요가 없고, 판례는 오토바이 운전 시 보상 제한과 가족운전자 한정특약은 설명대상으로, 보험금 청구서류 위조 시 청구권 상실 조항은 설명대상이 아니라고 봄":"거래상 일반적이어서 예상할 수 있는 사항이나 법령을 되풀이한 사항은 보험자가 설명할 필요가 없어요.","거래소 시세가 있는 물건은 직접 매도인이나 매수인이 될 수 있음(제107조)":"거래소 시세가 있는 물건은 위탁매매인이 직접 매도인이나 매수인이 될 수 있어요.","검사인 조사는 공인된 감정인의 감정으로 갈음할 수 있고 감정인도 결과를 법원에 보고":"검사인의 조사를 공인 감정인의 감정으로 바꿀 수 있고, 감정인은 결과를 법원에 보고합니다.","검사·통지의 증명책임은 매수인에게 있음":"검사와 통지를 했다는 증명책임은 매수인에게 있어요.","결의 없이 한 거래는 상대방이 알았거나 중과실로 몰랐을 때만 무효(2021년 전원합의체)":"2021년 전원합의체 판결은 이사회 결의 없는 거래도 상대방이 알았거나 중과실로 모른 경우에만 무효라고 보았습니다.","결의일부터 20일 안에 청구, 주식분할에는 매수청구권 없음":"매수청구는 결의일부터 20일 안에 해야 하고, 주식분할은 매수청구권의 대상이 아닙니다.","결의일부터 2년 이상 재임·재직해야 행사할 수 있고 본인 귀책이 없는 퇴임이어도 마찬가지이며, 양도할 수 없으나 상속인은 행사할 수 있음(제340조의4)":"결의일부터 2년 이상 재임·재직해야 행사할 수 있고, 양도는 안 되지만 상속인은 행사할 수 있어요.","경과보고서를 보내지 못하면 임명권자는 10일 이내의 기간을 정해 송부 요청 가능(인사청문회법 제6조)":"경과보고서를 보내지 않으면 임명권자가 10일 이내의 기간을 정해 보내 달라고 요청할 수 있어요.","경영권 분쟁 중 지배권 방어를 위한 제3자배정은 주주의 신주인수권 침해이고 지배구조에 중대한 변화가 생기면 무효이며, 이 법리는 신주인수권부사채·전환사채에도 적용":"경영권 분쟁 중 방어 목적의 제3자배정은 신주인수권을 해치고 지배구조를 크게 바꾸면 무효이며, 사채 발행에도 같습니다.","경제적 대가를 받고 변호사를 광고·소개하는 행위 금지 부분은 과잉금지원칙 위반":"경제적 대가를 받고 변호사를 소개하거나 광고하지 못하게 한 부분은 과잉금지원칙을 어깁니다.","경제질서는 개인과 기업의 경제상 자유와 창의 존중을 기본으로 하는 사회적 시장경제질서이고, 제119조 제2항의 경제민주화는 기본권을 제한하는 국가행위를 정당화하는 규범":"경제질서는 개인과 기업의 자유와 창의를 존중하는 사회적 시장경제질서이고, 경제민주화 조항은 기본권 제한을 정당화하는 규범이에요.","경제질서는 사유재산제와 자유경쟁 바탕의 사회적 시장경제질서":"경제질서의 바탕은 사유재산제와 자유경쟁이며, 이를 사회적 시장경제질서라고 해요.","계약 당시 사고가 이미 발생했으면 무효이지만 당사자 쌍방과 피보험자가 모두 몰랐으면 유효(제644조)":"계약을 맺을 때 이미 사고가 났다면 무효지만, 보험자와 보험계약자, 피보험자 모두 몰랐다면 유효합니다.","계약 종료 후 보상청구권은 종료 전 5년간 평균연보수액 한도, 종료일부터 6개월 안에 행사(제91조·제92조의2)":"계약 종료 후 보상청구권은 종료 전 5년간 평균연보수액 한도이며, 종료일부터 6개월 안에 행사해야 해요.","계엄을 선포하면 대통령은 지체 없이 국회에 통고하면 되고 승인은 필요 없으며 국회가 재적의원 과반수의 찬성으로 해제를 요구하면 대통령은 해제해야 함(헌법 제77조)":"계엄 선포는 국회에 지체 없이 통고만 하면 되고, 국회가 재적의원 과반수로 해제를 요구하면 대통령은 해제해야 해요.","고의·과실로 사실과 다른 사항을 등기한 자는 선의의 제3자에게 대항 불가(제39조)":"고의·과실로 사실과 다른 사항을 등기한 사람은 선의의 제3자에게 그 사실이 아님을 주장할 수 없어요.","고의·중과실과 경업·기회유용·자기거래에는 면제 적용 안 됨":"고의·중과실과 경업·기회유용·자기거래에는 정관에 따른 면제가 적용되지 않아요.","공고 · 대통령이 20일 이상 공고":"대통령이 개정안을 20일 이상 국민에게 알리는 단계예요.","공권력은 국가기관·공공단체의 고권적 작용으로 국민의 법적 지위를 직접 불리하게 변화시키는 것이어야 하고, 권력적 사실행위(개성공단 전면중단, 경찰 차벽 설치)는 대상이 되지만 국가기관 사이의 내부행위인 법률안 제출과 대통령기록물 이관, 국민을 직접 구속하지 않는 예산, 구청장의 토론대회 공모 같은 사법상 행위는 대상이 아님":"공권력은 국민의 법적 지위를 직접 불리하게 바꾸는 고권적 작용이어야 하며 법률안 제출과 예산은 대상이 아닙니다.","공동해손은 위험을 면한 선박·적하 가액과 운임의 반액에 비례해 분담하고, 손해 구간이 불분명한 복합운송에서는 운송거리가 가장 긴 구간에 적용되는 법에 따름(제866조·제816조)":"공동해손은 위험을 면한 선박·적하 가액과 운임의 반액에 비례해 분담해요.","공무원 신분의 부당한 박탈과 직무의 부당한 정지도 보호영역":"공무원 신분을 부당하게 박탈당하거나 직무를 부당하게 정지당하지 않을 권리도 보호영역이에요.","공무원은 정당의 발기인·당원이 될 수 없음":"정당의 발기인이나 당원이 되는 것은 공무원에게 허용되지 않습니다.","공무원인 근로자는 법률이 정하는 자만 근로3권 보유(헌법 제33조 제2항)":"공무원인 근로자는 법률이 정하는 사람만 근로3권을 가질 수 있어요.","공무원 지위 이용 선거범죄의 공소시효 10년":"공무원 지위를 이용한 선거범죄의 공소시효를 10년으로 둔 것도 합헌이에요.","공정한 재판을 받을 권리는 명문 규정은 없으나 보장(헌법 제27조)":"공정한 재판을 받을 권리는 조문에 적혀 있지 않아도 헌법 제27조에서 인정합니다.","공직취임 기회를 자의적으로 배제당하지 않을 권리":"공무담임권이란 공직에 오를 기회를 자의적으로 막히지 않을 권리입니다.","과거사정리법상 국가폭력 사건에도 재심청구권자를 배우자·직계친족·형제자매로 한정한 조항":"과거사정리법상 국가폭력 사건의 재심은 배우자·직계친족·형제자매만 청구할 수 있게 한 조항입니다.","과외교습을 전면 금지한 법률은 위헌":"과외교습을 전면 금지한 법률은 위헌으로 판단됐어요.","과잉금지원칙 안에서 제한 가능":"종교적 행위는 과잉금지원칙의 한계 안에서 제한할 수 있어요.","광고물과 엄격한 의미의 음란표현도 언론·출판의 자유의 보호영역":"광고물과 음란표현도 엄격한 의미의 것이라면 언론·출판의 자유 보호 범위 안에 있습니다.","교도시설 수용 중인 미결수용자의 건강보험급여 정지는 합헌":"교도시설에 있는 미결수용자의 건강보험급여를 멈추게 하는 것은 헌법에 어긋나지 않습니다.","교육훈련 소집 예비군에게 동원훈련 예비군에 준하는 보상을 할 의무는 없음":"교육훈련 소집 예비군에게 동원훈련 예비군과 같은 수준으로 보상할 의무는 없어요.","교환 대가로 쓰려고 취득한 모회사 주식이 남으면 효력발생일부터 6개월 안에 처분":"교환 대가로 쓰려고 사 둔 모회사 주식이 남았다면 효력발생일부터 6개월 안에 팔아야 합니다.","구금되었던 피고인뿐 아니라 피의자에게도 인정":"구금당했던 사람이면 피고인뿐 아니라 피의자도 형사보상을 받을 수 있습니다.","구성원 과반수 출석으로 개의하고 출석구성원 3분의 2 이상의 찬성으로 의결하며 국무위원 대신 출석한 차관은 발언만 할 수 있고 표결에는 참가하지 못함":"국무위원 대신 나온 차관은 발언만 할 수 있고 표결에는 참가할 수 없어요.","구체적 내용과 행사 종기는 주주총회 결의가 정한 본질을 해치지 않는 범위에서 회사와 대상자의 계약으로 정할 수 있음":"구체적 내용과 행사 종기는 총회 결의의 본질을 해치지 않는 한 회사와 대상자가 계약으로 채울 수 있습니다.","국가기관과 공법인은 기본권의 수범자":"국가기관과 공법인은 기본권을 누리는 쪽이 아니라 기본권을 지켜야 하는 수범자예요.","국가긴급권은 위기 극복이라는 소극적 목적으로 필요한 최소한도에서만 발동해야 하고, 법원과 헌재는 사후에 그 위헌·위법을 심사할 수 있음":"국가긴급권은 위기를 극복하는 소극적 목적에 필요한 최소한도로만 쓰며, 법원과 헌법재판소가 사후에 위헌·위법을 심사할 수 있어요.","국가는 경제적 약자의 실질적 평등교육을 위해 적극적 정책을 펴야 함":"국가는 경제적 약자도 실질적으로 평등하게 교육받도록 적극적인 정책을 펴야 해요.","국가에 급부를 요구하는 권리가 아님":"행복추구권으로 국가에 급부를 달라고 요구할 수는 없어요.","국가에 대한 직장존속보장청구권은 근로의 권리에서 나오지 않음":"국가에 직장을 계속 보장해 달라는 청구는 근로의 권리에서 나오지 않아요.","국가와 국민 모두 환경보전을 위해 노력해야 함(헌법 제35조 제1항)":"환경보전을 위해 국가와 국민이 모두 노력해야 한다고 헌법 제35조 제1항이 정해요.","국가유공자 자녀나 보훈보상대상자 부모 중 나이 많은 사람을 선순위로 한 조항":"나이가 많은 유족을 선순위로 정한 국가유공자 자녀·보훈보상대상자 부모 순위 조항이 평등에 어긋난 사례입니다.","국가의 간섭 없이 행복을 추구하는 자유권":"행복추구권은 국가가 간섭하지 않고 개인이 행복을 추구하도록 두는 자유권이에요.","국가인권위원회는 위원장 1명과 상임위원 3명을 포함한 11명의 위원으로 구성하고, 특별한 규정이 없으면 재적위원 과반수의 찬성으로 의결(국가인권위원회법 제5조 제1항·제13조 제1항)":"국가인권위원회는 11명의 위원으로 구성하며, 특별한 규정이 없으면 재적위원 과반수 찬성으로 의결해요.","국·공립 사대 졸업자 교원 우선채용":"국·공립 사범대 졸업자를 교원 임용에서 우선하는 것도 평등원칙 위반으로 본 사례예요.","국내 수표는 발행일부터 10일 안에 제시해야 하고 발행일 전에 제시해도 제시한 날에 지급해야 하며 수표 상환청구권은 제시기간이 지난 후 6개월이면 시효로 소멸(수표법 제28조·제29조·제51조)":"국내 수표는 발행일부터 10일 안에 제시해야 하고, 상환청구권은 제시기간이 지난 후 6개월이면 시효로 소멸해요.","국립교육대학교 등이 수시모집에서 검정고시 출신자의 지원을 일률 제한한 것은 위헌":"수시모집에서 검정고시 출신이라는 이유만으로 지원을 일률 막은 국립교육대학교 등의 조치는 위헌입니다.","국무위원은 국무총리의 제청으로 대통령이 임명하고, 군인은 현역을 면한 후가 아니면 국무총리나 국무위원이 될 수 없으며 국무총리는 국무위원의 해임을 대통령에게 건의할 수 있음(헌법 제87조)":"국무위원은 국무총리의 제청으로 대통령이 임명하고, 현역 군인은 총리나 국무위원이 될 수 없어요.","국무총리나 행정각부의 장은 법률·대통령령의 위임 또는 직권으로 총리령·부령을 발할 수 있고, 대통령은 비상계엄하에서도 국무총리·국무위원 등의 직을 겸할 수 없음":"국무총리나 행정각부의 장은 위임이나 직권으로 총리령·부령을 발할 수 있고, 대통령은 비상계엄 중에도 총리 등의 직을 겸할 수 없어요.","국무총리는 대통령의 보좌기관이고, 국무총리가 통할하는 행정각부에 모든 행정기관이 포함되지는 않음":"국무총리는 대통령을 보좌하는 기관이며, 총리가 통할하는 행정각부에 모든 행정기관이 들어가지는 않아요.","국무총리 해임건의 발의와 일반 탄핵소추 발의는 모두 재적의원 3분의 1 이상":"국무총리 해임건의나 일반 탄핵소추를 발의하려면 재적의원의 3분의 1 이상이 필요합니다.","국무회의는 대통령·국무총리와 15인 이상 30인 이하의 국무위원으로 구성하고, 대통령이 의장, 국무총리가 부의장이며, 행정부 최고의 정책심의기관이지만 의결기관은 아님(헌법 제88조)":"국무회의는 정책을 심의하는 기관일 뿐 의결기관이 아니며, 대통령이 의장이고 국무총리가 부의장이에요.","국민연금 강제가입과 자경농지 양도세 면제를 농지소재지 거주자로 제한한 것은 합헌":"국민연금 강제가입과 자경농지 양도세 면제의 거주지 제한은 헌법에 어긋나지 않는다고 판단했습니다.","국민 전체의 봉사자인 공무원(대통령 포함)":"대통령까지 포함하는 넓은 뜻의 공무원은 국민 전체에 대한 봉사자입니다.","국민투표 · 의결 후 30일 이내 · 국회의원선거권자 과반수의 투표와 투표자 과반수의 찬성":"의결 후 30일 이내에 국민투표를 하고, 선거권자 과반수 투표에 투표자 과반수 찬성이 필요합니다.","국회가 별도 조사 없이 소추를 의결해도 위법하지 않고, 국가기관에 대한 탄핵소추절차에는 적법절차원칙이 직접 적용되지 않음":"소추 의결 전에 따로 조사하지 않아도 위법이 아니며, 국가기관 탄핵소추에는 적법절차원칙이 직접 미치지 않습니다.","국회노동위원회, 직장의료보험조합, 지방자치단체는 기본권 주체가 아님":"국회노동위원회와 직장의료보험조합, 지방자치단체는 기본권을 주장할 수 없는 기관입니다.","국회는 20일 이내에 청문을 마쳐야 함":"국회는 인사청문을 20일 이내에 마쳐야 해요.","국회는 개시 30일 전까지 의결(헌법 제54조 제2항)":"국회는 회계연도 개시 30일 전까지 예산안을 의결해야 해요.","국회는 정부의 동의 없이 지출예산 각항의 금액을 늘리거나 새 비목을 설치할 수 없음":"정부가 동의하지 않으면 국회는 지출예산 각 항의 금액을 올릴 수도, 새 비목을 세울 수도 없습니다.","국회·법원·헌법재판소 소속 공무원은 직무감찰 대상이 아니고, 비위를 밝혀도 직접 징계할 수 없으며 지방자치단체 자치사무에는 합목적성 감사도 할 수 있음":"국회·법원·헌법재판소 소속 공무원은 직무감찰 대상이 아니며, 감사원은 비위를 밝혀도 직접 징계할 수 없어요.","국회에서 직무상 행한 발언과 표결에 관해 국회 외에서 책임지지 않음":"국회의원은 국회에서 직무상 한 발언과 표결에 대해 국회 밖에서 책임지지 않아요.","국회 의결 · 공고된 날부터 60일 이내 · 재적의원 3분의 2 이상 찬성":"공고된 날부터 60일 이내에 재적의원 3분의 2 이상이 찬성해야 의결됩니다.","국회의원선거에서 의석을 얻지 못하고 유효투표총수의 100분의 2 미만을 얻은 정당":"총선에서 의석을 못 얻고 유효투표총수의 100분의 2 미만을 얻은 정당이 대상이에요.","국회의원에게만 후원회를 허용하고 지방의회의원을 제외한 조항":"국회의원에게만 후원회를 두게 하고 지방의회의원은 빼 놓은 조항도 평등원칙 위반이에요.","국회의원은 조약 체결·비준 동의권 침해를 이유로 대통령을 상대로 권한쟁의심판을 청구할 수 없음":"조약 체결·비준 동의권이 침해됐다는 이유로 국회의원이 대통령을 상대로 권한쟁의심판을 청구할 수는 없어요.","국회의원의 법률안 심의·표결권은 국회뿐 아니라 의원 각자에게 보장":"법률안을 심의하고 표결할 권리는 국회라는 기관만이 아니라 의원 한 명 한 명에게도 있습니다.","국회의원의 임기가 만료되면 폐기(제51조 회기계속의 원칙)":"다만 국회의원의 임기가 끝나면 남은 의안은 폐기되며, 이를 회기계속의 원칙이라 해요.","국회의장 공관 100미터 이내 집회 일률 금지 조항은 헌재가 위헌으로 봄":"공관 100미터 이내라는 이유로 집회를 모두 막은 조항은 헌재에서 위헌 판단을 받았습니다.","국회의장 선출과 계엄해제 요구는 모두 재적의원 과반수":"국회의장 선출과 계엄해제 요구는 재적의원 과반수 찬성으로 이루어집니다.","군사법원도 제청할 수 있고 대법원 외의 법원은 대법원을 거쳐 제청하며 제청하면 당해 재판은 정지되지만 긴급하면 종국재판 외의 소송절차는 진행할 수 있음(헌법재판소법 제41조·제42조)":"군사법원도 위헌법률심판을 제청할 수 있고, 제청하면 당해 재판은 정지되지만 긴급하면 소송절차는 진행할 수 있어요.","군사법원의 상고심은 대법원이 관할(제110조 제2항)":"군사법원의 상고심은 대법원이 맡아요.","규율이 직업수행에서 직업선택으로 갈수록 입법재량이 좁아지고, 주관적 사유보다 객관적 허가조건에 따른 선택 제한이 가장 심각해 엄격한 비례원칙이 적용(경비업 겸영 금지)":"직업선택 쪽으로 갈수록 입법재량이 좁아지며, 객관적 허가조건에 따른 선택 제한이 가장 무거워 엄격한 비례원칙을 적용해요.","균등하게 교육받을 권리를 침해할 수는 없음":"대학의 입시 자율이 있어도 그 결정이 균등하게 교육받을 권리를 해칠 수는 없습니다.","그 밖에는 합리적 이유가 있는지만 보는 자의심사":"나머지 경우에는 합리적 이유가 있는지만 따지는 느슨한 심사를 합니다.","그 밖의 법관은 대법관회의의 동의를 얻어 대법원장이 임명(헌법 제104조)":"그 밖의 법관은 대법관회의의 동의를 얻어 대법원장이 임명해요.","그 사원은 퇴사한 것으로 봄(제194조)":"원인이 있던 사원은 나간 사원으로 간주해 처리합니다.","그 의결권 수는 출석 의결권 수에 산입하지 않음":"그 주주의 의결권 수는 출석한 의결권 수에도 넣지 않아요.","그 자체에서 구체적 기본권이 도출되지는 않음":"지도원리 자체에서는 구체적인 기본권이 바로 도출되지 않아요.","그 정당의 등록을 취소하는 조항":"의석 확보에 실패하고 득표율도 낮은 정당의 등록을 없애도록 정한 조항이에요.","그 후 3년 안에는 특별결의로 계속 가능":"해산 간주 후 3년 안에는 특별결의로 회사를 계속할 수 있어요.","근로자 보호의무 위반에 따른 손해배상채권은 10년의 민사시효":"근로자 보호의무를 어겨 생긴 손해배상채권은 10년 시효가 적용되는 민사 채권입니다.","금융회사 종사자에게 타인의 금융거래정보 요구를 일률 금지·처벌하는 조항은 위헌":"타인의 금융거래정보를 달라는 요구를 예외 없이 금지하고 처벌하면 지나치다고 보아 위헌입니다.","급식비 일부를 학부모가 부담하게 해도 무상원칙에 위배되지 않음":"급식비 일부를 학부모가 내게 해도 의무교육 무상원칙에 어긋나지 않아요.","급식은 의무교육의 핵심 항목이 아님":"급식은 의무교육에서 반드시 지켜야 할 핵심 요소로 보지 않습니다.","기간 안에 이의를 내지 않은 채권자는 합병을 승인한 것으로 봄(제527조의5)":"정해진 기간 동안 이의를 제출하지 않은 채권자는 합병에 동의한 것으로 취급합니다.","기관위임사무는 개별 법령의 위임이 있을 때만 위임조례로 정함":"기관위임사무는 국가 사무라 개별 법령의 위임이 있어야 위임조례로 정할 수 있어요.","기업의 자유와 직업교육장 선택의 자유는 포함되나, 합당한 보수를 받을 권리와 국가에 대한 직장존속보장청구권은 직업의 자유에서 나오지 않음":"기업의 자유와 직업교육장 선택의 자유는 직업의 자유에 들어가나, 합당한 보수 청구와 직장존속보장 청구는 들어가지 않아요.","기존회사가 채무를 면탈하려고 실질이 같은 신설회사를 세웠다면 채권자는 두 회사 어느 쪽에도 이행을 청구할 수 있지만 판결의 기판력과 집행력을 신설회사로 확장할 수는 없음":"채무를 피하려고 실질이 같은 신설회사를 세우면 채권자는 두 회사 어느 쪽에도 청구할 수 있지만 기판력은 확장되지 않아요.","긴급명령이 국회의 승인을 얻지 못하면 그때부터 효력을 잃고, 긴급재정경제명령은 법률과 같이 위헌법률심판과 헌법소원의 대상":"국회 승인을 못 받은 긴급명령은 그때부터 효력이 사라지고, 긴급재정경제명령은 위헌법률심판과 헌법소원으로 다툴 수 있습니다.","남자에게만 병역의무를 부과한 조항":"남자에게만 병역의무를 지운 조항은 평등원칙에 어긋나지 않는 합헌 판례예요.","내부관계 규정은 원칙적으로 임의규정":"내부관계 규정은 원칙적으로 임의규정이라 정관으로 달리 정할 수 있어요.","내용이 현저히 불합리해 재량을 명백히 일탈한 경우":"입법 내용이 현저히 불합리해 재량을 명백히 벗어난 경우가 둘째예요.","노동조합 설립신고서 반려 제도는 자주성을 확인하는 절차":"노동조합 설립신고서 반려는 노조가 자주성을 갖췄는지 확인하는 절차입니다.","노동조합의 적극적 단결권은 근로자의 단결하지 아니할 자유보다 중시":"노조의 적극적 단결권과 근로자 개인의 소극적 단결권이 부딪히면 앞의 것에 무게를 둡니다.","노역장유치와 가정폭력 사회봉사명령에는 행위시법 적용":"형벌에 준하는 처분이므로 노역장유치와 가정폭력 사회봉사명령도 행위 당시 법을 적용합니다.","능력 외의 성별·종교·경제력·사회적 신분으로 취학 기회를 차별하는 것은 원칙적 금지":"수학능력이 아닌 성별, 종교, 경제력, 사회적 신분을 이유로 취학 기회를 차별하는 일은 금지가 원칙입니다.","능력은 수학능력을 말함(헌법 제31조 제1항)":"여기서 능력은 일할 능력이 아니라 수학능력을 뜻해요.","다른 구제수단이 남아 있지 않을 때만 행사 가능(보충성)":"보충성 때문에 다른 구제수단이 모두 막혔을 때에만 저항권을 쓸 수 있습니다.","다른 법률에 구제절차가 있으면 이를 모두 거친 후에 헌법소원을 청구해야 하고, 손해배상·손실보상 청구, 진정, 수용자 청원은 여기의 구제절차가 아니며, 종국결정 전에 구제절차를 거치면 하자가 치유":"헌법소원은 다른 구제절차를 거친 뒤에 내야 하고, 손해배상 청구나 진정은 그 구제절차에 해당하지 않습니다.","다른 사원의 동의 없이 회사 영업부류의 거래 불가":"사원은 다른 사원의 동의 없이 회사 영업부류에 속하는 거래를 할 수 없어요.","단결권은 근로자 개인뿐 아니라 근로자단체도 주체":"근로자 개인은 물론 근로자들의 단체도 단결권을 주장할 수 있는 주체입니다.","단독판사와 합의부의 심판권 분배는 입법자가 정할 사항":"단독판사와 합의부 중 누가 심판할지 나누는 일은 입법자가 정할 사항이에요.","단순한 재산상 이익의 기대, 영업으로 얻을 영리획득의 기회, 개발제한구역 토지의 지가상승 기대는 재산권이 아님":"재산상 이익의 기대나 영업상 영리 획득의 기회, 지가상승 기대는 재산권으로 보호되지 않아요.","대금을 받기 전까지 그 주주는 주주 지위 유지":"매수 대금을 받기 전에는 해당 주주의 주주 지위가 그대로 이어집니다.","대리권 제한은 선의의 제3자에게 대항 불가, 제3자의 악의·중과실은 영업주가 증명":"선의의 제3자는 지배인의 대리권 제한을 이유로 거절당하지 않고, 상대방의 악의·중과실은 영업주가 입증합니다.","대리인은 대리권 증명 서면 또는 전자문서(2025년 개정)를 제출, 서면은 원본":"대리인은 대리권을 증명하는 서면 또는 전자문서를 내야 하며, 서면은 원본이어야 해요.","대리인 자격을 주주로 한정하는 정관 유효, 포괄적 위임과 재위임 허용":"대리인을 주주로 제한한 정관은 유효하고, 포괄적으로 위임하거나 다시 맡기는 것도 허용됩니다.","대법관으로 구성, 대법원장이 의장":"대법관회의는 대법관으로 구성하고 대법원장이 의장을 맡아요.","대법관은 대법원장의 제청과 국회의 동의를 거쳐 대통령이 임명":"대법관은 대법원장이 제청하고 국회가 동의하면 대통령이 임명해요.","대법관의 수는 현재 대법원장을 포함하여 14명":"현재 대법관의 수는 대법원장을 포함해 14명이에요.","대법관 전원의 3분의 2 이상의 합의체에서 행사하는 것이 원칙":"대법원의 심판권은 대법관 전원의 3분의 2 이상으로 이루어진 합의체가 행사하는 것이 원칙이에요.","대법관 전원의 3분의 2 이상 출석과 출석인원 과반수의 찬성으로 의결(법원조직법 제16조)":"정족수는 대법관 전원의 3분의 2 이상 출석이고, 의결은 출석한 인원 과반수 찬성으로 합니다.","대법원에는 대법관이 아닌 법관도 둘 수 있음":"대법원 구성원 중에는 대법관이 아닌 법관을 포함시킬 수도 있습니다.","대법원이 사실확정도 하므로 재판청구권 침해 아님":"대법원이 사실 확정까지 직접 하기 때문에 재판청구권 침해가 아니라고 판단합니다.","대법원이 최고법원이라고 해서 모든 사건을 상고심으로 관할해야 하는 것은 아님":"대법원은 최고법원이지만 모든 사건의 상고심을 반드시 맡아야 하는 것은 아닙니다.","대법원장과 대법관의 임기는 6년":"대법원장과 대법관의 임기는 똑같이 6년이에요.","대법원장·대법관·헌법재판소장·국무총리·감사원장 임명에도 국회의 동의 필요":"이 다섯 자리는 임명하기 전에 국회의 동의를 먼저 받아야 합니다.","대법원장은 국회의 동의를 얻어 대통령이 임명":"대법원장 임명에는 국회 동의 절차가 먼저이고, 임명 자체는 대통령이 합니다.","대법원장은 중임할 수 없으나 대법관은 연임 가능":"대법원장은 한 번만 하고 다시 못 하지만 대법관은 연임할 수 있어요.","대법원장이 궐위되거나 직무를 수행할 수 없으면 선임대법관이 권한 대행(법원조직법 제13조 제3항)":"대법원장이 궐위되거나 직무를 못 하면 선임대법관이 권한을 대행해요.","대여자가 상인이 아니거나 차용자 영업이 상행위가 아니어도 같음(제24조)":"대여자가 상인이 아니거나 차용자의 영업이 상행위가 아니어도 연대책임은 같아요.","대체복무제 없이 군사훈련을 수반하는 병역만 규정한 병역종류조항은 침해의 최소성 위반":"대체복무제가 없어 군사훈련을 받는 병역만 있는 조항은 침해의 최소성을 지키지 못합니다.","대통령령의 위헌 여부가 재판의 전제가 된 때에도 법원은 헌재에 제청하지 않음":"대통령령이 위헌인지가 재판의 전제여도 법원은 헌법재판소에 제청하지 않고 스스로 판단해요.","대통령선거 무효소송에서 무효 판결을 할 때도 가중된 정족수 없이 과반수의 찬성으로 함":"대통령선거 무효소송에서 무효로 판결할 때에도 정족수를 높이지 않고 과반수 찬성이면 됩니다.","대통령선거 후보자는 등록 후 개표종료 시까지 사형·무기·장기 7년 이상의 죄가 아니면 현행범인이 아닌 한 체포·구속되지 않음":"대통령선거 후보자는 현행범인이 아니면 사형·무기·장기 7년 이상의 죄가 아닌 한 개표종료 시까지 체포·구속되지 않아요.","대통령은 국회에서 의결된 법률안을 이송받은 날부터 15일 이내에 공포하고, 그 기간 안에 공포나 재의 요구를 하지 않으면 법률로 확정":"대통령은 이송받은 법률안을 15일 이내에 공포해야 하며, 공포도 재의 요구도 없이 그 기간이 지나면 법률이 확정됩니다.","대통령은 보통·평등·직접·비밀선거로 선출하고, 최고득표자가 2인 이상이면 국회 재적의원 과반수가 출석한 공개회의에서 다수표를 얻은 자가 당선되며, 후보자가 1인이면 선거권자 총수의 3분의 1 이상을 얻어야 당선(헌법 제67조)":"대통령 선거는 네 가지 원칙으로 치르고, 후보가 한 명뿐이면 선거권자 총수의 3분의 1 이상을 얻어야 당선됩니다.","대통령은 정부에 이송된 날부터 15일 이내에 공포하거나 이의서를 붙여 재의 요구 가능":"대통령은 이송받은 날부터 15일 안에 법률을 공포하거나 이의서를 붙여 다시 논의하라고 돌려보낼 수 있습니다.","대통령이 동의 없이 조약을 체결해도 국회의원 개인은 국회의 동의권 침해를 이유로 권한쟁의심판을 청구할 수 없음":"동의권 침해를 내세워 국회의원 한 사람이 권한쟁의심판을 청구하는 것은 허용되지 않습니다.","대통령이 요구할 때는 기간과 이유 명시":"대통령이 임시회를 요구할 때는 기간과 이유를 밝혀야 해요.","대통령 임명 3인, 국회 선출 3인, 대법원장 지명 3인":"선관위 위원 구성은 대통령, 국회, 대법원장이 각각 3인씩 맡아 위원을 정합니다.","대통령 임명·대법원장 지명 재판관·위원과 국무위원은 소관 상임위원회에서 청문":"대통령이 임명하거나 대법원장이 지명한 재판관·위원, 그리고 국무위원은 소관 상임위원회가 청문합니다.","대표권의 내부 제한은 선의의 제3자에게 대항 불가":"대표권에 내부적으로 걸어 둔 제한은 선의의 제삼자를 상대로는 주장하지 못합니다.","대표이사 개인이 회사 운영자금으로 돈을 빌리는 것도 상행위가 아님":"대표이사 개인이 회사 운영 자금을 빌렸다고 해서 그 차용이 상행위로 되는 것은 아닙니다.","대표이사는 이사회가 선정, 정관으로 주주총회가 선정하게 할 수 있음":"대표이사는 이사회가 정하는 것이 기본이지만, 정관으로 주주총회가 정하게 바꿀 수 있습니다.","대학은 학문의 자유와 대학의 자율성에 따라 입시제도 결정 가능":"대학은 학문의 자유와 대학의 자율성에 따라 입시제도를 스스로 정할 수 있어요.","대한변호사협회의 변호사 광고에 관한 규정은 헌법소원 대상인 공권력 행사":"대한변호사협회의 변호사 광고 규정은 헌법소원으로 다툴 수 있는 공권력 행사예요.","동의권이 없는 공직후보자의 경과보고서는 임명권자를 구속하지 않음":"동의권이 없는 후보자의 경과보고서는 참고 자료일 뿐 임명권자의 결정을 묶지 못합니다.","동일한 특별시·광역시·시·군에서 동종영업으로 타인이 등기한 상호를 쓰면 부정한 목적 추정":"같은 시·군에서 동종영업으로 타인이 등기한 상호를 쓰면 부정한 목적으로 쓴 것으로 추정해요.","두 공무원은 범위가 다름(헌법 제7조 제1항·제2항)":"헌법 제7조의 제1항 공무원과 제2항 공무원은 포함 범위가 서로 같지 않습니다.","두 채무는 부진정연대여서 한 사람에 대한 시효중단은 다른 사람에게 미치지 않음":"두 채무는 부진정연대 관계라서 한쪽의 시효 중단이 다른 쪽에까지 미치지는 않습니다.","두 회사의 대표이사를 겸한 자가 두 회사 사이에 맺은 계약도 자기거래":"두 회사의 대표이사를 함께 맡은 사람이 두 회사 사이에 계약을 맺는 것도 자기거래입니다.","등기 상호를 정당한 사유 없이 2년간 사용하지 않으면 폐지로 봄(제26조)":"등기해 둔 상호를 정당한 이유 없이 2년 동안 쓰지 않으면 폐지한 것으로 간주합니다.","만기가 기재된 백지어음의 보충권은 독립하여 시효로 소멸하지 않고 주채무자에 대한 3년의 시효 안에 보충하면 되며, 만기 백지 어음의 보충권 시효는 행사할 수 있는 때부터 3년, 발행일 백지 수표는 6개월":"만기가 적힌 백지어음의 보충권은 따로 시효로 사라지지 않고, 주채무자에 대한 3년 시효 안에 보충하면 충분합니다.","매도인이 악의이거나 불완전이행에 따른 손해배상, 임대차, 부대체물 제작물공급에는 적용되지 않음":"매도인이 악의인 경우나 불완전이행, 임대차, 부대체물 제작물공급 계약에서는 이 규정을 쓰지 않습니다.","매도청구를 받은 소수주주는 2개월 안에 매도해야 하고, 매매가액은 협의로 정하되 30일 안에 협의가 안 되면 법원에 결정을 청구할 수 있으며 주식은 매매가액을 지급한 때 이전된 것으로 봄":"매도청구를 받은 소수주주는 2개월 안에 팔아야 하고, 협의가 30일 안에 안 되면 법원에 가액 결정을 청구할 수 있어요.","매수인이 수령을 거부하면 매도인은 공탁하거나 최고 후 경매 가능":"매수인이 받기를 거부하면 매도인은 물건을 공탁하거나, 최고한 후 경매할 수 있습니다.","매수청구권은 형성권, 행사하면 회사 승낙 없이 매매계약 성립":"형성권이라서 주주가 행사하면 회사 승낙이 없어도 곧바로 매매계약이 성립합니다.","면책 대상에는 이에 통상 부수하는 행위도 포함":"면책특권은 직무상 발언과 표결뿐 아니라 이에 통상 딸린 행위에도 미칩니다.","명령·규칙 또는 처분의 헌법·법률 위반이 재판의 전제가 되면 대법원이 최종 심사(헌법 제107조 제2항)":"명령·규칙·처분의 위헌·위법이 재판의 전제가 되면 대법원이 최종적으로 심사해요.","명의개서는 주식 이전의 효력요건이 아니라 회사에 대한 대항요건이지만 회사도 주주명부에 구속되어 실제 인수인이 따로 있음을 알았든 몰랐든 명부상 주주의 권리 행사를 부인할 수 없고 명부에 없는 자의 권리 행사를 인정할 수도 없음":"명의개서는 효력요건이 아니라 회사에 대한 대항요건이며, 회사도 명부상 주주의 권리 행사를 부인할 수 없어요.","모든 국민은 국가기관에 문서로 청원할 권리, 국가는 청원을 심사할 의무(헌법 제26조)":"국가기관에 문서로 청원할 수 있고, 국가는 그 청원을 심사해야 합니다.","모든 기본권 제한입법에 요구되나 최소한의 명확성이면 족함":"명확성원칙은 모든 기본권 제한 입법에 요구되지만 최소한의 명확성만 갖추면 충분합니다.","모든 등록대상자에게 일률적으로 20년 등록기간을 적용한 조항은 침해의 최소성 위반":"등록 대상자 모두에게 20년을 일률 적용한 조항은 침해의 최소성에 어긋난다고 봤어요.","모든 사건에서 상소심 재판을 받을 권리까지 당연히 포함하지는 않음":"모든 사건에서 상소심 재판까지 받을 권리가 당연히 포함되지는 않아요.","모자보건법상 허용 사유에 사회적·경제적 사유 없음":"모자보건법이 낙태를 허용하는 사유에는 사회적·경제적 사유가 들어 있지 않았어요.","모회사에 보관된 자회사 장부도 모회사 회계 파악에 필요하면 대상이 되고, 주주명부 열람·등사 청구는 회사가 정당한 목적이 없음을 증명해야 거절할 수 있으며 명의개서대리인에게도 직접 청구할 수 있음":"모회사에 보관된 자회사 장부도 모회사 회계 파악에 필요하면 열람 대상이 되고, 명의개서대리인에게도 직접 청구할 수 있어요.","모회사 주식 1% 이상(상장회사는 6개월 이상 0.5% 이상)을 가진 주주":"다중대표소송을 내려면 모회사 주식 1% 이상, 상장회사라면 6개월 이상 0.5% 이상을 보유해야 합니다.","목적물은 채무자 소유여야 하고 특약으로 배제 가능":"상사유치권의 목적물은 채무자 소유여야 하고 특약으로 배제할 수 있어요.","목적의 정당성·방법의 적절성·피해의 최소성·법익의 균형성을 모두 갖춰야 함":"기본권 제한이 정당하려면 목적, 방법, 피해, 법익 네 면에서 각각 요건을 충족해야 합니다.","무료·부당 염가 수임료를 내세운 광고 금지":"무료이거나 부당하게 싼 수임료를 내세운 광고를 막는 부분은 합헌이에요.","무인이나 지장은 유효한 날인이 아니지만 진정한 의사로 한 이상 기명과 날인이 일치하지 않아도 유효":"무인이나 지장은 유효한 날인이 아니지만, 진정한 의사로 했다면 기명과 날인이 서로 달라도 효력이 있습니다.","무죄재판을 한 법원에 청구, 무죄재판이 확정된 사실을 안 날부터 3년":"무죄재판을 한 법원에 신청하되, 무죄 확정 사실을 안 날로부터 3년 안에 해야 합니다.","무한책임사원 전원의 동의가 있으면 지분 양도 가능(제276조)":"합자회사 사원의 지분은 무한책임사원 전원의 동의가 있으면 양도할 수 있어요.","무효인 재산인수의 양도인이 목적물 반환을 구하는 것은 사정에 따라 신의칙상 허용되지 않을 수 있음":"무효가 된 재산인수의 양도인이 물건을 돌려 달라고 하는 것은 사정에 따라 신의칙에 어긋날 수 있습니다.","무효·취소 원인이 특정 사원에게만 있으면 다른 사원 전원의 동의로 회사 계속 가능":"무효나 취소의 원인이 한 사원에게만 있으면 나머지 사원 전원이 동의해 회사를 이어 갈 수 있습니다.","민주적 기본질서에 대한 중대한 침해가 있을 때":"저항권은 민주적 기본질서가 크게 침해될 때 행사하는 권리예요.","민주적 기본질서 위배는 실질적 해악을 끼칠 구체적 위험성을 뜻함":"민주적 기본질서 위배란 실질적인 해악을 끼칠 구체적 위험성이 있다는 뜻이에요.","발달단계에 따라 보호 정도와 수단을 달리할 수 있음":"태아의 발달 단계에 따라 보호의 정도와 수단을 다르게 둘 수 있어요.","발의 · 국회재적의원 과반수 또는 대통령":"개정안을 처음 제안하는 단계로, 국회 재적의원 과반수나 대통령이 할 수 있어요.","발행주식총수의 1% 이상 주주가 이유를 적은 서면으로 이사 책임 추궁 소 제기를 청구":"발행주식총수의 1% 이상을 가진 주주는 이유를 적은 서면으로 이사의 책임을 묻는 소를 제기하라고 회사에 청구할 수 있어요.","발행주식총수의 3% 이상을 가진 주주는 이유를 붙인 서면으로 회계장부 열람·등사를 청구할 수 있고, 회사는 청구가 부당함을 증명하지 못하면 거부할 수 없음(제466조)":"발행주식총수의 3% 이상을 가진 주주가 서면으로 회계장부 열람·등사를 청구하면 회사는 부당함을 증명하지 못하는 한 거부할 수 없어요.","발행주식총수의 95% 이상을 자기 계산으로 보유한 지배주주는 경영상 목적에 필요하면 미리 주주총회 승인을 받아 소수주주에게 주식 매도를 청구할 수 있고, 보유주식 수에는 모회사와 자회사가 가진 주식을 합산(제360조의24)":"발행주식총수의 95% 이상을 가진 지배주주는 경영상 목적이 있으면 주주총회 승인을 받아 소수주주에게 매도를 청구할 수 있어요.","배당가능이익은 순자산액에서 자본금, 적립된 준비금, 당기 적립할 이익준비금, 미실현이익을 뺀 금액이고, 배당은 주주총회 결의로 하되 재무제표를 이사회가 승인하는 회사는 이사회가 정하며 위법배당 시 회사채권자는 주주에게 회사로의 반환을 청구할 수 있음(제462조)":"배당가능이익은 순자산액에서 자본금, 준비금, 이익준비금, 미실현이익을 뺀 금액이고, 위법배당 시 회사채권자는 주주에게 반환을 청구할 수 있어요.","배당은 결의일부터 1개월 안에 지급하고 배당금 지급청구권의 시효는 5년이며, 특정 주주를 배당에서 제외한 결의는 무효":"배당금은 결의 후 1개월 안에 지급해야 하고 청구권 시효는 5년이며, 특정 주주만 배당에서 제외하는 결의는 무효입니다.","배서금지배서를 한 배서인은 그 후의 피배서인에게 담보책임을 지지 않고(제15조 제2항), 배서가 연속된 점유자는 최후 배서가 백지식이어도 적법한 소지인으로 추정되며 위조된 배서가 끼어 있어도 형식상 연속이면 됨(제16조 제1항)":"배서금지배서를 한 사람은 그 뒤 피배서인에게 담보책임이 없고, 배서가 이어진 점유자는 적법한 소지인으로 추정됩니다.","배서는 권리이전·담보·자격수여의 효력이 있고, 배서에 붙인 조건은 적지 않은 것으로 보며 일부배서는 무효(어음법 제12조)":"배서에는 권리이전, 담보, 자격수여의 효력이 있고, 조건을 붙여도 없는 것으로 보며 일부배서는 효력이 없습니다.","백지를 보충하지 않고 어음금을 청구해도 시효는 중단되지만 미보충 상태의 지급제시는 적법한 제시가 아니고, 부당보충은 악의·중과실로 취득한 소지인에게만 대항할 수 있음(어음법 제10조)":"백지를 채우지 않고 어음금을 청구해도 시효는 중단되지만, 채우지 않은 채 한 지급제시는 적법한 제시가 아닙니다.","범죄 종류와 경중을 가리지 않고 금고 이상 형의 선고유예만으로 당연퇴직시키는 조항은 침해":"범죄 종류와 무게를 따지지 않고 선고유예만으로 공무원을 내보내는 조항은 침해라고 봅니다.","법관에 대한 징계처분 취소청구소송을 대법원 단심으로 하는 법관징계법 조항":"법관 징계처분 취소청구소송을 대법원 단심으로 한다고 정한 법관징계법 조항이에요.","법관은 탄핵 또는 금고 이상의 형의 선고가 아니면 파면되지 않음":"법관은 탄핵이나 금고 이상의 형을 선고받지 않으면 파면되지 않아요.","법관의 정년은 법률로 정함(제105조)":"법관의 정년은 헌법이 아닌 법률로 정해요.","법관이 검사와 피고인의 부당한 간섭에서 독립할 것도 요구":"법관이 검사와 피고인의 부당한 간섭에서도 독립해야 한다는 요구도 담고 있어요.","법관이 사실을 확정하고 법률을 해석·적용하는 재판을 받을 권리":"재판청구권의 재판은 법관이 사실관계를 확정하고 법을 해석해 적용하는 재판입니다.","법령 위반 행위는 결과적으로 회사에 이익이 되었어도 보호받지 못함":"법령을 위반한 행위는 결과적으로 회사에 이익이 되었어도 경영판단원칙의 보호를 받지 못해요.","법령을 위반하지 않고 필요한 정보를 충분히 검토해 내린 합리적 판단에만 적용":"경영판단원칙의 보호는 법령을 지키고 정보를 충분히 살펴 합리적으로 판단한 경우에만 받을 수 있습니다.","법령·정관 위반이나 현저히 불공정한 방법의 발행으로 불이익을 받을 염려가 있는 주주는 발행 효력이 생기기 전(납입기일까지) 유지를 청구할 수 있음(제424조)":"불이익을 받을 염려가 있는 주주는 납입기일까지 신주발행 유지를 청구할 수 있어요.","법률로 이와 다른 비공개 요건을 정할 수 없음":"비공개 요건을 헌법과 다르게 법률로 정하는 것은 허용되지 않습니다.","법률로 확정(헌법 제53조)":"재의결이 이뤄지면 그 법률안은 법률로 확정됩니다.","법률·명령·조례·규칙의 제정·개정·폐지도 청원 가능":"법률·명령·조례·규칙을 만들거나 고치거나 없애 달라는 청원도 할 수 있어요.","법률안은 국회의원과 정부가 제출 가능":"법률안은 국회의원과 정부가 모두 제출할 수 있어요.","법률안 일부에 대해서나 수정하여 재의를 요구할 수는 없음":"법률안 일부만, 또는 수정해서 재의를 요구하는 것은 허용되지 않아요.","법률에 설치근거를 둔 기관이어서 권한쟁의심판의 당사자능력이 없음":"국가인권위원회는 법률로 설치된 기관이라 권한쟁의심판의 당사자능력이 없어요.","법률은 특별한 규정이 없으면 공포한 날부터 20일이 지나면 효력이 생기고, 대통령이 환부한 법률안은 무기명투표로 표결":"법률은 공포 후 20일이 지나야 효력이 시작되며 특별한 규정이 있으면 달라집니다.","법률의 위헌결정, 권한쟁의심판 결정, 헌법소원 인용결정은 기속력이 법률에 명문으로 규정":"위헌결정, 권한쟁의심판 결정, 헌법소원 인용결정에 대해서는 법률이 기속력을 직접 정해 두었습니다.","법률이 여러 가지로 해석될 수 있으면 헌법에 합치되는 해석을 택해야 하고, 이는 헌법의 최고규범성에서 나오는 법질서의 통일성과 권력분립·입법권 존중에 근거":"여러 해석이 가능한 법률은 최고규범인 헌법에 맞게 해석해야 하며, 그 근거가 헌법의 최고규범성입니다.","법무법인 구성원 지분 압류채권자의 퇴사청구는 재산권을 중심으로 판단":"법무법인 구성원 지분을 압류한 채권자가 퇴사를 청구한 사건은 재산권이 중심이에요.","법무사 아닌 자의 등기신청대행 등 법무행위를 금지·처벌하는 조항, 고소·고발장 작성을 법무사 업무로 정한 조항, 경력공무원에게 시험 없이 법무사 자격을 주던 조항은 직업선택의 자유를 침해하지 않음":"법무사 아닌 사람의 법무행위 금지·처벌 등은 직업선택의 자유를 침해하지 않는다고 판단했어요.","법원은 다른 사원의 청구로 업무집행권한 상실 선고 가능":"법원은 다른 사원의 청구로 그 사원의 업무집행권한 상실을 선고할 수 있어요.","법원은 설립목적이 불법인 경우 해산 명령 가능":"법원은 회사의 설립목적이 불법이면 해산을 명령할 수 있어요.","법원의 재량기각은 취소의 소에만 인정":"법원이 재량으로 기각할 수 있는 것은 취소의 소에만 해당해요.","법원이 선임한 경우가 아니면 주주총회 결의로 언제든지 해임 가능":"법원이 선임한 청산인이 아니면 주주총회 결의로 언제든지 해임할 수 있어요.","법위반사실 공표명령·학교폭력 가해학생 서면사과·준법서약서 요구는 침해 아님":"법위반사실 공표명령, 가해학생 서면사과, 준법서약서 요구는 양심의 자유를 침해하지 않는다고 봅니다.","법인도 성질에 반하지 않는 범위에서 사회적 신용·명예 같은 인격권의 주체":"법인은 사람이 아니어도 성질에 맞는 한 사회적 신용·명예에 관한 인격권을 누립니다.","법인도 업무집행자가 될 수 있음":"법인도 유한책임회사의 업무집행자가 될 수 있어요.","법인의 어음행위는 법인명과 대표자격을 표시하고 대표자가 기명날인해야 하므로 법인명과 대표자 날인만 있으면 무효이고, 대리권 없이 대리인으로 기명날인한 자는 스스로 어음상 의무를 지며(어음법 제8조), 수권 범위를 넘은 경우 본인은 수권 범위에서 책임":"법인의 어음행위는 법인명과 대표 자격을 적고 대표자가 기명날인해야 하며, 대리권 없이 대리인으로 서명한 사람은 스스로 의무를 집니다.","법인 임원이 학원법 위반으로 벌금형을 받으면 법인의 학원 등록이 실효되게 한 조항, 성인대상 성범죄자의 10년간 의료기관 취업 제한, 법인의 약국 개설 금지, 자동차를 이용한 범죄에 대한 필요적 운전면허 취소, 일반학원 강사에게 대졸 학력을 요구한 조항은 직업의 자유를 침해":"벌금형에 따른 학원 등록 실효, 성범죄자 의료기관 취업 제한, 법인의 약국 개설 금지 등은 직업의 자유를 침해한다고 본 판례들이에요.","법통 계승·범죄피해자구조청구권은 1987년, 환경권은 1980년 헌법이 처음 규정":"1987년 헌법이 법통 계승과 범죄피해자구조청구권을, 1980년 헌법이 환경권을 처음 헌법에 담았습니다.","변호사로 오인하게 할 수 있는 자에게 광고를 의뢰하는 행위 금지":"변호사로 오인하게 할 수 있는 사람에게 광고를 맡기는 행위를 금지한 부분은 합헌이에요.","변호사·법무사·법무법인은 의제상인이 아님":"변호사나 법무사, 법무법인은 영업 성격이 달라 의제상인으로 보지 않습니다.","변호사시험 응시기회를 졸업 후 5년 내 5회로 제한하는 조항과 집행유예 기간 경과 후 2년 미만인 자의 응시를 막는 조항은 직업선택의 자유를 제한하고, 수임 건수·수임액 보고의무와 알선 대가 제공 금지는 직업수행의 자유를 제한":"변호사시험 응시를 5년 내 5회로 막는 조항은 직업선택의 자유를, 수임 보고의무와 알선 대가 금지는 직업수행의 자유를 제한해요.","변호사의 표현의 자유와 직업의 자유 침해":"이 부분들은 변호사의 표현의 자유와 직업의 자유를 침해한다고 판단됐어요.","변호사 징계정보 공개는 일반적 인격권을 중심으로 판단":"변호사 징계정보 공개 사건은 일반적 인격권을 중심으로 심사했습니다.","변호인이 되려는 자의 접견교통권도 헌법상 기본권":"변호인이 되려는 사람의 접견교통권도 헌법이 보장하는 기본권이에요.","병역의무 이행은 국민이 마땅히 해야 할 의무를 다하는 것, 국가를 위한 특별한 희생은 아님":"병역을 마치는 일은 국민의 당연한 의무 이행이어서 특별 희생으로 보상해 주는 일이 아닙니다.","병역 이행을 이유로 한 법적 불이익 금지, 병역 이행 자체의 불이익과는 무관(헌법 제39조 제2항)":"병역을 이행했다는 이유로 불이익을 주는 것만 금지되고, 병역 이행 자체에서 생기는 불이익과는 별개예요.","보상결정에 불복할 수 없게 한 조항은 위헌 결정":"보상결정에 불복할 수 없게 막은 조항은 위헌으로 결정됐어요.","보수는 정관이나 주주총회 결의로 정하고 퇴직금·해직보상금도 포함":"이사의 보수는 정관 규정이나 주주총회 결의로 정하고, 퇴직금과 해직보상금까지 보수에 들어갑니다.","보통선거원칙은 성년자이면 누구나 선거권을 갖는 것":"보통선거원칙은 성년이면 누구나 선거권을 가진다는 원칙이에요.","보험가액을 정하지 않았으면 사고발생 시의 가액이 보험가액이고(제671조), 정한 경우에는 사고발생 시 가액으로 추정하되 그것을 현저히 초과하면 사고발생 시 가액에 따름":"보험가액을 정하지 않으면 사고 당시 가액이 보험가액이고, 정했더라도 현저히 초과하면 사고 당시 가액을 따릅니다.","보험계약자나 피보험자가 계약 당시 고의·중과실로 중요한 사항을 알리지 않거나 사실과 다르게 알리면 보험자는 안 날부터 1개월, 계약일부터 3년 안에 해지할 수 있지만 보험자가 그 사실을 알았거나 중과실로 몰랐으면 해지할 수 없음(제651조)":"고의·중과실로 중요한 사항을 알리지 않으면 보험자는 안 날부터 1개월, 계약일부터 3년 안에 해지할 수 있어요.","보험금 부정취득 목적의 다수 계약은 민법 제103조에 따라 무효이고, 이때 보험자의 부당이득반환청구권에는 5년의 상사시효가 적용":"보험금을 부정하게 타내려는 다수 계약은 민법 제103조로 무효이고, 보험자의 반환청구에는 5년의 상사시효가 적용됩니다.","보험금 지급 약정기간이 없으면 사고 통지를 받은 후 지체 없이 금액을 정하고 그날부터 10일 안에 지급해야 함(제658조)":"지급 약정기간이 따로 없으면 사고 통지 후 지체 없이 보험금을 정하고 그날부터 10일 안에 지급해야 합니다.","보험금청구권과 보험료반환청구권은 3년, 보험료청구권은 2년의 시효로 소멸하고(제662조), 보험금청구권의 시효는 원칙적으로 사고 발생 시부터, 사고 발생을 객관적으로 알 수 없었으면 알았거나 알 수 있었던 때부터 진행":"보험금청구권과 보험료반환청구권은 3년, 보험료청구권은 2년의 시효로 소멸해요.","보험자가 서면(청약서 포함)으로 질문한 사항은 중요한 사항으로 추정되고(제651조의2), 해지는 인과관계 없이 할 수 있으나 위반 사실이 사고 발생에 영향이 없었음을 보험계약자가 증명하면 보험금은 지급해야 함(제655조 단서)":"보험자가 서면으로 질문한 사항은 중요한 사항으로 추정되고, 해지는 인과관계 없이 가능하나 사고와 무관함을 증명하면 보험금을 줘야 해요.","보험자는 계약 체결 시 약관을 교부하고 중요한 내용을 설명해야 하며 위반하면 보험계약자는 계약 성립일부터 3개월 안에 취소할 수 있음(제638조의3)":"보험자가 약관을 주고 중요한 내용을 설명하지 않으면, 보험계약자는 계약 성립일부터 3개월 안에 계약을 취소할 수 있습니다.","보험자는 피해자가 배상을 받기 전에는 피보험자에게 보험금을 지급하지 못함(제724조 제1항)":"보험자는 피해자가 배상을 받기 전에는 피보험자에게 보험금을 지급할 수 없어요.","복권은 상실·정지된 자격을 회복시키는 것이고 형 집행이 끝나지 않았거나 면제되지 않은 자에게는 하지 않음":"복권은 상실·정지된 자격을 되찾게 하는 것이며 형 집행이 안 끝났거나 면제되지 않은 사람에게는 하지 않아요.","본안이 부적법하거나 이유 없음이 명백하지 않고, 회복하기 어려운 손해를 예방할 필요와 긴급성이 있으며 가처분을 기각한 뒤 청구가 인용될 때의 불이익이 인용한 뒤 기각될 때의 불이익보다 크면 인용할 수 있음":"회복하기 어려운 손해를 막을 긴급성이 있고 기각 후 인용될 때의 불이익이 더 크면 가처분을 인용할 수 있어요.","본인 소유가 아닌 물건도 유치 가능":"대리상은 본인 소유가 아닌 물건도 유치할 수 있어요.","본회의와 위원회는 모두 재적의원 5분의 1 이상의 출석으로 개의":"본회의와 위원회는 모두 재적의원 5분의 1 이상이 출석해야 회의를 열 수 있어요.","부모의 자녀교육권은 헌법에 명문 규정은 없으나 양도할 수 없는 불가침의 인권":"부모의 자녀교육권은 조문이 없어도 남에게 넘길 수 없는 불가침의 인권으로 봅니다.","부분적 포괄대리권을 가진 사용인에게는 유추적용되지 않음":"부분적 포괄대리권을 가진 사용인에게는 표현지배인 규정을 유추적용하지 않아요.","부정 취득한 면허 외의 모든 면허까지 필요적으로 취소하는 조항":"부정 취득한 면허 외의 모든 면허까지 반드시 취소하게 한 조항이기도 해요.","부진정소급입법은 원칙적으로 허용, 신뢰보호와 비교형량":"부진정소급입법은 진행 중인 사실에 적용하는 것이라 원칙적으로 허용되고, 신뢰보호와 비교형량을 합니다.","불구속 피의자·피고인과 출입국관리법상 보호·강제퇴거 절차에도 인정":"변호인 조력권은 구속되지 않은 피의자와 피고인, 출입국관리법상 보호·강제퇴거 절차까지 확장됩니다.","불법체류 중인 외국인도 원칙적으로 기본권의 주체":"불법체류 중인 외국인도 원칙적으로 기본권을 누리는 주체가 될 수 있어요.","불법행위나 차용자의 피용자 행위에는 책임이 미치지 않음":"명의대여자의 책임 범위에 불법행위나 차용자의 피용자가 한 행위는 포함되지 않습니다.","불법행위 손해배상채권, 위법배당에 따른 부당이득반환채권":"불법행위로 인한 손해배상채권과 위법배당 때문에 생기는 부당이득반환채권이 그 예로 거론됩니다.","불법행위 손해배상채무에는 적용되지 않음(제54조)":"불법행위 손해배상채무에는 상사 법정이율이 적용되지 않아요.","불체포특권은 불기소특권이 아님":"불체포특권은 체포를 막는 것일 뿐 수사나 기소까지 막는 불기소특권은 아닙니다.","비례원칙에 따른 엄격한 심사":"이런 경우에는 비례원칙을 적용해 엄격하게 심사합니다.","비례원칙에 맞는 제약은 수인해야 할 사회적 제약이지만 개발제한구역 지정으로 토지를 종래 목적으로도 쓸 수 없게 되는 등 그 한계를 넘으면 보상규정을 두어야 함":"사회적 제약을 넘어 토지를 종래 목적으로도 못 쓰게 되면 보상규정을 둬야 해요.","비상근·사외이사도 위법을 의심할 사유를 방치하면 책임":"상근하지 않는 이사와 사외이사도 위법 징후를 알고 방치하면 책임에서 벗어나지 못합니다.","비상장법인 간 합병비율은 자산가치 외에 수익가치·상대가치 등을 고려해 정할 수 있음":"비상장법인 사이에서는 자산가치 말고도 수익가치와 상대가치를 함께 고려해 합병비율을 정할 수 있습니다.","비의료인 문신시술업 금지는 직업의 자유를 중심으로 판단":"비의료인의 문신시술업을 금지한 사건은 직업의 자유를 중심으로 심사했어요.","사립학교 교원의 단체행동권을 제한하는 헌법 규정은 없음":"사립학교 교원의 단체행동권을 막으라고 정한 헌법 조항은 없습니다.","사망보험은 중과실로 생긴 사고에도 보험금을 지급해야 하고, 보험수익자 변경은 형성권이나 보험자에게 통지하지 않으면 대항하지 못하며 상속인이 수익자인 경우 보험금청구권은 상속인의 고유재산":"사망보험은 중과실로 생긴 사고에도 보험금을 지급해야 하고, 상속인이 수익자인 경우 보험금청구권은 상속인의 고유재산이에요.","사망하면 퇴사, 정관에 정한 경우에만 상속인이 사원이 될 수 있음(제218조·제219조)":"사원이 죽으면 퇴사하고, 정관에 정한 경우에만 상속인이 사원이 될 수 있어요.","사면은 형 선고의 효력이나 공소권을 상실시키거나 형 집행을 면제하는 대통령의 권한으로 권력분립의 예외이며, 그 종류·대상·절차는 입법자가 넓은 재량으로 정함":"사면은 형 선고의 효력이나 공소권을 없애거나 형 집행을 면제하는 대통령 권한이며 권력분립의 예외예요.","사법상 환경권을 인정하는 명문 규정이 없는 경우 환경권에 근거한 직접 방해배제 청구 불가":"사법상 환경권을 인정하는 명문 규정이 없으면 환경권만으로 방해배제를 직접 청구할 수 없어요.","사안과 가장 밀접하고 침해 정도가 큰 기본권이 주된 기본권":"침해가 심하고 사안과 가장 가까운 기본권을 골라 그것을 기준으로 심사한다는 말입니다.","사영기업은 국방상 또는 국민경제상 긴절한 필요로 법률이 정하는 경우가 아니면 국유·공유로 이전할 수 없고(제126조), 수력 등 자연력은 법률이 정하는 바에 따라 일정 기간 이용을 특허할 수 있음(제120조 제1항)":"사영기업은 법률이 정한 긴절한 필요가 없으면 국유·공유로 못 바꾸고, 자연력 이용은 일정 기간 특허로 줄 수 있어요.","사원은 다른 사원의 동의 없이 지분을 양도하지 못함(제197조)":"사원은 다른 사원의 동의 없이 지분을 양도하지 못해요.","사원은 신용이나 노무를 출자할 수 없고 설립등기 전까지 출자를 전부 이행(제287조의4)":"유한책임회사 사원은 신용이나 노무를 출자할 수 없고 설립등기 전까지 출자를 전부 이행해야 해요.","사원의 지분은 강제집행의 대상이나 금전채권이 아니어서 전부명령의 대상은 아님":"유한회사 지분은 강제집행은 가능하지만 금전채권이 아니므로 전부명령으로 가져갈 수는 없습니다.","사원의 책임은 면제 불가, 이사·감사의 책임은 총사원의 동의로 면제 가능(제551조)":"사원의 책임은 면제할 수 없고, 이사·감사의 책임은 총사원의 동의로 면제할 수 있어요.","사원이 아닌 자가 자기를 사원으로 오인시켰으면 그 오인으로 회사와 거래한 자에게 사원과 같은 책임(제215조)":"사원이 아닌데도 사원처럼 보이게 만든 사람은 그것을 믿고 거래한 상대에게 사원과 같은 책임을 집니다.","사원이 업무집행에 현저하게 부적임하거나 중대한 의무위반이 있는 경우":"사원이 업무집행에 현저히 부적임하거나 중대한 의무위반을 한 경우가 사유예요.","사인에게서 차별행위를 당한 경우에도 진정할 수 있고, 위원회는 피해자를 위해 법률구조를 요청할 수 있으나 피해자의 명시한 의사에 반해서는 할 수 없음":"사인에게서 차별행위를 당해도 진정할 수 있고, 피해자의 명시한 의사에 반하는 법률구조 요청은 할 수 없어요.","사자(死者)는 청구인능력이 없음":"사자는 이미 사망한 사람이라 헌법소원을 낼 청구인능력이 없습니다.","사전 승인 없는 거래는 무효, 사후 이사회 승인이나 주주총회 추인으로 유효해지지 않음":"사전 승인 없이 한 자기거래는 무효이고, 이사회가 뒤늦게 승인하거나 총회가 추인해도 유효해지지 않습니다.","사채관리회사는 은행·신탁회사 등만 될 수 있고 그 사채의 인수인은 될 수 없음(제480조의3)":"사채관리회사는 은행·신탁회사 등이 맡을 수 있으나 해당 사채의 인수인이 겸할 수는 없습니다.","사채권자집회의 결의는 법원의 인가로 효력이 생기지만 그 종류 사채권자 전원이 동의한 결의는 인가가 필요 없음(제498조)":"사채권자집회 결의는 법원 인가를 받아야 효력이 생기지만, 같은 종류 사채권자 전원이 동의했다면 인가가 필요하지 않습니다.","사채는 이사회 결의로 발행하고, 정관이 정하면 이사회가 대표이사에게 금액과 종류를 정해 1년 이내에 발행하도록 위임할 수 있음(제469조)":"사채 발행은 이사회 결의 사항이지만, 정관이 허용하면 금액과 종류를 정해 1년 이내 발행하도록 대표이사에게 맡길 수 있습니다.","사회국가원리는 명문 규정은 없으나 여러 조항에 구체화":"사회국가원리를 직접 밝힌 조문은 없지만 여러 조항에서 구체화되어 있어요.","산재보험수급권은 입법으로 구체화되는 법률상 권리":"산재보험수급권은 법률로 내용이 채워져야 생기는 법률상 권리입니다.","살아서 출생하지 못한 태아의 손해배상청구권 불인정은 법적 안정성 요청이라 보호의무 위반 아님(민법 제762조)":"출생하지 못한 태아의 손해배상청구권을 인정 않는 민법 제762조는 법적 안정성 요청으로 보호의무 위반이 아닙니다.","상대방은 민법상 표현대리로만 보호":"이런 상대방은 상법이 아닌 민법상 표현대리로만 보호받아요.","상대방의 악의·중과실이면 책임 없음, 증명책임은 명의대여자":"상대방이 악의이거나 중과실이면 책임이 없고, 그 증명책임은 명의대여자에게 있어요.","상사채무 불이행 손해배상채권, 은행 대출금 지연손해금도 5년":"상사채무 불이행에 따른 손해배상채권과 대출금의 지연손해금도 5년이 지나면 시효로 사라집니다.","상인 간 매매에서 매수인은 목적물을 받으면 지체 없이 검사하고 하자나 수량부족을 즉시 통지":"상인 사이의 매매에서 매수인은 물건을 수령하면 곧장 검사하고, 하자나 수량 부족이 있으면 즉시 알려야 합니다.","상인 간 상행위로 인한 채권이 변제기에 있으면 목적물과 견련성 없이 성립":"상인끼리 상행위로 채권이 생겨 변제기가 되면 물건과 채권이 관련 없어도 유치권이 인정됩니다.","상인이 판매한 상품의 대가는 3년의 단기시효":"상인이 판 상품의 값을 받을 권리는 3년의 단기시효로 끝납니다.","상행위로 생긴 채권을 담보하는 질권에는 유질약정 허용":"상행위에서 생긴 채권을 담보하는 질권이라면 유질약정을 해도 괜찮습니다.","상행위로 인한 채권의 소멸시효는 5년(상법 제64조)":"상행위에서 생긴 채권의 소멸시효는 5년입니다.","상행위로 인한 채무의 법정이율은 연 6%":"상행위로 진 채무에 붙는 법정이율은 연 6%입니다.","상호를 속용하는 양수인은 양도 전 양도인의 영업상 채무(불법행위 채무 포함)를 변제할 책임":"상호를 계속 쓰는 양수인은 양도 전 양도인의 영업상 채무를 불법행위 채무까지 변제할 책임이 있어요.","상호원조·안전보장, 중요한 국제조직, 우호통상항해, 주권의 제약":"상호원조·안전보장, 국제조직, 우호통상항해, 주권 제약에 관한 조약이 동의권 대상에 들어갑니다.","생계를 같이 하는 가족에 대한 권리는 그 가족의 고의가 아니면 대위할 수 없고, 인보험에서는 대위가 금지되나 상해보험은 약정으로 피보험자의 권리를 해하지 않는 범위에서 할 수 있음(제729조)":"생계를 같이하는 가족에 대한 권리는 그 가족의 고의가 아니면 대위할 수 없고, 인보험은 대위 자체가 금지됩니다.","서면의 이유는 대상 이사와 원인사실을 회사가 특정할 수 있을 정도면 충분(제403조)":"제소 청구서의 이유는 대상 이사와 원인사실을 회사가 특정할 수 있을 정도면 충분합니다.","서열이 아니라 형량과 규범조화로 조정":"기본권끼리 부딪히면 높낮이를 매기지 않고 형량과 규범조화로 조정해요.","선거관리위원회의 자료제출요구는 영장주의 적용 대상 아님":"선관위가 자료 제출을 요구하는 일에는 영장주의를 적용하지 않습니다.","선거권 제한 입법은 한계를 더 엄격히 지켜야 함(헌법 제37조 제2항)":"선거권을 제한하는 법은 헌법 제37조 제2항의 한계를 더 엄격하게 지켜야 해요.","선거기간 중 집회·모임 금지 조항":"선거기간 중 집회나 모임을 막아 선거운동을 제한한 조항이기도 합니다.","선거로 취임하는 지방자치단체의 장도 예외, 교육감은 예외 아님(정당법 제22조 제1항)":"지방자치단체의 장은 선거로 취임하므로 예외이지만 교육감은 여기에 들지 않습니다.","선거일 전 180일부터 벽보·인쇄물·광고물 금지 조항":"선거일 180일 전부터 벽보·인쇄물·광고물을 못 쓰게 한 조항이 문제 된 사례예요.","선교의 자유가 임의의 장소에서 행사할 권리까지 보장하지는 않음":"선교의 자유가 있어도 아무 장소에서나 선교할 수 있는 권리까지 보장되지는 않아요.","선박우선특권자는 집행권원 없이 경매를 청구할 수 있고, 우선특권은 선박소유권이 이전되어도 영향을 받지 않으며 채권 발생일부터 1년 안에 실행하지 않으면 소멸하고, 여러 항해의 채권이 경합하면 뒤의 항해 채권이 앞섬(제785조·제786조·제783조)":"선박우선특권자는 집행권원 없이 경매를 청구할 수 있고, 채권 발생일부터 1년 안에 실행하지 않으면 우선특권이 소멸해요.","선의의 전자에게 대항할 수 없던 항변은 그 뒤 악의로 취득한 소지인에게도 대항할 수 없으나, 항변을 받던 소지인이 배서양도 후 환배서로 되찾거나 전자에게 넘겼다 돌려받으면 여전히 항변을 받음":"선의의 전자에게 대항하지 못하던 항변은 악의의 후자에게도 대항할 수 없지만, 환배서로 되찾은 소지인은 여전히 항변을 받아요.","선전포고, 국군의 해외파견, 외국군대 주류에도 동의권(헌법 제60조)":"선전포고, 국군의 해외파견, 외국군대의 주류도 국회가 동의해야 하는 사항에 속합니다.","선행 저당권에 기한 경매의 매수인에게는 대항하지 못함(제58조)":"선행 저당권에 기한 경매의 매수인에게는 상사유치권으로 대항하지 못해요.","설립무효·취소 판결은 제3자에게도 효력이 있으나 판결 확정 전에 생긴 권리의무에는 영향이 없고, 회사가 성립하면 주식인수인은 착오나 청약서 요건 흠결을 이유로 인수의 무효·취소를 주장하지 못함(제320조)":"설립무효·취소 판결은 제3자에게도 효력이 있지만 확정 전에 생긴 권리의무에는 영향이 없어요.","설립의 자유에 가입·탈퇴의 자유와 존속·활동의 자유 포함":"설립의 자유에는 정당에 가입하고 탈퇴할 자유와 존속하고 활동할 자유도 들어갑니다.","설립중의 회사는 정관 작성과 발기인의 1주 이상 인수로 성립하고, 그 전에 발기인이 취득한 권리의무는 양수 등 별도 이전행위가 있어야 성립 후 회사에 귀속":"정관을 작성하고 발기인이 1주 이상 인수하면 설립중의 회사가 되고, 그 전의 권리의무는 별도 이전행위가 있어야 넘어갑니다.","설치하면 감사를 둘 수 없음":"감사위원회를 설치하면 감사를 따로 둘 수 없어요.","성별·종교·사회적 신분은 예시(헌법 제11조 제1항 후문)":"성별, 종교, 사회적 신분은 차별 금지 사유를 예로 든 것에 불과합니다.","성폭력 피해자가 원하지 않을 때의 국민참여재판 배제":"성폭력 피해자가 원하지 않으면 국민참여재판을 하지 않는 것도 합헌으로 판단됐어요.","소년심판에서 검사의 상소권 불인정":"소년심판에서 검사에게 상소권을 인정하지 않는 것도 평등원칙에 위배되지 않아요.","소는 본점 소재지 지방법원 관할, 여러 소가 제기되면 병합심리":"무효 소송은 본점 소재지 지방법원이 맡고, 소가 여러 개 제기되면 하나로 합쳐서 심리합니다.","소멸회사의 권리의무는 사법·공법 관계를 가리지 않고 성질상 이전이 안 되는 것을 빼고 포괄승계":"소멸회사의 권리의무는 성질상 넘길 수 없는 것을 빼고 공법·사법 관계를 가리지 않고 전부 승계됩니다.","소멸회사의 주주총회 승인을 이사회 승인으로 갈음 가능(간이합병)":"이때 소멸회사의 주주총회 승인을 이사회 승인으로 대신하는 것이 간이합병이에요.","소멸회사 총주주의 동의가 있거나 존속회사가 소멸회사 주식의 90% 이상을 가지면":"소멸회사의 총주주가 동의했거나 존속회사가 소멸회사 주식의 90% 이상을 갖고 있을 때가 요건입니다.","소속 국회의원 제명은 당헌 절차 외에 소속 국회의원 전원의 2분의 1 이상 찬성(정당법 제17조·제18조·제33조)":"소속 국회의원 제명은 당헌 절차를 거치고도 소속 국회의원 전원의 2분의 1 이상이 찬성해야 합니다.","소속 정당을 위해 정당활동을 하는 사인의 지위에서는 기본권 주체":"대통령도 정당활동을 하는 사인의 자격이면 기본권의 주체로 인정됩니다.","소송 중 주식이 양도되면 양수인은 그 소송을 승계할 수 있음":"소송 도중 주식이 넘어가면 양수인이 그 소송을 이어받을 수 있습니다.","소수주주도 언제든지 지배주주에게 매수를 청구할 수 있음(제360조의25)":"소수주주도 언제든지 지배주주에게 주식을 사 달라고 청구할 수 있어요.","소음 없는 정온한 환경에서 생활할 권리도 환경권의 내용":"소음 없이 조용한 환경에서 생활할 권리도 환경권의 내용이에요.","소지인은 만기 전에 지급받을 의무가 없고, 약속어음은 지급제시를 하지 않아도 발행인의 책임은 남음":"소지인에게는 만기 이전에 돈을 받아야 할 의무가 없고, 약속어음은 지급제시가 없어도 발행인의 책임이 유지됩니다.","소집권한 없는 자가 이사회 결정 없이 소집, 대부분 주주에게 통지하지 않은 총회 결의는 부존재":"소집권한이 없는 사람이 이사회 결정도 없이 소집하고 대부분 주주에게 알리지 않은 총회의 결의는 존재하지 않는 결의입니다.","손해를 받을 염려가 있는 자나 상호를 등기한 자가 폐지 청구 가능(제23조)":"손해를 받을 염려가 있는 사람이나 상호를 등기한 사람이 폐지를 청구할 수 있어요.","수리·심사와 처리결과 통지를 요구하는 권리":"청원권은 청원을 수리하고 심사하며 결과를 통지해 달라고 요구하는 권리예요.","수사기관의 통신자료 제공요청은 강제력 없는 임의수사":"통신자료 제공요청은 강제하는 힘이 없어 임의수사로 분류합니다.","수용자가 내보내는 서신을 모두 봉함하지 않고 제출하게 하는 것도 통신비밀의 자유 침해":"수용자가 내보내는 편지를 봉하지 못하게 하고 낼 때 모두 제출하게 하는 것은 통신비밀을 침해합니다.","수용 주체는 국가에 한정되지 않아 민간도 될 수 있으나, 고급골프장처럼 공익성이 낮은 사업의 민간개발자에게 수용권을 준 조항은 공공필요에 어긋나 위헌":"수용 주체는 민간도 될 수 있지만, 공익성이 낮은 골프장 사업에 수용권을 준 조항은 공공필요에 어긋나 위헌이에요.","수익적 급부행정은 완화하여 적용":"혜택을 주는 급부행정 규정은 명확성을 느슨하게 적용합니다.","수인이 그 1인 또는 전원에게 상행위가 되는 행위로 채무를 부담하면 연대책임":"채무를 진 여러 사람 가운데 한 명 또는 전원에게 상행위가 되면 모두 연대책임을 집니다.","수취인이 백지인 어음은 인도로 양도할 수 있고, 지급기일을 공란으로 발행한 어음은 일람출급이 아니라 백지어음으로 추정되며, 보충권 없는 불완전어음이라는 점은 발행인이 증명해야 함":"수취인이 백지인 어음은 인도로 양도할 수 있고, 지급기일을 비워 발행한 어음은 일람출급이 아니라 백지어음으로 추정해요.","수표의 이자 약정과 환어음의 지급무담보 문구는 적지 않은 것으로 보고 인수무담보 문구는 유효하며 금액을 글자와 숫자로 다르게 적으면 글자로 적은 금액에 따름":"수표에 이자 약정을 적어도 효력이 없고, 금액을 글자와 숫자로 다르게 적으면 글자로 적은 금액이 우선합니다.","시·도당은 1천인 이상의 당원을 보유":"각 시·도당에는 당원이 1천인 이상 있어야 해요.","시행 중인 법령의 효력을 정지하는 가처분은 파급효과가 커서 더 신중하게 판단":"이미 시행 중인 법령을 멈추게 하는 가처분은 영향이 크므로 한층 조심스럽게 판단합니다.","신고 등 규정 적용 안 됨(집회 및 시위에 관한 법률 제6조 제1항·제15조)":"열거된 목적의 집회에는 옥외집회 신고 등 규정이 적용되지 않아요.","신고서는 시작 720시간 전부터 48시간 전까지 관할 경찰서장에게 제출":"관할 경찰서장은 시작 720시간 전부터 48시간 전까지 들어온 신고서를 받습니다.","신분과 정치적 중립이 보장되는 공무원":"신분과 정치적 중립을 보장받는 공무원은 직업공무원을 가리키는 좁은 범위입니다.","신속한 재판을 받을 권리는 명시(헌법 제27조 제3항)":"신속한 재판을 받을 권리는 헌법 제27조 제3항에 분명히 쓰여 있어요.","신앙의 자유와 달리 종교적 행위의 자유는 절대적 자유 아님":"종교적 행위의 자유는 마음속 신앙의 자유와 달리 제한할 수 있는 자유입니다.","신주발행의 무효는 주주·이사·감사가 발행일부터 6개월 안에 소로만 주장할 수 있고, 그 기간이 지나면 새 무효사유를 추가할 수 없으며 무효원인은 거래안전을 고려해도 묵과할 수 없을 정도의 중대한 위반으로 엄격히 해석(제429조)":"신주발행 무효는 주주·이사·감사가 발행일부터 6개월 안에 소로만 주장할 수 있고, 기간이 지나면 새 무효사유를 추가할 수 없어요.","신주인수권증서가 발행되지 않았으면 신주인수권 양도의 제3자 대항요건은 확정일자 있는 통지나 승낙":"신주인수권증서가 만들어지지 않았다면 신주인수권 양도를 제삼자에게 주장하려면 확정일자 있는 통지나 승낙이 필요합니다.","심판 중 침해가 끝나면 원칙적으로 권리보호이익이 없지만 같은 침해가 반복될 위험이 있고 헌법적 해명이 중대한 의미를 가지면 예외적으로 심판의 이익이 인정":"심판 중 침해가 끝나면 권리보호이익이 없지만, 침해가 반복될 위험이 있고 헌법적 해명이 중요하면 예외로 심판의 이익을 인정해요.","안전보장·안녕질서 방해나 선량한 풍속 해할 염려가 있으면 법원의 결정으로 심리 비공개 가능":"국가안전이나 선량한 풍속 등을 해칠 우려가 있으면 법원이 결정해 재판 심리를 공개하지 않을 수 있습니다.","알고 있는 채권자에게는 따로 최고":"회사가 알고 있는 채권자에게는 따로 최고해야 해요.","액면미달 발행은 회사 성립 후 2년이 지나야 하고 최저발행가액을 정한 주주총회 특별결의와 법원의 인가가 필요(제417조)":"액면미달 발행은 회사 성립 후 2년이 지나야 하고 특별결의와 법원의 인가가 필요해요.","약속어음 발행인과 환어음 인수인에 대한 청구권은 만기일부터 3년, 배서인·발행인에 대한 상환청구권은 거절증서 날짜부터 1년이 지나면 시효로 소멸하고(어음법 제70조), 확정일출급 어음은 지급할 날 또는 그 후 2거래일 안에 제시해야 함":"약속어음 발행인에 대한 청구권은 만기일부터 3년, 배서인·발행인에 대한 상환청구권은 거절증서 날짜부터 1년이 지나면 소멸해요.","약속어음에는 지급인이 없으나 지급지는 적어야 하고, 수표에는 만기와 수취인이 필요 없으며 인수할 수 없고, 은행을 지급인으로 하지 않아도 수표의 효력에는 영향이 없음":"약속어음에는 지급인이 없고 지급지는 적어야 하며, 수표에는 만기와 수취인이 필요 없고 인수할 수 없어요.","약정으로는 그 지역에 한하여 20년까지 금지 가능(제41조)":"약정으로 하면 그 지역에 한해 20년까지 금지할 수 있어요.","양도는 등기하지 않으면 제3자에게 대항 불가(제25조)":"상호 양도는 등기하지 않으면 제3자에게 대항할 수 없어요.","양도인은 다른 약정이 없으면 10년간 동일·인접 특별시·광역시·시·군에서 동종영업 불가":"양도인은 약정이 없으면 10년간 같은 지역과 인접 지역에서 동종영업을 할 수 없어요.","양도인의 채무는 양도 후 2년이 지나면 소멸(제42조·제45조)":"양도인의 채무는 양도 후 2년이 지나면 소멸해요.","양수인은 양도인의 협력 없이 단독으로 양수 사실을 증명해 명의개서를 청구할 수 있음":"주식을 넘겨받은 사람은 양도인의 도움 없이도 스스로 양수 사실을 입증해 명의개서를 청구할 수 있습니다.","양심실현의 자유는 법률로 제한 가능":"양심이 밖으로 드러나는 양심실현의 자유는 법률로 제한할 수 있어요.","양심형성의 자유는 내심에 머무는 한 절대적":"양심형성의 자유는 마음속에 머무는 한 어떤 제한도 받지 않는 절대적 자유입니다.","어음보증은 누구를 위한 것인지 표시하지 않으면 발행인을 위한 것으로 보고, 일부보증과 조건부보증도 할 수 있으며 어음보증인에게는 최고·검색의 항변권이 없음(어음법 제30조·제31조)":"어음보증은 누구를 위한 것인지 표시하지 않으면 발행인을 위한 것으로 보며, 어음보증인에게는 최고·검색의 항변권이 없어요.","어음상 주채무자가 원인관계의 채무자와 다르면 어음은 지급을 위하여 교부된 것으로 추정되고, 기존 채무의 변제기보다 늦은 만기의 어음을 받았으면 지급을 유예한 것으로 봄":"주채무자가 원인관계의 채무자와 다르면 지급을 위한 교부로 추정하고, 만기가 더 늦은 어음이면 지급을 유예한 것으로 봅니다.","어음·수표상 권리가 절차 흠결이나 시효로 소멸하면 소지인은 발행인 등이 원인관계에서 실제로 받은 이익의 한도에서 상환을 청구할 수 있고, 원인채무가 남아 있으면 발행인이 이익을 얻은 것이 아님":"어음·수표상 권리가 소멸하면 소지인은 발행인 등이 실제로 받은 이익의 한도에서 상환을 청구할 수 있어요.","어음의 선의취득에는 배서의 연속에 의한 권리 증명과 취득자에게 악의·중과실이 없을 것이 필요하고, 양도인의 무권리를 의심할 사정이 있는데도 조사 없이 양수하면 중과실":"어음의 선의취득에는 배서의 연속과 취득자의 선의·무중과실이 필요하며, 무권리를 의심할 사정이 있는데 조사 없이 양수하면 중과실이에요.","어음채권으로 청구하면 원인채권의 시효도 중단되지만 원인채권으로 청구한 것만으로는 어음채권의 시효가 중단되지 않음":"어음채권으로 청구하면 원인채권 시효도 끊기지만, 원인채권을 청구한다고 해서 어음채권 시효까지 끊기지는 않습니다.","어음채무자는 종전 소지인에 대한 인적항변으로 소지인에게 대항하지 못하지만 소지인이 채무자를 해할 것을 알고 취득했으면 대항할 수 있고 중대한 과실로 몰랐다는 것만으로는 대항할 수 없음(어음법 제17조)":"어음채무자는 소지인이 채무자를 해할 것을 알고 취득했을 때만 종전 소지인에 대한 인적항변으로 대항할 수 있어요.","엄격한 비례심사를 거쳐 평등권 침해로 위헌":"엄격한 비례심사를 거쳐 평등권을 침해한다며 위헌 결정이 났어요.","업무를 집행하지 않는 사원은 업무집행사원 전원의 동의로 양도 가능, 정관으로 달리 정할 수 있음(제287조의8)":"업무를 집행하지 않는 사원은 업무집행사원 전원의 동의로 양도할 수 있고, 정관으로 달리 정할 수 있어요.","업무집행권과 대표권이 되살아나지 않음":"이미 잃은 업무집행권과 대표권은 되살아나지 않아요.","업무집행권한은 이 소송 외에 정관에 정한 방법이나 총사원의 동의로도 상실 가능":"업무집행권한은 소송 말고도 정관이 정한 방법이나 총사원의 동의로 잃을 수 있습니다.","업무집행이사는 평이사보다 높은 주의의무":"업무집행이사에게는 평이사보다 한 단계 높은 수준의 주의가 요구됩니다.","업무집행지시자(법인 포함)도 이사와 같은 책임(제401조·제401조의2)":"업무집행지시자는 법인이더라도 이사와 같은 책임을 집니다.","여럿이 제기하면 유사필수적 공동소송":"같은 결의를 여러 명이 다투면 유사필수적 공동소송이 됩니다.","여성공무원 채용목표제가 있어도 위헌성이 없어지지는 않음":"여성공무원 채용목표제가 있어도 가산점 제도의 위헌성이 사라지지는 않아요.","여성과 장애인 등의 공직 진입 자체를 막아 공무담임권을 중대하게 제한":"제대군인 가산점은 여성과 장애인 등이 공직에 진입하는 것 자체를 막아 공무담임권을 중대하게 제한했어요.","연소자의 근로는 특별한 보호를 받음(헌법 제32조 제5항)":"연소자의 근로는 헌법 제32조 제5항에 따라 특별한 보호를 받아요.","연장에 총기간 제한이 없던 조항은 통신의 비밀 침해":"연장 횟수에 총기간 제한이 없던 조항은 통신의 비밀을 침해한다고 판단됐어요.","엽관제를 막기 위한 제도적 보장, 최소한 보장의 원칙 적용":"직업공무원제도는 엽관제를 막으려는 제도적 보장이어서 최소한 보장의 원칙을 따릅니다.","영업양도, 합병, 분할합병, 주식의 포괄적 교환·이전 등에 반대하는 주주":"영업양도·합병·분할합병·주식의 포괄적 교환이나 이전에 반대하는 주주에게 매수청구권이 주어집니다.","영업에 관한 재판상·재판 외의 모든 행위 가능":"지배인은 영업에 관한 재판상·재판 외의 모든 행위를 할 수 있어요.","영업에 관한 행위인지는 행위의 객관적 성질로 판단":"영업에 관한 행위에 해당하는지는 그 행위가 객관적으로 어떤 성질인지를 보고 가립니다.","영업을 폐지하거나 영업과 함께 하는 경우에만 양도 가능, 사실상 폐업도 영업폐지에 포함":"상호는 영업을 접거나 영업과 함께일 때만 넘길 수 있으며, 사실상의 폐업도 영업 폐지로 칩니다.","영업주로 오인하고 거래한 제3자에게 명의차용자와 연대책임":"영업주로 잘못 알고 거래한 상대에게는 명의대여자가 명의차용자와 같이 책임을 져야 합니다.","영화 상영등급 분류와 법원의 방영금지가처분은 검열 아님":"영화 상영등급 분류나 법원의 방영금지가처분은 사전검열의 요건을 채우지 못합니다.","예산 변경이 필요하면 정부가 추가경정예산안 제출":"예산을 바꿔야 하면 정부가 추가경정예산안을 따로 제출해요.","예산안 수정동의는 50명 이상, 징계 요구는 20명 이상의 찬성(국회법 제95조·제138조·제156조)":"예산안 수정동의는 50명 이상, 징계 요구는 20명 이상의 찬성이 필요해요.","예산은 국가기관만 구속하고 국민을 직접 구속하지 않음":"예산의 구속 대상은 국가기관이고, 국민에게 직접 의무를 지우는 효력은 없습니다.","예외는 대통령, 국무총리, 국무위원, 국회의원, 지방의회의원":"대통령, 국무총리, 국무위원, 국회의원, 지방의회의원은 이 금지의 예외예요.","예외는 명의개서 청구가 부당하게 지연되거나 거절된 경우뿐이고, 이 법리는 주식양도뿐 아니라 주식발행에도 적용":"예외는 명의개서를 부당하게 미루거나 거절한 경우뿐이고, 이 법리는 신주발행에도 똑같이 쓰입니다.","예외 · 임기연장이나 중임변경을 위한 개정은 제안 당시의 대통령에게 효력 없음(헌법 제128조~제130조)":"임기연장이나 중임변경 개정은 그 개정을 제안한 당시의 대통령에게는 적용되지 않습니다.","완전모회사가 될 회사가 완전자회사가 될 회사 주식의 90% 이상을 가지면":"완전모회사가 될 회사가 완전자회사가 될 회사의 주식을 90% 이상 보유하고 있을 때가 요건입니다.","완전모회사가 발행하는 신주나 이전하는 자기주식을 받음":"주식교환에서 완전모회사가 발행하는 신주나 이전하는 자기주식을 교환 대가로 받아요.","완전자회사가 되는 회사의 주주가 완전모회사의 주주가 됨":"주식교환이 이뤄지면 완전자회사가 되는 회사의 주주들이 완전모회사의 주주로 바뀝니다.","완전자회사의 주주총회 승인을 이사회 승인으로 갈음 가능":"이때 완전자회사의 주주총회 승인을 이사회 승인으로 대신할 수 있어요.","외국인은 원칙적으로 주체가 아니나 일할 환경에 관한 권리는 인정":"외국인은 근로의 권리 주체가 되기 어렵지만 일할 환경에 관한 권리는 누릴 수 있습니다.","요건과 절차를 어긴 취득은 당연무효이고 사후에 갖추어도 유효해지지 않으며 제3자 명의라도 회사 자금으로 취득하고 손익이 회사에 귀속되면 자기주식 취득":"절차나 요건을 어긴 자기주식 취득은 당연히 무효이고, 남의 이름을 빌렸더라도 회사 돈으로 사서 손익이 회사에 돌아가면 자기주식 취득입니다.","요건을 갖추어 발생하면 재산권 보호대상":"요건을 갖춰 이미 발생한 수급권은 재산권으로 보호받아요.","원고가 소송 중 주주 지위를 잃으면 원고적격 상실":"소송 중에 원고가 주주의 지위를 잃으면 소를 낼 자격도 함께 사라집니다.","원장은 국회의 동의를 얻어, 감사위원은 원장의 제청으로 국회 동의 없이 대통령이 임명하고 모두 임기 4년에 1차 중임할 수 있음(헌법 제98조)":"감사원장은 국회 동의를 얻어, 감사위원은 원장의 제청으로 대통령이 임명하며 임기는 4년에 1차 중임할 수 있어요.","위반 거래에 대한 개입권은 거래일부터 1년 안에 행사(제397조)":"위반 거래에 대한 개입권은 거래일부터 1년 안에 행사해야 해요.","위반하면 회사는 자기 계산으로 한 거래를 회사 계산으로 볼 수 있음(제198조)":"위반하면 회사는 사원이 자기 계산으로 한 거래를 회사 계산으로 한 것으로 볼 수 있어요.","위원 해임은 이사 총수 3분의 2 이상의 이사회 결의(제415조의2)":"감사위원을 해임하려면 이사 총수 3분의 2 이상의 이사회 결의가 필요해요.","위임관계에 따른 채무불이행책임, 시효 10년(제399조)":"이사의 회사에 대한 책임은 위임관계에 따른 채무불이행책임이며 시효는 10년이에요.","위조수표를 할인해 취득한 자의 손해는 액면금이 아니라 실제로 낸 할인금 상당액":"위조수표를 할인해 사 들인 사람이 입은 손해는 액면금이 아니라 실제 낸 할인금 상당액입니다.","위치추적 전자장치 부착명령은 비형벌적 보안처분이라 소급효금지원칙 적용 안 됨":"위치추적 전자장치 부착은 형벌이 아닌 보안처분이라 소급효금지원칙이 적용되지 않아요.","위탁매매인은 상대방이 채무를 이행하지 않으면 위탁자에게 이행할 책임":"위탁매매의 상대방이 의무를 이행하지 않으면 위탁매매인이 대신 위탁자에게 이행해야 합니다.","위탁매매인이 이를 자기 채무의 담보로 양도해도 위탁자에게 효력 없음":"위탁매매인이 자기 빚의 담보로 그것을 넘겼더라도 위탁자에게는 효력이 없습니다.","위헌결정된 법률은 결정이 있는 날부터 효력을 잃지만 형벌 조항은 소급하여 효력을 잃고, 종전에 합헌결정이 있었으면 그 결정이 있은 날의 다음 날로 소급하며 그에 근거한 유죄 확정판결에는 재심을 청구할 수 있음(헌법재판소법 제47조)":"위헌결정된 법률은 결정일부터 효력을 잃지만, 형벌 조항은 소급하여 효력을 잃고 유죄 확정판결에는 재심을 청구할 수 있어요.","위헌법률심판의 대상에는 형식적 법률뿐 아니라 조약, 일반적으로 승인된 국제법규, 법률과 같은 효력의 관습법도 포함되지만 헌법 조항 자체는 포함되지 않음":"위헌법률심판 대상에는 조약과 법률과 같은 효력의 관습법이 들어가지만 헌법 조항 자체는 들어가지 않아요.","유통시킬 의사로 기명날인한 어음이 도난·분실로 유통되었어도 발행인은 배서가 연속된 어음을 선의로 취득한 소지인에게 책임을 지고, 소지인의 악의·중과실은 발행인이 증명해야 함":"유통할 마음으로 서명한 어음이 도난·분실로 돌아다녀도, 발행인은 선의로 취득한 소지인에게 책임을 져야 합니다.","유한책임사원은 출자액 한도에서 회사채권자에게 직접 책임":"유한책임사원은 자기 출자액 범위 안에서 회사채권자에게 바로 책임을 집니다.","유한회사와 주식회사가 합병하여 주식회사가 남으면 법원의 인가를 얻어야 효력 발생(제600조)":"유한회사가 주식회사와 합병해 주식회사로 남는 경우에는 법원 인가를 받아야 합병이 유효합니다.","융통어음이라는 항변은 제3자의 선의·악의와 상관없이 대항할 수 없지만 교환으로 받은 담보어음이 지급거절된 사정을 알고 취득한 제3자에게는 대항할 수 있음":"융통어음이라는 항변은 제삼자의 선의·악의와 관계없이 막히지만, 담보어음이 지급거절된 사정을 알고 취득한 제삼자에게는 통합니다.","음란 간행물 출판사 등록취소는 언론·출판의 자유를 중심으로 판단":"음란 간행물 출판사의 등록취소 사건은 언론·출판의 자유를 중심으로 심사했어요.","응시 횟수나 합격 경력과 상관없이 계속 가산점 부여":"응시 횟수나 합격 경력과 관계없이 가산점이 계속 주어진다는 점이 문제였어요.","의결권 불통일행사는 총회일 3일 전까지 회사에 통지 도달":"의결권 불통일행사를 하려면 총회일 3일 전까지 그 통지가 회사에 닿아야 합니다.","의결권이 없거나 제한되는 종류주식은 우선주가 아니어도 발행할 수 있으나 발행주식총수의 4분의 1을 넘지 못하고, 액면주식은 1주 100원 이상으로 균일해야 함":"의결권이 제한되는 종류주식은 발행주식총수의 4분의 1을 넘을 수 없고, 액면주식은 1주 100원 이상으로 균일해야 해요.","의결권이 없는 주주를 포함하여 총회 전에 서면으로 반대 의사를 통지":"의결권이 없는 주주도 청구할 수 있으나, 총회 전에 반대 의사를 서면으로 알려야 합니다.","의료법상 무면허 의료행위 금지와 관련한 외국인의 직업의 자유":"무면허 의료행위를 금지한 의료법과 관련해 외국인의 직업의 자유가 문제 된 사안이에요.","의사록에 이의 기재가 없으면 찬성으로 추정, 기권으로 기재되었으면 추정되지 않음":"의사록에 이의 기재가 없으면 찬성으로 추정하고, 기권으로 적혔다면 추정하지 않아요.","의원 자격심사 청구는 30명 이상의 찬성":"의원 자격심사를 청구하려면 30명 이상의 찬성이 있어야 해요.","의원 제명과 헌법개정안 의결은 모두 재적의원 3분의 2 이상":"의원 제명과 헌법개정안 의결은 재적의원 3분의 2 이상의 찬성이 있어야 합니다.","의장은 표결권을 가지고 가부동수일 때 결정권을 가짐":"의장도 투표할 수 있고, 찬성과 반대가 같은 수이면 의장이 결정합니다.","이 경우 퇴임등기 기간은 후임자 취임일부터 계산":"이때 퇴임등기를 해야 하는 기간은 후임자가 취임한 날부터 셉니다.","이 규정은 매수인이 상인이면 매도인이 상인인지와 상관없이 적용되는 임의규정":"매수인이 상인이기만 하면 매도인이 상인이든 아니든 적용되고, 당사자가 달리 정할 수 있는 규정입니다.","이득상환청구권은 지명채권이어서 지명채권 양도 방법으로 양도하고 선의취득이 인정되지 않으며 제시기간이 지난 자기앞수표는 이를 증명하는 증거증권일 뿐":"이득상환청구권은 지명채권이라 지명채권 양도 방법으로 양도하고 선의취득이 인정되지 않아요.","이들이 50% 이상 지분을 가진 회사":"이들이 지분 50% 이상을 가진 회사가 거래 상대방일 때도 자기거래로 규제합니다.","이때 그 법인은 직무를 행할 자를 선임해야 함":"법인이 업무집행자가 되면 직무를 실제로 행할 사람을 선임해야 해요.","이때도 소멸회사 반대주주의 주식매수청구권 인정":"간이합병에서도 소멸회사의 반대주주에게는 주식매수청구권이 있어요.","이론적 가능성에 그치지 않고 실효적으로 출생등록이 되게 제도 마련":"국가는 출생등록이 이론에 그치지 않고 실제로 이뤄지게 하는 제도를 마련해야 해요.","이를 모두 갖춘 사전검열만 금지":"금지되는 것은 이 요건을 모두 갖춘 사전검열뿐입니다.","이를 이유로 한 차별도 절대적으로 금지되지는 않음":"그런 사유에 의한 차별이라도 헌법상 절대 금지라고까지 할 수는 없습니다.","이 보상은 금전보상에 한정되지 않고 매수청구권 같은 방법도 가능":"보상은 꼭 현금이 아니어도 되고 매수청구권 같은 방식으로 줄 수도 있습니다.","이사, 주요주주, 그 배우자와 직계존비속, 배우자의 직계존비속":"자기거래를 규제하는 사람의 범위는 이사, 주요주주, 이들의 배우자, 직계존비속, 배우자의 직계존비속입니다.","이사가 없으면 이해관계인의 청구로 법원이 선임":"청산인이 될 이사가 없으면 이해관계인이 청구해 법원이 청산인을 지정합니다.","이사가 존속을 허용할 수 없는 위법행위를 한 경우":"이사가 회사의 존속을 허용할 수 없을 만큼 위법행위를 한 경우도 해산명령 사유예요.","이사 과반수 출석과 출석이사 과반수로 결의(정관으로 가중 가능)":"이사회는 이사 과반수 출석과 출석이사 과반수 찬성으로 결의하며 정관으로 요건을 높일 수 있어요.","이사는 대표이사와 다른 이사의 업무집행을 감시할 의무":"이사에게는 대표이사와 다른 이사들이 업무를 제대로 집행하는지 지켜볼 감시의무가 있습니다.","이사는 주주총회 보통결의로 선임, 선임결의와 승낙만으로 지위 취득":"이사는 주주총회 보통결의로 선임되고, 선임결의에 본인이 승낙하기만 하면 이사가 됩니다.","이사의 경업은 이사회의 일반 결의로 승인":"이사가 경업을 하려면 이사회의 일반 결의로 승인을 받아야 해요.","이사 총수의 3분의 1 이상을 두어야 함(2026.7.23. 시행)":"독립이사는 이사 총수의 3분의 1 이상이어야 하고, 이 규정은 2026.7.23.부터 시행됩니다.","이사회결의 무효확인 판결에는 대세효가 없음":"이사회결의 무효확인 판결은 소송 당사자 밖의 사람에게까지 미치는 효력이 없습니다.","이사회 결의에 따른 것이면 찬성한 이사도 연대책임":"이사회 결의에 따라 한 행위로 회사에 손해가 생기면 거기에 찬성한 이사도 함께 책임집니다.","이사회 결정을 거쳐 대표이사 아닌 이사가 소집, 일부 주주 통지 누락은 취소사유":"이사회 결정을 거쳐 대표이사 아닌 이사가 소집했거나 일부 주주에게 통지를 빠뜨린 것은 취소사유예요.","이유는 경위와 목적을 구체적으로 적으면 되고 뒷받침 자료를 첨부할 필요는 없으며 소송 중 지분이 3% 미만이 되면 당사자적격을 잃고, 주식매수청구 후 대금을 받지 못한 주주도 청구할 수 있음":"이유는 경위와 목적을 구체적으로 적으면 되고, 소송 중 지분이 3% 미만이 되면 당사자적격을 잃어요.","이중양수인이나 양도담보권자와 압류채권자 사이의 우열은 명의개서와 상관없이 확정일자 있는 통지·승낙과 압류명령 송달의 선후로 정하고, 확정일자를 나중에 받으면 그때부터 대항력이 생김":"이중양수인과 압류채권자 사이의 우열은 명의개서가 아니라 확정일자 있는 통지·승낙과 압류명령 송달의 선후로 정해요.","이중처벌금지의 처벌은 국가 형벌권 행사만을 의미":"이중처벌금지가 막는 것은 국가가 형벌권을 거듭 행사하는 일뿐입니다.","이해관계인·검사의 청구나 직권으로 해산 명령":"해산명령은 이해관계인이나 검사의 청구 또는 법원의 직권으로 할 수 있어요.","이해관계인이 청구하면 회사의 청구로 담보 제공을 명할 수 있음(제176조)":"이해관계인이 청구하면 회사의 청구로 법원이 담보를 제공하라고 명할 수 있어요.","이행청구를 받은 때부터 지체책임":"이사의 책임은 이행청구를 받은 순간부터 지체가 시작되는 지체책임입니다.","인간다운 생활 보장 의무 위반은 다음 경우에만 위헌":"인간다운 생활을 보장할 의무를 어겨 위헌이 되는 경우는 아래 두 가지뿐이에요.","인감증명서가 없어도 다른 방법으로 위임사실을 증명하면 회사는 대리권 부정 불가":"인감증명서가 없더라도 위임을 다른 방법으로 입증하면 회사가 대리권을 부정할 수 없습니다.","인사청문회는 국회법과 인사청문회법에 근거":"인사청문회를 열 수 있는 근거는 국회법과 인사청문회법 두 법률입니다.","인수자 없는 시체를 본인 의사와 무관하게 해부용으로 제공하면 시체처분 자기결정권 침해":"본인 의사와 무관하게 인수자 없는 시체를 해부용으로 제공하면 시체처분 자기결정권을 침해해요.","인터넷게시판 본인확인제와 선거운동기간 인터넷언론사 실명확인제는 위헌(공직선거법 제82조의6은 2023년 삭제)":"본인확인제와 실명확인제는 위헌이었고, 공직선거법 제82조의6은 2023년에 아예 삭제됐습니다.","인·허가나 사업자등록 명의와 실제 영업주체가 다르면 실제 영업주체가 상인":"사업자등록 명의와 실제 영업주체가 다르면 실제 영업을 하는 쪽이 상인이에요.","일반사면에는 국회의 동의가 필요하고 특별사면에는 필요 없음(헌법 제79조 제2항)":"일반사면에는 국회의 동의가 필요하지만 특별사면에는 필요하지 않아요.","일반사면에는 국회의 동의 필요":"일반사면은 대통령이 하지만 국회의 동의를 받아야 해요.","일반적 인격권과 사생활의 비밀과 자유에서 나옴(헌법 제10조·제17조)":"개인정보 자기결정권은 일반적 인격권과 사생활의 비밀과 자유에서 도출됩니다.","일반적 인격권은 인간의 존엄에서 나오고 자기결정권은 그 파생":"자기결정권은 일반적 인격권에서 갈라져 나온 권리이고, 일반적 인격권의 뿌리는 인간의 존엄입니다.","일반적 행동자유권에 기부행위·생활방식·취미·위험한 스포츠를 즐길 권리 포함":"기부, 생활방식, 취미, 위험한 스포츠 같은 선택도 일반적 행동자유권이 지켜 줍니다.","일방적·보조적 상행위로 인한 채권도 5년":"한쪽에만 상행위이거나 보조적 상행위로 생긴 채권도 소멸시효가 5년이에요.","일방적 상행위로 생긴 채권도 같고 질권설정자가 상인일 필요는 없음(제59조)":"한쪽만 상행위로 생긴 채권에도 마찬가지이고, 질권설정자가 상인일 필요도 없어요.","일부 선거구 획정이 위헌이면 선거구구역표 전체에 위헌 선언":"선거구 일부가 위헌이면 선거구구역표 전체가 위헌이라고 선언됩니다.","일부 양도와 묵시적 계약도 가능, 근로관계는 원칙적으로 양수인에게 포괄 승계":"영업의 일부만 넘기거나 묵시적으로 계약해도 되고, 근로관계는 원칙적으로 양수인이 통째로 이어받습니다.","일시 차입금으로 납입 외형을 갖추고 설립 후 곧 인출해 갚는 가장납입도 납입으로서 효력이 있어 주식인수인은 바로 주주가 되고 납입의무도 끝나며, 명의차용인과 명의대여자의 연대납입책임 규정(제332조 제2항)은 적용되지 않음":"가장납입도 납입으로서 효력이 있어 주식인수인은 바로 주주가 되고, 명의차용인과 명의대여자의 연대납입책임은 적용되지 않아요.","일할 자리에 관한 권리와 일할 환경에 관한 권리를 함께 뜻함":"근로의 권리에는 일할 자리를 구하는 권리와 일하는 환경을 보장받는 권리가 함께 있습니다.","임기는 취임 후 3년 내 최종 결산기의 정기총회 종결 시까지":"감사의 임기는 취임 후 3년 안의 마지막 결산기 정기총회가 끝날 때까지예요.","임기만료나 사임으로 정원이 부족해지면 퇴임이사가 후임자 취임 시까지 권리의무":"임기만료나 사임으로 이사 수가 모자라게 되면 퇴임이사가 후임자 취임 때까지 이사의 권리의무를 가집니다.","임기만료 시에는 70일 내지 40일 전에, 궐위 시에는 60일 이내에 후임자를 선거하고, 궐위로 인한 선거로 뽑힌 대통령의 임기는 당선이 결정된 때부터 시작(공직선거법 제14조 제1항)":"임기만료 선거는 70일 내지 40일 전에, 궐위 선거는 60일 이내에 하며, 궐위 선거 당선자의 임기는 당선 결정 때부터 시작해요.","임명동의 대상자와 국회 선출 헌법재판소 재판관·중앙선거관리위원회 위원":"임명동의 대상자와 국회가 선출한 헌법재판소 재판관·중앙선거관리위원회 위원은 인사청문특별위원회에서 청문해요.","임시정부 법통 계승 선언에서 독립유공자와 그 유족 예우의 헌법적 의무가 나옴":"전문의 임시정부 법통 계승 선언을 근거로 독립유공자와 유족을 예우할 헌법상 의무가 나옵니다.","임시회는 대통령 또는 국회재적의원 4분의 1 이상의 요구로 집회":"임시회는 대통령이나 재적의원 4분의 1 이상이 요구하면 소집됩니다.","임신 32주 이전 태아 성별 고지 금지도 위헌":"임신 32주 이전에는 태아 성별을 알리지 못하게 한 금지 조항도 위헌이에요.","임의적 규정으로 목적 달성이 가능하면 개별 사정을 고려할 여지 없는 필요적 규정은 최소침해성 위반":"임의적 규정으로 충분한데 일률적인 필요적 규정을 두면 최소침해성을 어기는 것이 됩니다.","자격요건 설정은 입법재량이 넓어 현저히 불합리한 경우에만 위헌":"자격요건은 입법재량이 넓어서 현저히 불합리할 때에만 위헌이 됩니다.","자기낙태죄 조항은 2019년 헌법불합치 결정, 개선입법 시한(2020.12.31.) 경과로 효력 상실":"자기낙태죄 조항은 헌법불합치 결정 뒤 개선입법 시한이 지나도록 법이 바뀌지 않아 효력이 사라졌습니다.","자기낙태죄 조항은 임신한 여성의 자기결정권과 태아 생명 보호의 형량 문제":"자기낙태죄는 임신한 여성의 자기결정권과 태아 생명 보호를 저울질하는 형량의 문제예요.","자기 명의로 상행위를 하는 자, 자기 명의는 실질로 판단":"상인은 자기 명의로 상행위를 하는 사람이며, 자기 명의인지는 실질을 보고 판단해요.","자기 명의로 타인의 계산으로 매매, 명의와 계산의 분리가 본질":"위탁매매는 자기 명의로 타인의 계산으로 하는 매매이며, 명의와 계산이 갈라지는 점이 본질이에요.","자기 성명이나 상호로 영업할 것을 허락한 명의대여자":"명의대여자는 자기 성명이나 상호로 영업하도록 허락한 사람이에요.","자녀의 출생등록될 권리 침해(헌법불합치)":"이 조항은 자녀의 출생등록될 권리를 침해해 헌법불합치 결정을 받았어요.","자동차를 훔친 경우 운전면허를 필요적으로 취소하는 조항":"자동차를 훔치기만 해도 운전면허를 반드시 취소하게 한 조항이에요.","자본금 10억원 미만 회사는 감사를 두지 않을 수 있음":"자본금이 10억원에 못 미치는 회사는 감사를 두지 않아도 법에 어긋나지 않습니다.","자본금 1천만원 미만의 회사 아닌 소상인":"소상인은 자본금 1천만원 미만의 회사가 아닌 상인을 말해요.","자본금 감소는 주주총회 특별결의로 하지만 결손 보전을 위한 감소는 보통결의로 할 수 있음(제438조)":"자본금 감소는 특별결의가 원칙이지만 결손 보전을 위한 감소는 보통결의로 할 수 있어요.","자산 2조원 이상 상장회사는 감사위원 2명 이상을 분리선출":"자산 2조원 이상 상장회사는 감사위원 2명 이상을 다른 이사와 따로 뽑아야 합니다.","자유권과 사회적 기본권의 성격을 함께 가짐":"자유권으로서 간섭을 막는 면과, 사회적 기본권으로서 국가의 도움을 구하는 면이 함께 있습니다.","자유선거원칙은 헌법에 명문 규정 없음":"자유선거원칙은 헌법 조문에 직접 쓰여 있지 않아요.","자치사무와 단체위임사무는 조례로 제정":"자치사무와 단체위임사무는 지방의회가 조례로 정할 수 있어요.","자회사는 주식의 포괄적 교환·이전, 합병, 영업전부 양수, 권리 실행의 경우가 아니면 모회사 주식을 취득할 수 없고, 예외적으로 취득해도 6개월 안에 처분해야 함(제342조의2)":"자회사는 예외 사유가 아니면 모회사 주식을 취득할 수 없고, 예외로 취득해도 6개월 안에 처분해야 해요.","자회사 이사에 대한 다중대표소송 제기 가능":"이런 주주는 자회사 이사에 대한 다중대표소송을 제기할 수 있어요.","재결서처럼 이유를 명시할 것까지 요구할 수는 없음":"재결서처럼 이유까지 밝히라고 요구할 수는 없어요.","재산권은 재산가치 있는 모든 사법상·공법상 권리를 포함하지만 공법상 권리는 자기 노력이나 기여의 대가여야 하므로 기초생활보장수급권 같은 사회부조는 제외되고 공무원 퇴직연금수급권과 건강보험수급권은 포함":"공법상 권리는 본인 기여의 대가일 때만 재산권이라 사회부조는 빠지고 퇴직연금수급권은 들어갑니다.","재산권 행사가 사회적 연관성을 가질수록 넓은 제한이 허용되고, 토지는 다른 재산권보다 강하게 공동체 이익을 관철할 수 있음":"재산권은 사회적 연관성이 클수록 제한을 넓게 받으며, 토지는 공동체 이익을 더 강하게 요구받아요.","재심사유는 입법정책의 문제, 현저히 자의적일 때만 위헌":"재심 사유를 어디까지 둘지는 입법정책이어서 현저히 자의적인 경우에만 위헌이 됩니다.","재의결 등으로 확정된 법률이 정부에 이송된 후 5일 이내에 대통령이 공포하지 않으면 국회의장이 공포(헌법 제53조 제6항)":"확정된 법률을 대통령이 5일 이내에 공포하지 않으면 국회의장이 공포해요.","재의 요구된 법률안은 재적의원 과반수 출석, 출석의원 3분의 2 이상 찬성으로 다시 의결":"재의가 요구된 법률안은 재적의원 과반수가 출석한 자리에서 출석의원의 3분의 2 이상이 찬성하면 다시 의결됩니다.","재정조달목적 부담금은 조세에 대해 예외적으로만 인정되고, 납부의무자가 공적 과제와 특별히 밀접한 관련이 있어야 하며 장기간 유지되면 입법자가 그 타당성을 계속 심사해야 함":"재정조달 부담금은 조세의 예외라서, 납부자와 공적 과제의 밀접한 관련이 필요하고 오래가면 타당성을 재심사해야 합니다.","재판관 7명 이상 출석으로 심리하고 관여 재판관 과반수로 결정하지만 법률의 위헌결정, 탄핵결정, 정당해산결정, 헌법소원 인용결정, 종전 판례 변경에는 6명 이상의 찬성이 필요(헌법재판소법 제23조)":"심리는 재판관 7명 이상 출석으로 하고, 위헌결정·탄핵결정·정당해산결정에는 6명 이상의 찬성이 필요해요.","재판관의 임기는 6년이고 연임할 수 있으며 정년은 70세이고, 정당 가입과 정치 관여가 금지되며 탄핵 또는 금고 이상의 형의 선고 없이는 파면되지 않음":"재판관은 임기 6년에 연임할 수 있고 70세에 정년이며, 정당 가입과 정치 관여가 금지됩니다.","재판상 행위에는 권한이 없고 근무지가 영업소의 실체를 갖추어야 함(제14조)":"표현지배인은 재판상 행위 권한이 없고, 근무지가 영업소의 실체를 갖춰야 해요.","재판의 전제성은 구체적 사건이 법원에 계속 중이고, 그 법률이 당해 재판에 적용되며, 위헌 여부에 따라 주문이나 재판의 내용·효력의 법률적 의미가 달라지는 경우를 말하고, 여기서 재판에는 소송절차에 관한 재판과 중간재판도 포함":"재판의 전제성은 법원에 사건이 계속 중이고, 그 법률이 적용되며, 위헌 여부에 따라 재판 내용이 달라지는 경우를 말해요.","적부심사는 법원에 청구(헌법 제12조)":"체포·구속 적부심사는 법원에 청구해 적법성을 다투는 절차예요.","전자장치 부착명령과 디엔에이 감식시료 채취는 비형벌적 보안처분":"전자장치 부착과 디엔에이 시료 채취는 형벌이 아닌 보안처분으로 분류합니다.","전환권은 형성권이어서 전환을 청구한 때 주주가 되고 그 후에는 전환 금지를 구할 이익이 없으며 신주인수권부사채는 신주인수권을 행사하고 납입을 마친 때 주주가 됨(제516조의10)":"전환권은 형성권이어서 전환 청구 시점에 주주가 되고, 신주인수권부사채는 권리 행사와 납입을 마친 때 주주가 됩니다.","전환사채 발행무효의 소를 제기하지 못했어도 전환권 행사로 발행된 신주는 그 신주 발행일부터 6개월 안에 신주발행무효의 소로 다툴 수 있음":"전환권을 행사해 나온 신주는 전환사채 발행무효의 소를 놓쳤어도 신주 발행일부터 6개월 안에 신주발행무효의 소로 다툴 수 있습니다.","전환사채와 신주인수권부사채 발행에도 신주발행무효의 소 규정이 유추적용되어 발행일부터 6개월의 제소기간이 적용되지만 발행 실체가 없는 경우의 부존재확인의 소에는 이 기간 제한이 없음":"사채 발행에도 신주발행무효의 소가 유추적용되어 6개월 제소기간이 있지만, 발행 실체가 없으면 부존재확인의 소에는 기간 제한이 없어요.","정관에 적어야 효력이 생기는 변태설립사항은 발기인의 특별이익, 현물출자, 재산인수, 회사가 부담할 설립비용과 발기인의 보수액(제290조)":"발기인의 특별이익, 현물출자, 재산인수, 설립비용과 보수액은 정관에 적어야만 효력이 있는 변태설립사항입니다.","정관에 적힌 사원의 책임(무한·유한)을 바꾸는 것은 정관변경":"정관에 적힌 사원의 책임을 무한에서 유한으로 바꾸는 것은 정관변경에 해당해요.","정관에 정한 특정 이사의 보수액은 사원총회 결의로 감액하거나 박탈할 수 없음":"정관에 정한 특정 이사의 보수액은 사원총회 결의로 줄이거나 빼앗을 수 없어요.","정관에 정함이 없으면 발행할 신주의 종류와 수는 이사회가 정하고, 신주 인수인이 납입기일에 납입하지 않으면 별도 실권절차 없이 권리를 잃으며 납입한 인수인은 납입기일 다음 날부터 주주가 됨(제423조)":"신주 인수인이 납입기일을 넘기면 별도 절차 없이 권리를 잃고, 납입한 인수인은 납입기일 다음 날부터 주주입니다.","정관으로는 주식양도에 이사회 승인을 받게 할 수 있을 뿐 양도를 전면 금지할 수 없고, 승인 없는 양도는 회사에 효력이 없으나 당사자 사이에서는 유효":"정관으로 주식양도에 이사회 승인을 요구할 수는 있어도 양도를 전면 금지할 수는 없고, 승인 없는 양도도 당사자 사이에서는 유효해요.","정관으로 최근 1년 보수의 6배(사외이사와 독립이사는 3배)를 넘는 부분 면제(제400조)":"정관으로 최근 1년 보수의 6배, 사외이사와 독립이사는 3배를 넘는 부분을 면제할 수 있어요.","정관은 공증인의 인증으로 효력이 생기지만 자본금 10억원 미만 회사를 발기설립하면 인증이 필요 없음(제292조)":"정관은 공증인의 인증을 받아야 효력이 생기지만, 자본금 10억원 미만의 발기설립 회사는 인증이 면제됩니다.","정관의 양도 요건을 갖추지 못한 양도는 무효":"정관이 정한 양도 요건을 갖추지 않고 한 양도는 효력이 없습니다.","정관의 절대적 기재사항은 목적, 상호, 발행예정주식총수, 액면주식 1주의 금액, 설립 시 발행주식총수, 본점 소재지, 공고방법, 발기인의 성명·주민등록번호·주소(상법 제289조)":"정관의 절대적 기재사항은 목적, 상호, 발행예정주식총수, 본점 소재지, 공고방법, 발기인의 인적사항 등이에요.","정관이나 주주총회로 달리 정하지 않으면 해산 당시의 이사가 청산인":"정관이나 총회에서 따로 정하지 않았다면 해산 당시의 이사가 그대로 청산인을 맡습니다.","정기회는 법률이 정하는 바에 따라 매년 1회 집회":"정기회는 법률이 정한 시기에 해마다 한 번 열립니다.","정기회 회기는 100일, 임시회 회기는 30일을 넘을 수 없음(헌법 제47조)":"정기회는 100일, 임시회는 30일을 넘길 수 없다고 헌법 제47조가 정해요.","정당 가입과 정치 관여 금지":"선관위 위원은 정치적 중립을 위해 정당 가입과 정치 관여가 금지됩니다.","정당설립의 자유와 복수정당제 보장(헌법 제8조)":"헌법 제8조는 정당을 자유롭게 설립할 수 있고 여러 정당이 존재하는 복수정당제를 보장합니다.","정당은 5 이상의 시·도당을 보유":"정당은 시·도당을 5개 이상 두어야 합니다.","정당한 사유 없이 설립 후 1년 내에 영업을 개시하지 않거나 1년 이상 휴업한 경우":"정당한 사유 없이 설립 후 1년 내에 영업을 시작하지 않거나 1년 이상 쉬는 경우도 해산명령 사유예요.","정당한 이유가 없다는 증명책임은 이사에게 있음, 임기는 3년을 넘지 못함":"정당한 이유가 없었다는 점은 이사가 입증해야 하며 이사의 임기는 3년을 넘기지 못합니다.","정당해산 제소, 사면, 임시회 집회 요구, 각군참모총장·국립대학교총장 임명, 행정각부 간 권한 획정은 심의사항이지만 조약 체결·비준 자체는 열거되어 있지 않고 조약안이 심의사항":"조약 체결·비준 자체는 심의사항으로 열거되지 않고, 조약안이 심의사항이에요.","정보비공개결정이나 국가인권위원회의 진정 각하·기각결정은 행정심판·행정소송을 거치지 않으면 보충성을 갖추지 못함":"정보비공개결정이나 진정 각하·기각결정은 행정심판·행정소송을 먼저 거쳐야 보충성이 충족됩니다.","정부가 국무회의 심의를 거쳐 해산심판 청구":"정부가 국무회의 심의를 거쳐 헌법재판소에 정당 해산을 청구하는 절차예요.","정부는 회계연도 개시 90일 전까지 예산안 제출":"정부는 회계연도가 시작되기 90일 전까지 예산안을 국회에 내야 해요.","정부 허가로 비로소 생기는 권리라 보아 헌재가 주체성 부정":"직업의 자유를 정부 허가로 비로소 생기는 권리로 보아 외국인의 주체성을 부정했어요.","제1회 보험료를 내지 않고 계약 성립 후 2개월이 지나면 계약은 해제된 것으로 보고, 계속보험료를 연체하면 보험자는 상당한 기간을 정해 최고한 뒤 해지할 수 있으며 특정한 타인을 위한 보험이면 그 타인에게도 최고해야 함(제650조)":"제1회 보험료를 내지 않고 2개월이 지나면 계약은 해제된 것으로 보고, 연체하면 상당한 기간을 정해 최고한 뒤 해지할 수 있어요.","제3자는 선의이면 족하고 무과실은 불필요, 중과실이 있으면 보호받지 못함(제395조)":"표현대표이사에서 제3자는 선의이면 되고 무과실은 필요 없지만, 중과실이 있으면 보호받지 못해요.","제3자에 대한 책임은 고의·중과실이 있을 때 부담, 주주의 간접손해는 불포함":"제3자에 대한 책임은 고의·중과실이 있을 때 지며, 주주의 간접손해는 이에 들지 않아요.","제3자의 행위로 손해가 생겨 보험금을 지급한 보험자는 지급한 금액 한도에서 피보험자의 제3자에 대한 권리를 법률상 당연히 취득하고, 제3자의 행위에 귀책사유가 있을 필요는 없으며 대위 범위는 보험목적물의 손해로 한정(제682조)":"보험금을 지급한 보험자는 지급한 금액 한도에서 피보험자의 제3자에 대한 권리를 당연히 취득하는 것이 보험자대위예요.","제공받은 수사기관등이 당사자에게 통지(제83조의2)":"제공받은 수사기관등이 당사자에게 이 사실을 알려야 해요.","제도보장과 원칙규범의 성격도 가짐":"혼인·가족 조항은 제도보장이면서 국가가 지켜야 할 원칙규범이라는 성격도 있습니다.","제소 후 1% 미만으로 줄어도 소 유지, 주식을 전혀 보유하지 않게 되면 원고적격 상실":"제소 후 지분이 1% 미만이 되어도 소를 유지하지만, 주식을 전혀 갖지 않게 되면 원고적격을 잃어요.","제청신청인의 의도와 입법자의 객관적 동기를 참작":"주된 기본권을 고를 때 제청신청인의 의도와 입법자의 객관적 동기를 참작합니다.","제헌헌법은 근로3권을 법률의 범위 내에서 보장":"제헌헌법은 근로3권을 법률의 범위 안에서 보장하는 방식이었어요.","조례에 대한 법률의 위임은 포괄적이어도 됨":"조례에 대해서는 법률의 위임이 포괄적이어도 허용된다는 뜻이에요.","조세인지 부담금인지는 법률상 명칭이 아니라 실질로 판단":"조세인지 부담금인지는 법률에 붙은 이름이 아니라 내용을 보고 구분합니다.","조약의 체결·비준권은 대통령에게 있고 국회는 중요한 조약에 대한 동의권을 가짐":"조약을 맺고 비준하는 일은 대통령 권한이지만, 중요한 조약에는 국회의 동의가 따라야 합니다.","조직화된 인적·물적 조직을 동일성을 유지한 채 일체로 이전":"영업양도는 조직화된 인적·물적 조직을 동일성을 유지한 채 한꺼번에 넘기는 거예요.","존립기간 만료로 해산한 뒤 일부 사원의 동의만으로 회사 계속 가능, 동의하지 않은 사원은 퇴사로 봄":"존립기간이 끝나 해산한 뒤라도 일부 사원이 동의하면 회사를 이어 갈 수 있고, 반대한 사원은 나간 것으로 칩니다.","존속회사가 합병으로 발행하는 신주와 이전하는 자기주식이 발행주식총수의 10% 이하이면":"존속회사가 합병으로 새로 발행하거나 넘겨 주는 주식이 발행주식총수의 10% 이하일 때가 요건입니다.","존속회사나 신설회사가 본점 소재지에서 합병등기를 해야 효력 발생":"합병의 효력은 존속회사나 신설회사가 본점 소재지에서 합병등기를 마칠 때 생깁니다.","존속회사의 주주총회 승인을 이사회 승인으로 갈음 가능, 존속회사 주주에게는 매수청구권 없음":"존속회사 주주총회 승인을 이사회 승인으로 바꿀 수 있고, 그 주주에게는 매수청구권도 주어지지 않습니다.","존속회사 주식 20% 이상 주주가 2주 내에 반대를 통지하면 주주총회를 거침(제527조의3)":"존속회사 주식 20% 이상 주주가 2주 안에 반대를 통지하면 주주총회를 거쳐야 해요.","주권발행 전의 주식양도는 회사에 효력이 없지만 회사성립 후 또는 신주 납입기일 후 6개월이 지나면 지명채권 양도의 원칙에 따라 의사표시만으로 회사에도 효력이 있고, 6개월 전에 한 양도도 그 후 6개월이 지날 때까지 주권이 발행되지 않으면 하자가 치유":"주권 발행 전 주식양도는 회사에 효력이 없지만 회사성립 후 또는 납입기일 후 6개월이 지나면 의사표시만으로 회사에도 효력이 있어요.","주권 발행 후의 주식양도는 주권을 교부해야 효력이 생기고, 교부에는 현실인도 외에 간이인도, 점유개정, 반환청구권 양도도 포함":"주권이 발행된 후의 주식양도는 주권 교부로 효력이 생기고, 간이인도·점유개정·반환청구권 양도도 교부로 봅니다.","주권은 회사가 작성한 문서를 주주에게 교부한 때 효력이 생기고, 법정 기재사항 일부를 빠뜨렸다고 당연히 무효가 되지는 않으며 주권을 잃은 자는 제권판결을 얻어야 재발행을 청구할 수 있음":"주권은 회사가 작성한 문서를 주주에게 교부한 때 효력이 생기고, 분실하면 제권판결을 얻어야 재발행을 청구할 수 있어요.","주민등록번호 변경을 전혀 허용하지 않는 조항도 침해":"주민등록번호를 바꾸는 것을 전혀 허용하지 않는 조항도 개인정보 자기결정권을 침해해요.","주민의 자치권, 주민투표권, 주민소환권은 헌법상 기본권이 아님":"주민의 자치권·주민투표권·주민소환권은 법률상 권리일 뿐, 헌법이 정한 기본권으로 보지는 않아요.","주식매수선택권은 정관에 근거를 두고 주주총회 특별결의로 이사·집행임원·감사·피용자에게 부여하고, 10% 이상 주주, 경영에 사실상 영향력을 행사하는 자, 그 배우자와 직계존비속에게는 부여할 수 없으며 행사로 발행·양도할 주식은 발행주식총수의 10%를 넘지 못함(제340조의2)":"주식매수선택권은 정관 근거와 특별결의로 부여하며, 10% 이상 주주는 대상이 아니고 행사로 발행할 주식도 10%를 넘지 못해요.","주식배당은 주주총회 결의로만 하고 이익배당총액의 2분의 1을 넘지 못하며 중간배당은 연 1회 결산기 회사가 정관에 정한 경우 영업연도 중 1회만 이사회 결의로 할 수 있음":"주식배당은 이익배당총액의 2분의 1을 못 넘고, 중간배당은 정관에 정한 회사가 영업연도 중 1회만 이사회 결의로 할 수 있어요.","주식 수에 따라 다른 비율로 병합하는 차등감자는 주주평등원칙에 어긋나 무효원인이 되고, 이사의 손해배상책임은 감자무효 판결 확정과 별개로 성립":"주식 수에 따라 다르게 병합하는 차등감자는 주주평등원칙 위반으로 무효사유이며, 이사의 배상책임은 판결 확정 여부와 별개입니다.","주식에 질권을 설정할 때도 주권을 교부해야 하고(반환청구권 양도 포함) 질권자는 주권을 계속 점유하지 않으면 제3자에게 대항하지 못함":"주식에 질권을 잡을 때에도 주권을 교부해야 하고, 질권자가 계속 점유하지 않으면 제삼자에게 맞설 수 없습니다.","주식을 취득한 양수인도 회사에 승인을 청구할 수 있고, 주주들 사이에서 양도를 일부 제한하는 약정은 원칙적으로 당사자 사이에서 유효":"주식을 취득한 양수인도 회사에 승인을 구할 수 있고, 주주들끼리 양도를 일부 막기로 한 약정은 당사자 사이에서 통용됩니다.","주식이 실질적으로 분산되어 있으면 지배주주 1인의 의사록만으로 결의를 인정할 수 없음":"주식이 실제로 여럿에게 흩어져 있다면 지배주주 1인이 만든 의사록만으로는 결의를 인정하지 못합니다.","주식회사는 주주가 1인이 되어도 해산하지 않음":"주주가 한 사람만 남았다고 해서 주식회사가 저절로 해산하지는 않습니다.","주식회사 설립의 무효는 주주·이사·감사만 회사성립일부터 2년 안에 소로써 주장할 수 있고(제328조), 하자가 보완되어 무효로 하는 것이 부적당하면 법원은 재량으로 기각할 수 있음":"주식회사 설립무효는 주주·이사·감사만 성립일부터 2년 안에 소로 주장하며, 하자가 보완되면 법원이 재량으로 기각할 수 있어요.","주식회사에서는 노무나 신용을 출자할 수 없고, 현물출자 발기인은 납입기일에 지체 없이 재산을 인도하고 이전 서류를 갖추어 주어야 함":"주식회사 출자에는 노무나 신용이 쓰일 수 없고, 현물출자자는 납입기일에 재산을 넘기고 이전에 필요한 서류까지 줘야 합니다.","주주는 가진 주식 수에 따라 신주를 배정받을 권리가 있고, 회사는 정관에 정한 경우 신기술 도입·재무구조 개선 등 경영상 목적에 필요할 때만 제3자에게 배정할 수 있으며 이때 납입기일 2주 전까지 주주에게 통지·공고해야 함(제418조)":"신주는 보유 주식 수에 비례해 배정받는 것이 기본이고, 제3자 배정은 정관상 경영 목적이 있어야 하며 납입기일 2주 전까지 알려야 합니다.","주주배정인지 제3자배정인지는 지분비율에 따른 인수 기회를 주었는지로 객관적으로 정하고, 주주배정에서 실권된 주식은 정관 근거 없이 이사회 결의로 제3자에게 처분할 수 있음":"주주배정인지는 지분율대로 인수 기회를 줬는지로 가리고, 실권주는 정관 근거 없이 이사회 결의로 제삼자에게 넘길 수 있습니다.","주주 전원의 동의로 면제 가능":"이사의 회사에 대한 책임은 주주 전원의 동의가 있으면 면제할 수 있어요.","주주 전원의 사전 동의 등은 예외, 무효는 회사만 주장 가능":"주주 전원이 사전에 동의한 경우 등은 예외이고, 이 거래의 무효는 회사만 주장할 수 있습니다.","주채무가 상행위로 인한 것이거나 보증이 상행위이면 보증인도 연대책임(제57조)":"주채무가 상행위로 생겼거나 보증 자체가 상행위라면 보증인도 연대하여 책임집니다.","중복보험의 보험자들은 각자 보험금액 한도에서 연대책임을 지고 보험금액 비율로 분담하지만 이 규정은 임의규정이며(제672조), 피보험이익이 다르면 중복보험이 아니고, 통지의무를 게을리한 것만으로 사기가 추정되지 않음":"중복보험의 보험자들은 각자 한도에서 연대책임을 지고 금액 비율로 나눠 부담하며, 피보험이익이 다르면 중복보험이 아닙니다.","중복보험 체결 사실은 고지의무가 아니라 통지의무의 대상이고, 보험모집인에게는 고지를 받을 권한이 없으며 고지의무 위반이 사기이면 민법에 따라 취소할 수도 있음":"중복보험 체결 사실은 고지의무가 아니라 통지의무의 대상이고, 보험모집인에게는 고지를 받을 권한이 없어요.","중추는 공무원의 정치적 중립과 신분보장":"공무원의 정치적 중립과 신분보장이 이 제도를 떠받치는 중추입니다.","중학교 의무교육의 단계적 실시로 무상 혜택을 받지 못하는 지역 주민이 있어도 헌법상 권리 침해가 아님":"중학교 의무교육을 순차적으로 확대하느라 일부 지역이 무상 혜택을 못 받는 것은 권리 침해가 아닙니다.","중혼 취소청구권에 제척기간을 두지 않은 조항은 합헌":"중혼 취소청구권에 제척기간을 정하지 않은 규정은 위헌이 아닙니다.","중혼 취소청구권자에서 직계비속을 뺀 조항은 헌법불합치 결정":"직계비속이 중혼 취소를 청구하지 못하게 한 조항은 헌법불합치 결정을 받았습니다.","즉시 발견할 수 없는 하자는 6개월 안에 발견해 통지해야 함":"바로 드러나지 않는 하자는 6개월 안에 찾아내 통지해야 합니다.","즉시항고 기간 3일은 헌법불합치 결정 후 7일로 늘어남(형사소송법 제405조)":"즉시항고 기간 3일은 헌법불합치 결정을 받아 7일로 늘어났어요.","지급거절증서 작성 후나 작성기간 경과 후의 배서는 지명채권 양도의 효력만 있지만(제20조), 소지인은 통지나 승낙 없이 어음을 제시해 권리를 행사할 수 있음":"지급거절증서 작성 후의 배서는 지명채권 양도의 효력만 있어요.","지급에 조건을 붙인 약속어음과 만기가 발행일보다 앞선 어음은 요건이 모순되어 무효이지만 국내어음으로 인정되면 발행지 기재가 없어도 유효":"조건부 지급 약속어음과 만기가 발행일보다 빠른 어음은 요건이 맞지 않아 무효이지만, 국내어음이면 발행지가 없어도 유효합니다.","지방의회 증인 동행명령장에는 법관의 영장 필요":"지방의회가 증인을 강제로 데려오는 동행명령장에는 법관의 영장이 필요해요.","지방자치단체는 조례로 1천만원 이하의 과태료를 정할 수 있음(지방자치법 제32조 제3항·제34조 제1항)":"지방자치단체는 조례로 1천만원 이하의 과태료 부과를 정할 수 있어요.","지방자치단체는 평등권도 주장할 수 없음":"지방자치단체는 평등권을 내세워 다툴 수도 없습니다.","지방자치단체의 장은 조례안의 일부나 수정에 대한 재의요구를 할 수 없음":"지방자치단체의 장은 조례안 일부만, 또는 수정한 형태로는 재의를 요구할 수 없습니다.","지배인·상호·상업장부·상업등기 규정 적용 안 됨(상법 제9조, 시행령 제2조)":"소상인에게는 지배인·상호·상업장부·상업등기 규정이 적용되지 않아요.","지배인의 선임과 대리권 소멸은 영업소(회사는 본점) 소재지에서 등기(제13조)":"지배인의 선임과 대리권 소멸은 영업소 소재지에서 등기하며, 회사는 본점 소재지에서 해요.","지분 명의신탁을 해지해도 사원총회 특별결의가 있어야 신탁자에게 복귀":"지분의 명의신탁을 풀더라도 사원총회 특별결의가 있어야 지분이 신탁자에게 돌아갑니다.","지분은 다른 사원의 동의 없이 양도할 수 없음":"유한책임회사의 지분은 다른 사원의 동의 없이 양도할 수 없어요.","지역은 양도인의 통상적 영업활동 지역을 기준으로 함":"경업금지가 미치는 지역은 양도인이 평소 영업하던 곳을 기준으로 잡습니다.","지체 없이 면책등기를 하면 책임 없음, 영업임대차에는 유추적용되지 않음":"지체 없이 면책등기를 마치면 책임을 면하지만, 영업임대차에는 같은 논리를 확장하지 않습니다.","직계혈족으로 고쳐짐(민법 제818조)":"민법 제818조는 이를 직계혈족으로 고쳐서 직계비속이 다시 포함됐어요.","직업수행의 자유 제한은 인격발현에 미치는 영향이 작아 더 폭넓게 허용되지만 이때도 심사기준은 자의금지가 아니라 비례원칙":"직업수행의 자유는 제한이 더 넓게 허용되지만 이때도 자의금지가 아니라 비례원칙으로 심사해요.","직업은 생활의 기본적 수요를 충족하기 위한 계속적 소득활동이면 종류를 묻지 않아 대학생의 방학 중 학원강사 활동과 게임 결과물 환전업도 포함되지만 읍·면의 이장은 직업이 아님":"계속적 소득활동이면 직업이므로 학원강사 활동과 게임 결과물 환전업은 해당하지만 이장 일은 아닙니다.","진정소급입법은 원칙적으로 금지, 특단의 사정이 있을 때만 허용":"소급입법 중 완성된 과거 사실을 겨냥하는 진정소급은 원칙적으로 막히고, 예외는 특단의 사정이 있을 때뿐입니다.","진정입법부작위에 대한 헌법소원은 헌법이 명시적으로 입법을 위임했거나 헌법 해석상 국가의 입법의무가 명백히 발생했는데도 입법자가 아무 조치를 하지 않은 경우에만 허용":"진정입법부작위는 헌법상 입법의무가 명백한데도 입법자가 아무 조치도 안 한 경우에만 헌법소원으로 다툴 수 있어요.","집회의 시간·장소·방법·목적을 스스로 정할 권리 포함":"시간·장소·방법·목적을 스스로 정해 집회할 권리까지 포함됩니다.","징계처분이 아니면 정직·감봉 등 불리한 처분을 받지 않음":"징계처분 사유가 없다면 정직이나 감봉 같은 불이익을 줄 수 없습니다.","채권자는 제소권자가 아님(제360조의14)":"교환무효의 소를 낼 자격이 있는 사람 가운데 채권자는 들어 있지 않습니다.","채권자의 재산권과 채무자의 행동자유 충돌도 서열이 아니라 형량과 규범조화로 조정":"채권자취소권 사안에서도 채권자의 재산권과 채무자의 행동자유를 서열 없이 형량과 규범조화로 조정해요.","채무자는 어음 반환과 상환으로만 원인채무를 이행하겠다고 할 수 있고 원인채권만 양수한 자에게도 이를 주장할 수 있으나, 반환을 요구하지 않고 단순히 거절하면 이행지체가 되며, 배서했다는 사실만으로 원인채무를 보증한 것으로 추정되지 않음":"채무자는 어음 반환과 상환으로만 원인채무를 이행하겠다고 주장할 수 있고, 배서했다는 사실만으로 원인채무를 보증한 것으로 추정되지는 않아요.","처리결과가 기대에 미치지 못한다는 이유로 헌법소원 불가":"처리결과가 기대에 못 미친다는 이유로는 헌법소원을 낼 수 없어요.","처벌은 형식적 형벌에 그치지 않고 신체의 자유를 박탈하는 정도의 제재 포함":"처벌이란 형식적 형벌에 한정되지 않고 신체의 자유를 빼앗을 정도의 제재까지 넓게 봅니다.","청구권자가 사망하면 상속인이 청구 가능(형사보상법 제3조·제7조·제8조)":"청구권자가 사망하면 그 상속인이 대신 청구할 수 있어요.","청구기간 1년 조항은 헌법불합치":"청구기간을 1년으로 둔 조항은 헌법불합치로 결정됐어요.","청구기간 종료일부터 30일 안에 협의가 안 되면 회사나 주주가 법원에 결정 청구":"청구기간이 끝난 날부터 30일 안에 합의하지 못하면 회사나 주주가 법원에 가액 결정을 청구합니다.","청산종결등기를 했어도 청산사무가 남아 있으면 그 범위에서 법인격이 존속":"청산종결등기가 끝났어도 아직 처리할 청산사무가 남았다면 그 범위에서는 법인격이 살아 있습니다.","청산 중에는 이사 대신 청산인만이 청산사무를 집행하고 회사를 대표":"회사가 청산 중일 때는 이사가 아닌 청산인이 사무를 집행하고 회사를 대표합니다.","청원권의 주체에는 법인도 포함":"청원은 개인만 하는 것이 아니고 법인도 청원권을 가집니다.","체포·구금된 의원의 석방요구 발의는 재적의원 4분의 1 이상의 연서(국회법 제28조)":"체포·구금된 의원을 풀어 달라는 요구는 재적의원 4분의 1 이상이 연서해야 발의됩니다.","체포·구속된 사람은 즉시 변호인의 조력을 받을 권리":"체포·구속된 사람은 곧바로 변호인의 도움을 받을 권리가 있어요.","체포·구속·압수·수색에는 검사의 신청으로 법관이 발부한 영장 필요":"체포·구속·압수·수색을 하려면 검사가 신청하고 법관이 발부한 영장이 있어야 해요.","체포동의안은 일반 의결정족수로 의결":"체포동의안은 일반 의결정족수인 출석 과반수 찬성으로 의결해요.","초과보험 여부는 계약 당시 가액으로 정하고 감액을 청구할 수 있으며 사기로 체결된 초과보험은 무효이나 보험자는 안 때까지의 보험료를 청구할 수 있고(제669조), 일부보험은 비율로 보상하되 약정이 있으면 보험금액 한도에서 보상":"초과보험은 계약 당시 가액으로 판단해 감액을 청구할 수 있고, 사기로 맺은 초과보험은 무효이며, 일부보험은 비율로 보상해요.","초등교육과 법률이 정하는 교육(헌법 제31조 제2항)":"의무교육은 초등교육에다 법률로 정한 교육을 더해 이루어집니다.","초등교육 외에 어느 범위까지 의무교육으로 할지는 입법자의 형성의 자유에 속함":"초등교육 밖에서 어디까지 의무교육으로 할지는 입법자가 정할 수 있어요.","총사원의 동의로 주식회사로 조직 변경 가능(제287조의43)":"유한책임회사는 총사원의 동의로 주식회사로 조직을 변경할 수 있어요.","총액이나 한도만 정하고 개별 지급액을 이사회에 맡길 수 있음":"보수 총액이나 한도를 정해 두면 개별 지급액을 이사회가 정하도록 맡겨도 됩니다.","총주주의 이익을 보호하고 전체 주주의 이익을 공평하게 대우(제382조의3)":"이사는 총주주의 이익을 보호하고 전체 주주의 이익을 공평하게 대우해야 해요.","최고 없이 자동으로 효력을 잃게 하는 약관은 무효이고, 연체 이전에 생긴 사고의 보험금은 해지 후에도 반환을 구할 수 없으며 해지환급금이 지급되지 않았으면 연체보험료와 약정이자를 내고 부활을 청구할 수 있음":"최고 없이 자동으로 효력을 잃게 하는 약관은 무효이고, 해지환급금이 지급되지 않았으면 연체보험료와 이자를 내고 부활을 청구할 수 있어요.","최저생활보장 입법을 전혀 하지 않은 경우":"최저생활을 보장하는 입법을 전혀 하지 않은 경우가 첫째예요.","최저임금 청구권과 퇴직급여 청구권은 법률로 구체화되는 법률상 권리":"최저임금과 퇴직급여는 법률이 정해 줘야 생기는 권리라서 헌법만으로는 청구할 수 없습니다.","최후 등기 후 5년이 지난 휴면회사는 신고 공고 후 해산한 것으로 봄":"마지막 등기 이후 5년이 지난 휴면회사는 신고를 공고한 뒤 해산한 것으로 간주합니다.","출석의원 과반수의 찬성이 있거나 의장이 국가안전보장을 위해 필요하다고 인정할 때만 비공개 가능":"출석의원 과반수가 찬성하거나 의장이 국가안전보장상 필요하다고 인정할 때만 비공개로 할 수 있어요.","출자의 목적은 재산·노무·신용 어느 것이든 가능, 목적과 가격·평가 표준은 정관의 절대적 기재사항":"출자는 재산, 노무, 신용 무엇으로든 할 수 있고, 출자 목적과 가격 평가 기준은 정관에 반드시 써야 합니다.","출자자는 청산절차를 거치지 않으면 잔여재산을 분배받을 수 없음":"청산절차를 밟지 않고서는 출자자가 남은 재산을 나눠 받을 수 없습니다.","취득한 물건·유가증권·채권은 위탁자와 위탁매매인 또는 그 채권자 사이에서 위탁자의 것(제103조)":"위탁매매로 얻은 물건·유가증권·채권은 위탁자와 위탁매매인(또는 그 채권자) 사이에서는 위탁자의 몫입니다.","취소·무효·부존재 판결은 모두 대세효와 소급효, 청구인낙·화해 불가":"취소·무효·부존재 판결은 모두 제삼자에게 미치고 소급하며, 피고가 청구를 인정하거나 화해할 수 없습니다.","취소의 소는 주주·이사·감사가 결의일부터 2개월 안에 안건별로 제기":"결의취소의 소는 안건 하나하나에 대해 결의일로부터 2개월 안에 주주·이사·감사가 제기해야 합니다.","취소판결 확정 시 그 결의로 선임된 이사들이 정한 대표이사의 행위도 소급하여 대표권 없는 행위":"취소판결이 확정되면 그 결의로 뽑힌 이사들이 정한 대표이사의 행위도 거슬러 올라가 대표권 없는 행위가 됩니다.","취소하지 않아도 하자가 치유되지 않아 보험자는 설명하지 않은 약관을 계약 내용으로 주장할 수 없고, 그 약관에 정한 고지의무 위반을 이유로 해지할 수도 없음":"취소하지 않아도 하자는 치유되지 않아서 보험자는 설명하지 않은 약관을 계약 내용으로 주장할 수 없어요.","취업 체류자격이 없는 외국인 근로자도 노동조합 결성·가입 가능":"취업 체류자격이 없는 외국인 근로자도 노동조합을 결성하고 가입할 수 있어요.","친생부인의 소 제척기간 2년은 합헌":"친생부인의 소 제척기간을 2년으로 둔 것은 합헌이에요.","친일반민족행위 결정은 후손의 인격권을 제한":"친일반민족행위로 결정되면 그 후손의 인격권이 제한됩니다.","타인을 위해 주식을 가진 경우가 아니면 회사는 거부 가능(제368조의2)":"타인을 위해 주식을 가진 경우가 아니면 회사는 불통일행사를 거부할 수 있어요.","타인의 사망을 보험사고로 하는 계약은 체결 시까지 그 타인의 서면동의를 받아야 하고 이 규정은 강행규정이어서 동의는 계약마다 개별적으로 해야 하고 포괄적·묵시적 동의로는 부족하며 무효인 계약은 추인해도 유효해지지 않고 계약자 스스로 무효를 주장할 수 있음(제731조)":"타인의 사망을 보험사고로 하는 계약은 체결 시까지 그 타인의 서면동의를 계약마다 개별로 받아야 하고 무효인 계약은 추인해도 유효해지지 않아요.","탄핵 또는 금고 이상 형의 선고가 아니면 파면되지 않음(헌법 제114조)":"선관위 위원은 탄핵이나 금고 이상 형의 선고가 있어야만 파면됩니다.","탄핵사유의 직무는 법령상 고유업무와 사회통념상 관련 업무를 포함하고, 헌법에는 불문헌법이, 법률에는 조약과 일반적으로 승인된 국제법규가 포함되며, 파면은 이를 정당화할 정도로 중대한 위반이 있을 때만 함":"탄핵사유가 되는 직무는 법령상 고유업무에 사회통념상 관련 업무까지 넓고, 파면은 중대한 위반일 때에만 정당화됩니다.","태아는 생명권의 주체, 초기배아는 기본권 주체성이 인정되지 않음":"생명권은 태아에게까지 주어지지만, 초기배아는 아직 기본권을 가진 주체로 보지 않습니다.","태아도 생명권의 주체이고 국가는 보호할 의무 있음":"태아에게도 생명권이 인정되므로 국가는 태아를 보호할 의무를 집니다.","태어난 즉시 출생등록될 권리는 헌법에 명시되지 않은 독자적 기본권":"출생등록될 권리는 헌법에 쓰여 있지 않지만 독자적으로 인정되는 기본권이에요.","통지하지 않으면 과실이 없어도 해제·대금감액·손해배상 청구 불가(제69조)":"통지하지 않으면 매도인에게 과실이 없어도 해제·대금감액·손해배상을 청구하지 못해요.","퇴직급여와 공무상 재해보상도 보호영역이 아님":"퇴직급여나 공무상 재해보상 문제는 공무담임권이 지켜 주는 범위 밖입니다.","투표소에 수화통역인을 배치하는 법률을 만들 헌법상 작위의무는 없음":"투표소에 수화통역인을 두도록 법을 만들 의무가 헌법에서 나오지는 않습니다.","투하자본 회수를 절대적으로 보장하는 손실보전·수익보장 약정은 주주 전원이 동의해도 무효이지만 허용되는 사전동의권 약정 위반에 대비한 손해배상 약정은 유효할 수 있고, 주주평등원칙은 주주와 다른 주주·이사 개인 사이의 계약에는 직접 적용되지 않음":"투하자본 회수를 절대적으로 보장하는 손실보전·수익보장 약정은 주주 전원이 동의해도 무효예요.","특별이해관계 이사는 의사정족수에는 포함되나 출석이사에는 산입되지 않음":"특별이해관계 이사는 의사정족수에는 들어가지만 출석이사 수에는 넣지 않아요.","특별한 이해관계가 있는 주주는 의결권 행사 불가":"특별한 이해관계가 있는 주주는 그 결의에서 의결권을 행사할 수 없어요.","특별한 정함이 없으면 총사원의 동의 필요":"특별한 정함이 없으면 정관변경에는 총사원의 동의가 필요해요.","특정 상인을 위해 상시 대리·중개를 하는 독립 상인, 경업금지의무를 짐":"대리상은 한 상인을 위해 상시로 대리하거나 중개하며, 같은 영업을 하지 못하는 경업금지의무가 있습니다.","특정 장소나 보직에서 근무할 공무수행의 자유는 보호영역이 아님":"특정 장소나 보직에서 근무할 자유는 공무담임권의 보호영역에 들지 않아요.","특정 지방자치단체의 존속은 보장되지 않음":"특정 지방자치단체가 계속 존재할 권리까지 보장하지는 않습니다.","판결에 영향을 미칠 중요한 사항의 판단누락은 명확성원칙에 어긋나지 않음":"판결에 영향을 줄 중요한 사항을 판단하지 않은 것은 명확성원칙에 어긋나지 않아요.","판결은 언제나 공개(헌법 제109조)":"심리는 비공개로 해도 판결은 언제나 공개해야 해요.","판결은 제3자에게도 효력이 있으나 확정 전에 생긴 권리의무에는 영향 없음":"판결 효력은 제삼자에게도 미치지만, 판결이 확정되기 전에 생긴 권리의무는 건드리지 않습니다.","판례는 이 경우 납입가장죄만 성립하고 업무상횡령죄는 성립하지 않는다고 보며, 납입가장행위는 이사 해임청구 사유인 부정행위나 중대한 법령 위반에 해당":"판례는 납입가장죄만 성립한다고 보고 업무상횡령죄는 부정하며, 납입가장은 이사의 해임청구 사유가 됩니다.","판례는 진정한 양심에 따른 병역거부를 병역법상 정당한 사유로 봄":"진정한 양심에 따른 병역거부는 병역법이 정한 정당한 사유에 해당한다는 판례예요.","판사의 임명과 연임에 대한 동의도 이 정족수로 의결":"판사를 임명하거나 연임시킬 때 필요한 동의도 같은 정족수로 의결합니다.","패소한 주주는 악의인 경우에만 회사에 배상책임":"대표소송에서 패소한 주주는 악의가 있었던 경우에만 회사에 손해를 배상합니다.","평화적·비폭력적 집회만 보호":"집회의 자유는 평화적이고 비폭력적인 집회만 보호해요.","포괄적으로 위임할 수는 없음":"개별 지급액을 이사회에 포괄적으로 위임하는 것은 허용되지 않아요.","표결은 전자투표에 의한 기록표결이 원칙":"표결은 전자투표로 기록을 남기는 기록표결이 원칙이에요.","피보험자가 제3자의 청구를 막기 위해 지출한 방어비용은 보험의 목적에 포함되어 선급을 청구할 수 있고, 같은 사고에 관한 여러 책임보험의 보험금 총액이 배상액을 넘으면 중복보험 규정을 준용":"피보험자가 제3자의 청구를 막으려고 쓴 방어비용도 보험의 목적에 포함되어 선급을 청구할 수 있어요.","피보험자는 보험금으로 전보되지 않은 나머지 손해를 제3자에게 청구할 수 있고 보험금을 손익공제하지 않으며 이미 이전된 부분의 청구권을 포기해도 효력이 없음":"피보험자는 보험금으로 메워지지 않은 나머지 손해를 제3자에게 청구할 수 있고, 이미 이전된 청구권을 포기해도 효력이 없어요.","피위조자는 원칙적으로 책임이 없고 표현대리 규정은 정당한 이유가 있는 직접 상대방에게만 유추적용되며, 위조를 주장하면 소지인이 기명날인의 진정을 증명해야 하고, 변조 전에 기명날인한 자는 원래 문언에 따라 책임":"피위조자는 원칙적으로 책임이 없고, 위조를 주장하면 소지인이 기명날인의 진정을 증명해야 해요.","피해자는 보험금액 한도에서 보험자에게 직접 보상을 청구할 수 있고(제724조 제2항), 이 권리는 보험자가 피보험자의 손해배상채무를 병존적으로 인수한 손해배상청구권이어서 보험금청구권의 3년 시효가 적용되지 않고 지연손해금에는 연 5%의 민사법정이율이 적용되며, 보험자와 피보험자의 채무는 연대채무 관계":"책임보험의 피해자는 보험금액 한도에서 보험자에게 직접 청구할 수 있고, 이 권리에는 보험금청구권의 3년 시효가 적용되지 않아요.","하나의 규제로 여러 기본권이 제한되면 주된 기본권을 중심으로 심사":"경합 심사에서는 규제가 여러 기본권을 제한해도 주된 기본권 하나를 중심으로 판단해요.","학교교육에서는 국가의 교육권한이 독자적 지위":"학교 안 교육에서는 국가가 독자적인 교육 권한을 가집니다.","학교 밖 교육영역에서는 원칙적으로 부모의 교육권이 우위":"학교 밖 교육에서는 국가보다 부모의 교육권이 먼저입니다.","학문·예술·체육·종교·의식·친목·오락·관혼상제·국경행사 집회":"신고 대상에서 빠지는 집회 목적으로 학문, 예술, 체육, 종교, 의식, 친목, 오락, 관혼상제, 국경행사를 듭니다.","학생의 종교의 자유와 학교법인의 종교교육의 자유":"학생의 종교의 자유와 학교법인의 종교교육의 자유가 맞부딪히는 사례예요.","학생의 학습권은 교원의 수업권보다 우월":"학생의 학습권이 교원의 수업권보다 우선합니다.","학원법 위반 벌금형 후 1년간 등록 결격, 의료기관 중복 개설 금지, 안경사의 콘택트렌즈 전자상거래 판매 금지, 제1종 운전면허 시력 요건은 합헌":"학원법 위반 후 1년간 등록 결격, 의료기관 중복 개설 금지, 콘택트렌즈 전자상거래 판매 금지 등은 합헌으로 판단됐어요.","학원의 교습시간만 05:00~22:00로 제한한 조례는 개인과외교습자와의 합리적 차별":"학원에만 교습시간을 05:00~22:00로 제한한 조례는 개인과외교습자와 달리 다룰 합리적 이유가 있습니다.","한 명의 제대군인을 위해 여러 비제대군인의 기회가 박탈될 수 있음":"제대군인 한 명을 위해 비제대군인 여러 명의 합격 기회가 사라질 수 있다는 점도 문제였어요.","한 회계연도를 넘는 지출은 연한을 정해 계속비로 의결":"여러 회계연도에 걸쳐 쓸 돈은 기간을 정해 계속비라는 이름으로 국회에서 의결합니다.","합리적 근거 없는 차별을 금지하는 상대적 평등":"상대적 평등은 합리적 근거가 없는 차별만 금지하고 합리적 차별은 허용한다는 뜻이에요.","합명·합자회사는 사원이 2인 이상이어야 해서 1인 회사가 될 수 없고, 주식회사에는 최저자본금 제한이 없으며 모회사는 자회사 발행주식총수의 50%를 초과하여 가진 회사를 말함":"합명·합자회사는 사원이 2인 이상이어야 해서 1인 회사가 될 수 없고, 주식회사에는 최저자본금 제한이 없어요.","합명·합자회사 설립의 무효는 사원만, 취소는 취소권 있는 자만 주장 가능":"합명·합자회사 설립무효는 사원만, 설립취소는 취소권 있는 사람만 주장할 수 있어요.","합명회사의 내부관계에는 민법의 조합 규정 준용":"합명회사 사원들 사이의 내부관계는 민법의 조합 규정을 준용해서 처리합니다.","합병등기는 보고총회 종결일 등부터 2주 내에 본점 소재지에서 함(제528조)":"합병등기는 본점 소재지에서 보고총회 종결일 등부터 2주 안에 해야 합니다.","합병등기일부터 6개월 안에 소로 주장(제529조)":"합병무효는 합병등기일부터 6개월 안에 소로 주장해야 해요.","합병비율이 현저하게 불공정하면 합병무효의 소로 다툴 수 있음":"합병비율이 현저히 불공정하면 합병무효의 소를 제기해 다툴 수 있습니다.","합병 승인결의일부터 2주 내에 1개월 이상의 기간을 정해 채권자에게 이의를 제출하라고 공고":"합병을 승인한 날부터 2주 안에 채권자는 1개월 이상 이의를 낼 수 있다는 점을 공고해야 합니다.","합병·영업전부 양수, 권리 실행, 단주 처리, 주식매수청구권 행사의 경우에는 배당가능이익과 무관하게 취득할 수 있음(제341조의2)":"합병, 영업전부 양수, 권리 실행, 단주 처리, 주식매수청구권 행사에는 배당가능이익과 관계없이 취득할 수 있어요.","합병하는 회사 중 주식회사·유한회사·유한책임회사가 있으면 존속회사나 신설회사도 그중 하나여야 함(제174조 제2항)":"합병 당사자 중에 주식회사·유한회사·유한책임회사가 있으면 합병 후 존속하거나 신설되는 회사도 그 셋 중 하나여야 합니다.","합의부가 단독판사가 심판할 것으로 결정한 사건은 단독판사가 담당":"합의부가 단독판사에게 맡기기로 결정한 사건은 단독판사가 담당해요.","합자회사에서 판결로 권한을 잃은 무한책임사원은 나중에 유일한 무한책임사원이 되어도":"판결로 권한을 상실한 무한책임사원이 훗날 유일한 무한책임사원이 되더라도 상실한 권한은 되살아나지 않습니다.","합자회사의 유한책임사원은 출자액 한도에서 회사채권자에게 직접·연대하여 책임지고, 간접책임을 지는 것은 주식회사·유한회사의 사원이며, 주주의 책임은 주식 인수가액을 한도로 함":"합자회사의 유한책임사원은 출자액만큼 직접 책임을 지고, 주주는 주식 인수가액 범위에서 간접적으로 책임집니다.","합헌적 해석에는 법문의 뜻을 넘을 수 없다는 문의적 한계와 입법자의 명백한 의지와 목적을 헛되게 할 수 없다는 법목적적 한계가 있음":"합헌적 해석에는 법문의 뜻을 넘지 못하는 한계와 입법 목적을 무력하게 만들지 못하는 한계 두 가지가 있습니다.","합헌적 해석은 법원뿐 아니라 헌법재판소의 임무이기도 하고, 합헌적 한정축소해석과 한정위헌결정은 본질적으로 같은 방법":"합헌적 해석은 법원과 헌법재판소가 함께 하는 일이고, 한정축소해석과 한정위헌결정은 본질이 같습니다.","해산결정은 중앙선거관리위원회가 집행":"해산결정을 실제로 집행하는 기관은 중앙선거관리위원회예요.","해산된 정당의 잔여재산은 국고에 귀속":"해산된 정당에 남은 재산은 국가의 소유로 넘어갑니다.","해산명령이나 해산판결로 해산한 회사는 계속 불가":"해산명령이나 해산판결로 해산한 회사는 다시 계속할 수 없어요.","해산심판에 민사소송 법령을 준용해도 재판청구권 침해 아님":"정당 해산심판에 민사소송 법령을 준용해도 재판청구권을 침해하지 않는다고 봅니다.","해산한 회사는 청산 목적 범위에서 법인격 존속":"해산한 회사는 청산 목적의 범위에서 법인격이 그대로 남아요.","해상운송인의 송하인·수하인에 대한 채권·채무는 청구원인과 상관없이 인도한 날 또는 인도할 날부터 1년 안에 재판상 청구가 없으면 소멸하고(제척기간, 합의로 연장 가능), 운송인 책임 규정은 불법행위책임에도 적용(제814조·제798조)":"해상운송인의 채권·채무는 인도한 날 또는 인도할 날부터 1년 안에 재판상 청구가 없으면 소멸하며, 이는 합의로 연장할 수 있는 제척기간이에요.","해임건의안은 본회의 보고 후 24시간 이후 72시간 이내에 무기명투표로 표결(국회법 제112조)":"해임건의안은 본회의에 보고된 지 24시간이 지난 뒤 72시간 안에 무기명으로 표결합니다.","해임은 특별결의, 정당한 이유 없이 임기 전에 해임하면 손해배상 청구 가능":"해임은 특별결의로 하며, 정당한 이유 없이 임기 전에 해임당한 이사는 손해배상을 청구할 수 있습니다.","행정규칙은 원칙적으로 대상이 아니나 법령보충적 규칙이거나 반복 시행으로 자기구속이 생긴 경우에는 대상이 되고, 명령·규칙이 직접 기본권을 침해하면 헌법소원으로 다툴 수 있음":"행정규칙은 원칙적으로 대상이 아니지만 법령보충적이거나 자기구속이 생기면 대상이 되고, 명령·규칙도 직접 침해하면 다툴 수 있어요.","행정기관 위탁 협회의 건강기능식품 기능성 광고 사전심의는 검열에 해당":"협회가 행정기관 위탁을 받아 건강기능식품 광고를 미리 심의하는 것은 사전검열에 해당합니다.","행정법원의 심판권은 판사 3명의 합의부가 행사":"행정법원의 심판권은 판사 3명으로 이루어진 합의부가 행사해요.","행정절차상 구금 피해자에 대한 형사보상 규정이 없는 것은 진정입법부작위이고, 가정폭력 가해자에 대한 자녀 증명서 교부 제한 규정이 없는 것은 부진정입법부작위이며, 양육비 대지급제나 비의료인 문신시술 자격에 관한 입법의무는 헌법에서 나오지 않음":"행정절차상 구금 피해자의 형사보상 규정이 없는 것은 진정입법부작위이고, 증명서 교부 제한 규정이 없는 것은 부진정입법부작위예요.","허가를 받기 위한 표현물 제출의무, 행정권이 주체인 사전심사":"검열이 되려면 허가용으로 표현물을 제출할 의무와 행정권이 주체인 사전심사가 있어야 해요.","허가받지 않은 표현의 금지, 강제수단":"또 허가받지 않은 표현을 금지하고 이를 강제하는 수단도 있어야 해요.","헌법개정안은 기명투표로 표결":"헌법개정안은 누가 찬성했는지 적는 기명투표로 표결해요.","헌법소원 대상인 공권력 행사도 아님":"헌법소원 대상이 되는 공권력 행사도 아니라고 본 것이에요.","헌법의 교육 조항은 사교육을 금지하는 수권규범이 아님(헌법 제31조 제1항)":"교육 조항은 국가가 사교육을 금지할 수 있다고 허락하는 근거 규범이 아닙니다.","헌법의 지방자치 규정은 제도적 보장":"제도적 보장은 헌법이 지방자치라는 제도 자체를 보호한다는 뜻이에요.","헌법이 특별히 평등을 요구하거나 차별로 관련 기본권이 중대하게 제한되는 경우":"헌법이 특별히 평등을 요구하는 영역이나 차별로 기본권이 크게 제한되는 때가 엄격 심사 대상입니다.","헌법재판소는 법관의 자격을 가진 9인의 재판관으로 구성하고 모두 대통령이 임명하되 3인은 국회가 선출한 사람, 3인은 대법원장이 지명한 사람을 임명하며 국회의 선출권은 헌법재판소 구성에 참여하는 독자적이고 실질적인 권한":"헌법재판소는 재판관 9인으로 구성하고, 국회가 선출한 3인과 대법원장이 지명한 3인도 대통령이 임명해요.","헌법재판소법은 정당해산심판과 권한쟁의심판에 가처분을 명문으로 두고 있고, 헌법소원심판에는 명문 규정이 없지만 가처분이 허용":"정당해산심판과 권한쟁의심판은 가처분이 법에 적혀 있고, 헌법소원심판은 적혀 있지 않아도 허용됩니다.","헌법재판소법 제68조 제2항의 헌법소원으로는 진정입법부작위를 다툴 수 없고, 불완전한 입법이라는 주장은 그 법률이 재판의 전제가 될 때 법률 자체를 다투는 방식으로만 가능":"제68조 제2항 헌법소원으로는 진정입법부작위를 다툴 수 없고, 불완전한 입법은 법률 자체를 다투는 방식으로만 가능해요.","헌법재판소에 위헌 여부를 제청하는 것은 법률에 한함(제107조 제1항)":"법원이 헌법재판소에 위헌 여부를 제청하는 대상은 법률뿐이에요.","헌법 제15조의 직업의 자유는 좁은 의미의 직업선택의 자유와 직업수행의 자유를 포함하고, 주관적 공권이면서 사회적 시장경제질서를 이루는 객관적 법질서의 요소":"직업의 자유는 직업선택의 자유와 직업수행의 자유를 모두 포함하며, 개인의 권리이자 사회적 시장경제질서를 이루는 객관적 질서 요소예요.","헌법 제23조 제3항의 정당한 보상은 피수용재산의 객관적 가치를 완전하게 보상하는 것이고, 공익사업으로 생긴 개발이익은 여기에 포함되지 않음":"정당한 보상은 수용된 재산의 객관적 가치를 완전히 보상하는 것이고, 공익사업으로 생긴 개발이익은 넣지 않아요.","헌재는 두 조항 모두 정치적 표현의 자유 침해로 봄":"헌법재판소는 두 조항이 정치적 표현의 자유를 침해한다고 판단했어요.","헌재는 두 조항을 위헌으로 봄":"헌법재판소가 운전면허 필요적 취소 두 조항을 위헌이라고 결정했어요.","헌재는 선거관리사무가 감사원 직무감찰 대상 행정기관의 사무에 포함되지 않는다고 봄":"헌법재판소는 선거관리사무를 감사원 직무감찰 대상 행정기관의 사무로 보지 않아요.","헌재는 정당설립의 자유 침해로 위헌 결정":"헌법재판소는 정당설립의 자유를 침해한다는 이유로 이 조항을 위헌으로 결정했어요.","헌재는 제공요청 조항이 사후통지 절차를 두지 않아 적법절차원칙에 위배된다고 봄":"헌법재판소는 사후통지 절차가 없어 적법절차원칙에 어긋난다고 봤어요.","헌재는 직권 또는 신청으로 종국결정 선고 시까지 정당의 활동을 정지하는 결정 가능(헌법재판소법 제55조·제57조)":"헌법재판소는 종국결정 전까지 직권이나 신청으로 해당 정당의 활동을 정지시킬 수 있어요.","헌재는 한일어업협정을 국내법과 같은 효력의 조약으로 보았고, 국회 동의를 얻은 마라케쉬협정으로 관세법 위반자의 처벌이 가중되어도 죄형법정주의 위반이 아니라고 봄":"헌법재판소는 국회 동의를 얻은 조약이 국내법과 같은 효력이라 처벌이 가중돼도 죄형법정주의 위반이 아니라고 봤어요.","헌재는 헌법불합치 결정(형사소송법 제424조 제4호)":"헌법재판소는 이 조항에 헌법불합치 결정을 내렸어요.","혁신도시 건설 요구권이나 자동차교체명령을 할 구체적 작위의무는 나오지 않음(헌법 제35조)":"환경권에서 혁신도시 건설 요구권이나 자동차교체명령을 할 구체적 작위의무는 나오지 않아요.","현물출자를 회사 성립 후 매매로 완성하기로 한 약정은 실질이 재산인수여서 정관에 없으면 무효이지만 그것이 사후설립에도 해당하면 주주총회 특별결의로 추인해 유효하게 할 수 있음":"현물출자를 성립 후 매매로 하기로 한 약정은 실질이 재산인수라 정관에 없으면 무효이고, 사후설립이면 특별결의로 추인할 수 있어요.","현물출자와 재산인수는 원칙적으로 법원이 선임한 검사인이 조사해 법원에 보고하지만 그 재산총액이 자본금의 5분의 1과 5천만원을 넘지 않거나 정관 가격이 시세를 넘지 않는 거래소 상장 유가증권이면 조사가 면제(제299조 제2항, 시행령 제7조)":"현물출자와 재산인수는 검사인이 조사하는 것이 원칙이며, 자본금의 5분의 1과 5천만원을 넘지 않으면 조사를 생략합니다.","현재는 즉시항고 가능(같은 법 제20조)":"지금은 보상결정에 즉시항고로 불복할 수 있어요.","현행범인 또는 장기 3년 이상 죄를 범하고 도피·증거인멸 염려가 있는 경우":"현행범이거나 장기 3년 이상 죄를 짓고 도피나 증거인멸 우려가 있으면 영장 없이 체포할 수 있는 예외입니다.","현행범인을 제외하고 회기 중 국회의 동의 없이 체포·구금되지 않음":"국회의원은 현행범인이 아니면 회기 중 국회의 동의 없이 체포·구금되지 않아요.","현행법은 공관의 기능이나 안녕을 침해할 우려가 없으면 집회 허용(같은 법 제11조 제3호)":"공관의 기능이나 안녕을 해칠 우려가 없으면 현행법은 집회를 허용해요.","현행법은 총 연장기간을 1년(일부 범죄 3년)으로 제한(통신비밀보호법 제6조 제8항)":"현행 통신비밀보호법은 통신제한조치 연장을 합쳐 1년으로 제한하고 일부 범죄는 3년까지 허용해요.","혐연권은 생명권까지 연결되어 흡연권보다 상위의 기본권":"혐연권은 생명권과 연결되므로 흡연권보다 더 높은 단계의 기본권으로 취급합니다.","협회 유권해석에 반하는 광고 금지 부분은 법률유보원칙 위반":"협회 유권해석에 어긋나는 광고를 막은 부분은 법률유보원칙을 지키지 못한 규정입니다.","형벌과 함께 보호감호·과태료·성폭력 치료프로그램 이수명령 부과는 위반 아님":"형벌 외에 보호감호, 과태료, 이수명령을 더해도 형벌권을 두 번 쓴 것은 아니라서 이중처벌이 아닙니다.","형벌·부담적 규정은 엄격하게 적용":"형벌이나 국민에게 부담을 주는 규정은 명확성을 엄격하게 따집니다.","형벌 조항에 대한 헌법불합치결정도 위헌결정이어서 잠정적용을 명했더라도 소급하여 효력을 잃고, 위헌결정 전 그 법률에 따라 행위한 공무원에게는 고의·과실이 없어 국가배상책임이 생기지 않음":"형벌 조항의 헌법불합치결정도 위헌결정이라 소급해 효력을 잃으며, 그 법률에 따라 행위한 공무원은 국가배상책임이 없어요.","형법과 같은 구성요건에 법정형만 올린 특가법 조항":"형법과 같은 구성요건에 법정형만 높인 특가법 조항도 평등원칙 위반 사례예요.","형사보상의 정당한 보상은 재산권 보상의 정당한 보상과 같지 않음(헌법 제28조·제23조 제3항)":"형사보상에서 말하는 정당한 보상은 재산권 수용 때의 정당한 보상과 같은 기준이 아닙니다.","형사사법기관의 귀책사유를 따지지 않고 손실을 보상":"형사사법기관에 잘못이 있는지 따지지 않고 손실 자체를 보상해요.","형사재판의 사법권 독립은 법원과 검찰의 분리 요구":"형사재판에서 사법권 독립은 법원과 검찰을 분리하라는 요구를 담고 있어요.","형사재판 중인 사람에 대한 출국금지도 적용 대상 아님":"형사재판 중인 사람의 출국금지에도 영장주의가 적용되지 않아요.","형성판결로 확정되면 대표권도 함께 상실, 본점 소재지에서 등기(제205조)":"형성판결이 확정되면 대표권도 함께 잃고, 본점 소재지에서 등기해요.","형제자매나 직계혈족이 아무 제한 없이 본인의 가족관계 증명서를 발급받게 한 조항은 침해":"형제자매나 직계혈족이 아무 제한 없이 가족관계 증명서를 뗄 수 있게 한 조항은 침해로 판단됐어요.","형해화는 문제 된 행위 시점을, 남용은 채무면탈 등 남용행위 시점을 기준으로 판단하고, 모회사가 자회사 주식을 모두 갖고 임원을 겸한다는 것만으로는 남용이 아님":"형해화는 문제 된 행위가 있던 시점을, 남용은 채무면탈 등이 이뤄진 시점을 기준으로 판단합니다.","혼인과 가족생활을 스스로 결정할 자유를 기본권으로 보장(헌법 제36조 제1항)":"혼인과 가족생활을 스스로 결정할 자유를 기본권으로 보장하는 조항이에요.","혼인 중 여자와 남편 아닌 남자 사이 자녀의 생부 출생신고를 허용하지 않는 조항":"혼인 중인 여자가 남편 아닌 남자와 낳은 자녀를 생부가 출생신고하지 못하게 한 조항이에요.","혼인한 부부에게 불리한 자산소득합산과세와 호주제는 위반(헌법 제36조 제1항)":"혼인한 부부를 불리하게 한 자산소득합산과세와 호주제가 헌법 제36조 제1항을 위반한 사례입니다.","확정기매매는 이행시기가 지나면 상대방이 즉시 이행을 청구하지 않는 한 해제된 것으로 봄":"확정기매매는 기한이 지나도록 상대방이 바로 이행을 청구하지 않으면 계약이 해제된 것으로 취급합니다.","확정 · 대통령이 즉시 공포":"국민투표를 통과하면 대통령이 지체 없이 개정을 공포해 확정합니다.","확정되면 본점 소재지에서 등기, 해산에 준하여 청산":"판결이 확정되면 본점 소재지에 등기하고, 해산한 경우에 준해 청산절차를 밟습니다.","확정된 때부터 5년 이내에 청구":"무죄재판이 확정된 때부터 5년 이내에도 청구해야 해요.","확정판결에 대한 불복이라 상소보다 더 예외적으로 인정":"재심은 확정판결에 불복하는 것이라 상소보다 더 예외적으로만 인정해요.","환경에는 자연환경뿐 아니라 생활환경도 포함":"환경권에서 말하는 환경은 자연환경뿐 아니라 생활환경도 포함해요.","환경영향평가 대상지역 밖 주민도 환경상 이익 침해를 증명하면 처분 취소를 구할 원고적격 인정":"환경영향평가 대상지역 밖에 살아도 환경 이익 침해를 입증하면 취소소송을 낼 자격이 있습니다.","환매권 발생기간을 취득일부터 10년 이내로 제한한 조항은 위헌이고, 개성공단 전면중단 조치는 공용 제한이 아니어서 보상이 없어도 재산권 침해가 아님":"환매권 발생기간을 10년 이내로 제한한 조항은 위헌이며, 개성공단 전면중단 조치는 공용 제한이 아니라 보상 없이도 합헌이에요.","회기 전에 체포된 경우 현행범인이 아니면 국회의 요구로 회기 중 석방(헌법 제44조)":"회기 전에 체포된 의원이 현행범이 아니라면 국회가 요구할 때 회기 중에 풀려납니다.","회기 중 의결되지 못한 의안은 폐기되지 않음":"회기 중 의결되지 못한 의안이라도 회기가 끝났다고 폐기되지는 않아요.","회기 중 확정된 형은 집행 가능":"회기 중 확정된 형은 불체포특권과 무관하게 집행할 수 있어요.","회사가 30일 안에 제소하지 않거나 회복할 수 없는 손해 염려가 있으면 즉시 대표소송 제기":"회사가 30일 안에 소를 제기하지 않거나 회복 못 할 손해가 걱정되면 주주는 곧바로 대표소송을 낼 수 있습니다.","회사가 다른 회사 발행주식총수의 10분의 1을 초과하여 취득하면 지체 없이 그 회사에 통지해야 함":"다른 회사 발행주식총수의 10분의 1을 넘겨 샀다면 지체하지 말고 그 회사에 알려야 합니다.","회사가 명칭 사용을 소극적으로 묵인한 경우, 다른 대표이사의 명칭을 쓴 경우에도 적용":"회사가 명칭 사용을 소극적으로 눈감아 준 경우나 다른 대표이사의 명칭을 쓴 경우도 이 규정의 적용 대상입니다.","회사가 배후자의 개인기업에 불과할 정도로 형해화되었거나 배후자가 법률 적용을 피하려고 법인격을 남용하면 회사의 행위에 대해 배후자에게도 책임을 물을 수 있음":"회사가 배후자의 개인기업에 불과하거나 법인격이 남용되면 배후자에게도 책임을 물을 수 있어요.","회사가 아니면 회사의 영업을 양수해도 상호에 회사임을 표시하지 못함":"회사가 아닌 자는 회사의 영업을 넘겨받아도 상호에 회사라는 표시를 붙일 수 없습니다.","회사가 양도승인 청구일부터 1개월 안에 거부를 통지하지 않으면 승인한 것으로 보고, 거부 통지를 받은 주주는 20일 안에 상대방 지정이나 주식 매수를 청구할 수 있으며 이사회가 2주간 안에 상대방을 지정해 통지하지 않으면 승인한 것으로 봄(제335조의2·제335조의3)":"회사가 양도승인을 청구받고 1개월 안에 거부를 알리지 않으면 승인한 것으로 간주합니다.","회사가 일부 주주에게만 우월한 권리를 주는 약정은 원칙적으로 무효이고, 법률이 허용하는 절차에 따르거나 정당화할 특별한 사정이 있을 때만 허용":"일부 주주만 더 유리하게 대우하는 약정은 기본적으로 무효이며, 정당화할 특별 사정이 있어야 겨우 허용됩니다.","회사가 청구에 따라 제기한 소를 포함해 법원 허가 없이 취하·포기·화해 불가":"회사가 청구에 따라 낸 소를 포함해 법원 허가 없이는 취하·포기·화해를 할 수 없어요.","회사가 회수할 의사 없이 제3자에게 빌려준 돈으로 주식대금을 납입하게 한 것은 자본이 늘지 않아 납입의 효력이 없음":"회사가 회수할 의사 없이 빌려준 돈으로 주식대금을 내게 하면 자본이 늘지 않아 납입의 효력이 없어요.","회사는 거래소 매수나 주식 수에 따른 균등 조건의 방법으로 직전 결산기 배당가능이익 한도 안에서 자기주식을 취득할 수 있고, 미리 주주총회(정관상 이사회 배당이면 이사회) 결의로 종류·수, 총액 한도, 1년 이내의 취득기간을 정해야 하며 차입금으로 취득하는 것도 허용(제341조)":"자기주식 취득은 직전 결산기 배당가능이익 한도 안에서 하며, 미리 주주총회 결의로 취득 조건과 1년 이내의 기간을 정해야 해요.","회사는 상행위를 하지 않아도 상인, 영업을 위한 행위로 추정":"회사는 영업을 위한 존재이므로 상행위를 하지 않아도 상인이고, 회사의 행위는 영업을 위한 것으로 추정합니다.","회사는 주권을 제시한 청구자의 형식적 자격만 심사하면 되고, 양도인은 회사에 양수인 명의로 명의개서를 해 달라고 청구할 권리가 없음":"회사는 주권을 내보인 청구자의 형식적 자격만 확인하면 되고, 양도인에게는 양수인 명의로 바꿔 달라고 청구할 권리가 없습니다.","회사는 청구기간 종료일부터 2개월 안에 매수, 이 2개월은 대금 지급의무의 이행기(제374조의2)":"회사는 청구기간 종료일부터 2개월 안에 사야 하며, 이 기간은 대금 지급 의무의 이행기이기도 합니다.","회사는 합명회사, 합자회사, 유한책임회사, 주식회사, 유한회사의 5종":"회사 형태는 합명회사, 합자회사, 유한책임회사, 주식회사, 유한회사까지 다섯 가지입니다.","회사·모회사·자회사가 다른 회사 주식을 10분의 1 초과하여 가지면 그 다른 회사가 가진 회사·모회사 주식은 모자관계가 아니어도 의결권이 없고(제369조 제3항), 이 요건은 기준일이 아니라 실제 주주총회일을 기준으로 판단":"회사·모회사·자회사가 다른 회사 주식을 10분의 1 넘게 가지면, 그 다른 회사가 가진 이쪽 주식은 의결권이 없어요.","회사성립일부터 2년 안에 소로 주장(제184조)":"설립무효·취소는 회사성립일부터 2년 안에 소로 주장해야 해요.","회사 성립 후 가입한 사원도 가입 전 회사채무에 대해 다른 사원과 같은 책임(제213조)":"회사가 성립한 다음 가입한 사원이라도 가입 전에 생긴 회사채무에 대해 기존 사원과 같은 책임을 집니다.","회사 성립 후 출자 미이행이 발견되면 성립 당시의 사원·이사·감사가 연대하여 지급할 책임":"출자가 이행되지 않은 사실이 회사 성립 뒤 드러나면, 성립 당시의 사원·이사·감사가 함께 지급할 책임을 집니다.","회사와 거래하려면 미리 이사회에서 중요사실을 밝히고 이사 3분의 2 이상의 승인(제398조)":"이사가 회사와 거래하기 전에 이사회에서 중요사실을 밝히고, 이사 3분의 2 이상의 승인을 받아야 합니다.","회사재산으로 채무를 완제할 수 없거나 강제집행이 주효하지 못한 때 연대하여 변제할 책임(제212조)":"회사재산으로 빚을 다 못 갚거나 강제집행이 실패했을 때 사원들이 연대해서 갚을 책임이 생깁니다.","회사채권자에게 직접·연대·무한책임":"합명회사의 사원은 회사채권자에게 직접, 연대하여, 무한으로 책임집니다.","휴면회사로 청산종결이 간주된 회사도 정리할 권리관계가 남아 있으면 그 범위에서 청산인을 둠":"휴면회사가 청산종결로 간주되어도 처리할 권리관계가 남았다면 그 범위 안에서 청산인을 따로 둡니다.","흡연권은 혐연권을 침해하지 않는 한에서 인정":"흡연권은 혐연권을 해치지 않는 한도 안에서만 보호받는 권리입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
